const lessons = [
{num:1,time:"00:00:30,000 --> 00:00:40,100",arabic:"هَارُونُ لَا يَمْلِكُ إِلَّا السَّيْفَ وَالنِّطْعَ يَا ابْنَ الْأَشْرَسِ.",segs:[{ar:"هَارُونُ لَا يَمْلِكُ",uz:"Horunning qo‘lida yo‘q"},{ar:"إِلَّا السَّيْفَ وَالنِّطْعَ",uz:"qilich va qatl to‘shamasidan boshqa narsa"},{ar:"يَا ابْنَ الْأَشْرَسِ",uz:"ey Ibn Ashras"}],full_uz:"Horunning qo‘lida qilich va qatl to‘shamasidan boshqa narsa yo‘q, Ibn Ashras.",note:"النِّطْعُ — qatl paytida yerga yoziladigan charm to‘shama. السَّيْفُ وَالنِّطْعُ bu yerda qatlni anglatadi."},
{num:2,time:"00:00:40,100 --> 00:00:44,500",arabic:"أَنَسِيتَ الْبَرَامِكَةَ يَا رَجُلُ؟",segs:[{ar:"أَنَسِيتَ الْبَرَامِكَةَ",uz:"Barmakiylarni unutdingizmi"},{ar:"يَا رَجُلُ؟",uz:"ey odam?"}],full_uz:"Barmakiylarni unutdingizmi, ey odam?",note:"أَنَسِيتَ = so‘roq hamzasi أَ + نَسِيتَ («unutdingiz»)."},
{num:3,time:"00:00:44,500 --> 00:00:48,939",arabic:"فَهُوَ لَنْ يَتَسَامَحَ مَعَكَ وَمَعَ إِخْوَتِكَ.",segs:[{ar:"فَهُوَ لَنْ يَتَسَامَحَ",uz:"u kechirimli bo‘lmaydi"},{ar:"مَعَكَ وَمَعَ إِخْوَتِكَ",uz:"sizga ham, birodarlaringizga ham"}],full_uz:"U sizga ham, birodarlaringizga ham kechirimli bo‘lmaydi.",note:"تَسَامَحَ مَعَ — «kechirimli bo‘ldi, yon berdi». لَنْ kelasi zamondagi inkorni bildiradi."},
{num:4,time:"00:00:48,939 --> 00:00:52,700",arabic:"أَتَذْهَبُ هَكَذَا يَا ابْنَ الْأَشْرَسِ؟",segs:[{ar:"أَتَذْهَبُ هَكَذَا",uz:"shunday ketaverasizmi"},{ar:"يَا ابْنَ الْأَشْرَسِ؟",uz:"ey Ibn Ashras?"}],full_uz:"Shunday ketaverasizmi, Ibn Ashras?",note:"ذَهَبَ bu kontekstda hayotdan ketishga ishora qilmoqda."},
{num:5,time:"00:00:52,700 --> 00:00:55,679",arabic:"رَخِيصًا غَيْرَ مَأْسُوفٍ عَلَيْهِ.",segs:[{ar:"رَخِيصًا",uz:"qadrsiz holda"},{ar:"غَيْرَ مَأْسُوفٍ عَلَيْهِ",uz:"hech kim afsus chekmaydigan bo‘lib"}],full_uz:"Qadrsiz, ortingizdan hech kim afsus chekmaydigan holda.",note:"مَأْسُوفٌ عَلَيْهِ — «unga afsus chekiladigan». غَيْرُ bu ma’noni inkor qiladi."},
{num:6,time:"00:00:55,679 --> 00:00:57,760",arabic:"لَا دِينًا وَلَا دُنْيَا.",segs:[{ar:"لَا دِينًا",uz:"na din"},{ar:"وَلَا دُنْيَا",uz:"na dunyo"}],full_uz:"Na din, na dunyo.",note:"Oldingi fikrning qisqa davomi: din jihatidan ham, dunyo jihatidan ham foydasiz qolish nazarda tutilgan."},
{num:7,time:"00:00:57,759 --> 00:01:01,579",arabic:"يَجِبُ أَنْ تَحْتَالَ لِنَفْسِكَ.",segs:[{ar:"يَجِبُ أَنْ تَحْتَالَ",uz:"chora topishingiz kerak"},{ar:"لِنَفْسِكَ",uz:"o‘zingiz uchun"}],full_uz:"O‘zingiz uchun chora topishingiz kerak.",note:"اِحْتَالَ bu yerda «hiyla yoki tadbir bilan yo‘l topdi». يَجِبُ أَنْ — «...ish kerak»."},
{num:8,time:"00:01:01,579 --> 00:01:05,759",arabic:"وَإِلَّا فَأَنْتَ امْرُؤٌ هَالِكٌ لَا مَحَالَةَ.",segs:[{ar:"وَإِلَّا",uz:"aks holda"},{ar:"فَأَنْتَ امْرُؤٌ هَالِكٌ",uz:"siz halok bo‘ladigan kishisiz"},{ar:"لَا مَحَالَةَ",uz:"shubhasiz"}],full_uz:"Aks holda, siz shubhasiz halok bo‘lasiz.",note:"لَا مَحَالَةَ — «muqarrar ravishda, albatta». امْرُؤٌ — «kishi, odam»."},
{num:9,time:"00:01:05,759 --> 00:01:12,959",arabic:"أَحْسَنْتَ يَا فَرَجُ.",segs:[{ar:"أَحْسَنْتَ",uz:"yaxshi ish qildingiz"},{ar:"يَا فَرَجُ",uz:"ey Faraj"}],full_uz:"Yaxshi ish qildingiz, Faraj.",note:null},
{num:10,time:"00:01:14,500 --> 00:01:17,060",arabic:"أَخْبَارُكَ كَانَتْ قَيِّمَةً.",segs:[{ar:"أَخْبَارُكَ",uz:"xabarlaringiz"},{ar:"كَانَتْ قَيِّمَةً",uz:"qimmatli edi"}],full_uz:"Xabarlaringiz qimmatli edi.",note:"أَخْبَارٌ g‘ayri oqil ko‘plik bo‘lgani uchun كَانَتْ va قَيِّمَةً birlik muannasda kelgan."},
{num:11,time:"00:01:17,060 --> 00:01:20,539",arabic:"وَيَبْدُو أَنَّكَ فَتًى نَبِيهٌ.",segs:[{ar:"وَيَبْدُو أَنَّكَ",uz:"aftidan, siz"},{ar:"فَتًى نَبِيهٌ",uz:"ziyrak yigitsiz"}],full_uz:"Aftidan, siz ziyrak yigitsiz.",note:"نَبِيهٌ — «ziyrak, fahmli». فَتًى — «yigit»."},
{num:12,time:"00:01:20,539 --> 00:01:22,959",arabic:"أَنَا خَادِمُكَ الْمُطِيعُ يَا مَوْلَايَ.",segs:[{ar:"أَنَا خَادِمُكَ الْمُطِيعُ",uz:"men sizning itoatkor xizmatkoringizman"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Men sizning itoatkor xizmatkoringizman, hukmdorim.",note:null},
{num:13,time:"00:01:27,760 --> 00:01:34,160",arabic:"اِسْمَعْ يَا فَرَجُ.",segs:[{ar:"اِسْمَعْ",uz:"eshiting"},{ar:"يَا فَرَجُ",uz:"ey Faraj"}],full_uz:"Eshiting, Faraj.",note:null},
{num:14,time:"00:01:34,160 --> 00:01:35,680",arabic:"لَبَّيْكَ يَا مَوْلَايَ.",segs:[{ar:"لَبَّيْكَ",uz:"labbay"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Labbay, hukmdorim.",note:"لَبَّيْكَ — chaqiriqqa tayyorlik va itoat bilan beriladigan javob."},
{num:15,time:"00:01:35,680 --> 00:01:37,420",arabic:"مُنْذُ الْيَوْمِ...",segs:null,full_uz:"Bugundan boshlab...",note:null},
{num:16,time:"00:01:37,420 --> 00:01:40,000",arabic:"عَلَاقَتُكَ بِي شَخْصِيًّا.",segs:[{ar:"عَلَاقَتُكَ بِي",uz:"aloqangiz men bilan bo‘ladi"},{ar:"شَخْصِيًّا",uz:"shaxsan"}],full_uz:"Bevosita mening o‘zim bilan aloqada bo‘lasiz.",note:"شَخْصِيًّا — «shaxsan, bevosita o‘zi»."},
{num:17,time:"00:01:40,000 --> 00:01:43,320",arabic:"لَا أُرِيدُ صَغِيرَةً وَلَا كَبِيرَةً...",segs:[{ar:"لَا أُرِيدُ",uz:"istamayman"},{ar:"صَغِيرَةً وَلَا كَبِيرَةً",uz:"kichik ham, katta ham biror ishni"}],full_uz:"Kichik ham, katta ham biror ishning...",note:"صَغِيرَةً وَلَا كَبِيرَةً — «mayda-yirik hech bir narsa». Gapning davomi keyingi bandlarda."},
{num:18,time:"00:01:43,320 --> 00:01:45,780",arabic:"فِي زَاوِيَةٍ مِنْ زَوَايَا بَغْدَادَ...",segs:[{ar:"فِي زَاوِيَةٍ",uz:"biror burchakda"},{ar:"مِنْ زَوَايَا بَغْدَادَ",uz:"Bag‘dodning burchaklaridan"}],full_uz:"Bag‘dodning biror burchagida...",note:"زَوَايَا — زَاوِيَةٌ («burchak»)ning ko‘pligi."},
{num:19,time:"00:01:45,780 --> 00:01:47,960",arabic:"أَنْ تَغِيبَ عَنْ أُذُنِكَ وَبَصَرِكَ.",segs:[{ar:"أَنْ تَغِيبَ",uz:"chetda qolishini"},{ar:"عَنْ أُذُنِكَ وَبَصَرِكَ",uz:"qulog‘ingiz va ko‘zingizdan"}],full_uz:"Qulog‘ingiz va ko‘zingizdan chetda qolishini istamayman.",note:"غَابَ عَنْ — «...dan yashirin qoldi, chetda qoldi». Oldingi ikki band bilan bir gapni tashkil qiladi."},
{num:20,time:"00:01:47,960 --> 00:01:52,740",arabic:"نَعْلَمُ أَنَّكَ تَعْمَلُ صَانِعًا...",segs:[{ar:"نَعْلَمُ أَنَّكَ",uz:"bilamizki, siz"},{ar:"تَعْمَلُ صَانِعًا",uz:"hunarmand bo‘lib ishlaysiz"}],full_uz:"Hunarmand bo‘lib ishlashingizni bilamiz...",note:null},
{num:21,time:"00:01:52,740 --> 00:01:54,140",arabic:"عِنْدَ الْفَارِسِيِّ بِهْزَادَ.",segs:null,full_uz:"Fors Behzodning qo‘lida.",note:null},
{num:22,time:"00:01:54,140 --> 00:01:55,360",arabic:"صَانِعًا لِلسُّرُوجِ.",segs:null,full_uz:"Egar yasovchi bo‘lib.",note:"سُرُوجٌ — سَرْجٌ («egar»)ning ko‘pligi."},
{num:23,time:"00:01:55,359 --> 00:01:59,180",arabic:"وَيَضُمُّكَ وَأُمَّكَ بَيْتٌ مُتَوَاضِعٌ.",segs:[{ar:"وَيَضُمُّكَ وَأُمَّكَ",uz:"siz bilan onangizni bag‘riga olgan"},{ar:"بَيْتٌ مُتَوَاضِعٌ",uz:"oddiy bir uy"}],full_uz:"Siz bilan onangiz oddiy bir uyda yashaysizlar.",note:"ضَمَّ — «bag‘riga oldi, o‘z ichiga oldi». مُتَوَاضِعٌ uy haqida «oddiy, kamtarona» degani."},
{num:24,time:"00:01:59,180 --> 00:02:07,060",arabic:"عَيْنٌ وَاحِدَةٌ لَا تَكْفِي يَا فَرَجُ.",segs:[{ar:"عَيْنٌ وَاحِدَةٌ لَا تَكْفِي",uz:"bitta ko‘z yetmaydi"},{ar:"يَا فَرَجُ",uz:"ey Faraj"}],full_uz:"Bitta ko‘z yetmaydi, Faraj.",note:"عَيْنٌ bu yerda «kuzatuvchi, xufiya» ma’nosiga ham ishora qiladi."},
{num:25,time:"00:02:10,180 --> 00:02:19,039",arabic:"اِعْلَمْ أَنَّ فِي بَغْدَادَ كَثِيرِينَ مِنْ عُيُونِنَا سِوَاكَ.",segs:[{ar:"اِعْلَمْ",uz:"bilib qo‘ying"},{ar:"أَنَّ فِي بَغْدَادَ كَثِيرِينَ",uz:"Bag‘dodda ko‘p kishilar borligini"},{ar:"مِنْ عُيُونِنَا سِوَاكَ",uz:"sizdan boshqa xufiyalarimizdan"}],full_uz:"Bilib qo‘ying, Bag‘dodda sizdan boshqa xufiyalarimiz ham ko‘p.",note:"عُيُونٌ — «ko‘zlar»; ko‘chma ma’noda «xufiyalar». سِوَاكَ — «sizdan boshqa»."},
{num:26,time:"00:02:19,039 --> 00:02:21,680",arabic:"وَلَكِنَّنِي أَعْتَرِفُ أَمَامَكَ...",segs:[{ar:"وَلَكِنَّنِي أَعْتَرِفُ",uz:"lekin men tan olaman"},{ar:"أَمَامَكَ",uz:"oldingizda"}],full_uz:"Lekin oldingizda tan olaman...",note:null},
{num:27,time:"00:02:21,680 --> 00:02:27,000",arabic:"أَنَّكَ كُنْتَ أَكْثَرَهُمْ دَهَاءً وَمَكْرًا وَاقْتِنَاصًا.",segs:[{ar:"أَنَّكَ كُنْتَ أَكْثَرَهُمْ",uz:"siz ularning eng ustuni bo‘ldingiz"},{ar:"دَهَاءً وَمَكْرًا",uz:"ziyraklik va ayyorlikda"},{ar:"وَاقْتِنَاصًا",uz:"hamda imkoniyatni tutishda"}],full_uz:"Ziyraklik, ayyorlik va imkoniyatni tutishda siz ularning eng ustuni bo‘ldingiz.",note:"دَهَاءً، مَكْرًا، اقْتِنَاصًا ustunlikning qaysi jihatdan ekanini bildiradi. اِقْتِنَاصٌ — «ovlash, qulay fursatni tutish»."},
{num:28,time:"00:02:27,000 --> 00:02:33,460",arabic:"وَيَبْدُو أَنَّ أَيَّامًا سَعِيدَةً تَنْتَظِرُكَ إِنْ بَقِيتَ عَلَى إِخْلَاصِكَ وَتَفَانِيكَ.",segs:[{ar:"وَيَبْدُو أَنَّ أَيَّامًا سَعِيدَةً تَنْتَظِرُكَ",uz:"aftidan, sizni baxtli kunlar kutmoqda"},{ar:"إِنْ بَقِيتَ",uz:"agar davom etsangiz"},{ar:"عَلَى إِخْلَاصِكَ وَتَفَانِيكَ",uz:"sadoqatingiz va fidoyiligingizda"}],full_uz:"Sadoqat va fidoyiligingizni saqlasangiz, aftidan, sizni baxtli kunlar kutmoqda.",note:"تَفَانٍ — «fidoyilik, o‘zini butunlay bag‘ishlash». تَفَانِيكَ — «sizning fidoyiligingiz»."},
{num:29,time:"00:02:33,460 --> 00:02:38,680",arabic:"أَيَّامُ سَعَادَتِكَ قَادِمَةٌ يَا فَرَجُ، فَأَثْبِتْ لِي ذَلِكَ.",segs:[{ar:"أَيَّامُ سَعَادَتِكَ قَادِمَةٌ",uz:"baxtli kunlaringiz kelmoqda"},{ar:"يَا فَرَجُ",uz:"ey Faraj"},{ar:"فَأَثْبِتْ لِي ذَلِكَ",uz:"bas, menga buni isbotlang"}],full_uz:"Baxtli kunlaringiz kelmoqda, Faraj. Bas, menga buni isbotlang.",note:"أَثْبَتَ — «isbotladi»; أَثْبِتْ — uning buyruq shakli."},
{num:30,time:"00:02:39,700 --> 00:02:43,379",arabic:"وَعَلِمْتَ أَنَّ الْمَرِيسِيَّ فَرَّ مِنْ بَيْنِ أَيْدِينَا.",segs:[{ar:"وَعَلِمْتَ أَنَّ الْمَرِيسِيَّ",uz:"Marisiyning ...ganini bildingiz"},{ar:"فَرَّ مِنْ بَيْنِ أَيْدِينَا",uz:"qo‘limizdan qochib ketganini"}],full_uz:"Marisiyning qo‘limizdan qochib ketganini bildingiz.",note:"مِنْ بَيْنِ أَيْدِينَا — «qo‘limizdan, ko‘z oldimizdan»."},
{num:31,time:"00:02:43,379 --> 00:02:47,680",arabic:"وَأَنَّنَا نَعْمَلُ عَلَى الْوُصُولِ إِلَيْهِ.",segs:[{ar:"وَأَنَّنَا نَعْمَلُ",uz:"va harakat qilayotganimizni"},{ar:"عَلَى الْوُصُولِ إِلَيْهِ",uz:"uni topishga"}],full_uz:"Va uni topishga harakat qilayotganimizni.",note:"عَمِلَ عَلَى + masdar — «bir ishni amalga oshirishga harakat qildi»."},
{num:32,time:"00:02:48,200 --> 00:02:50,780",arabic:"أَنَا خَادِمُكَ يَا مَوْلَايَ.",segs:[{ar:"أَنَا خَادِمُكَ",uz:"men sizning xizmatkoringizman"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Men sizning xizmatkoringizman, hukmdorim.",note:null},
{num:33,time:"00:02:51,680 --> 00:02:56,560",arabic:"أَنْتَ ثُمَامَةُ بْنُ الْأَشْرَسِ الْمُعْتَزِلِيُّ؟",segs:[{ar:"أَنْتَ ثُمَامَةُ بْنُ الْأَشْرَسِ",uz:"siz Sumoma ibn Ashrasmisiz"},{ar:"الْمُعْتَزِلِيُّ؟",uz:"mu’taziliy?"}],full_uz:"Siz mu’taziliy Sumoma ibn Ashrasmisiz?",note:null},
{num:34,time:"00:02:56,560 --> 00:03:01,960",arabic:"بَلْ ثُمَامَةُ بْنُ الْأَشْرَسِ النُّمَيْرِيُّ، خَادِمُ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"بَلْ ثُمَامَةُ بْنُ الْأَشْرَسِ النُّمَيْرِيُّ",uz:"yo‘q, Sumoma ibn Ashras Numayriyman"},{ar:"خَادِمُ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining xizmatkori"}],full_uz:"Yo‘q, mo‘minlar amirining xizmatkori Sumoma ibn Ashras Numayriyman.",note:"بَلْ oldingi ta’rifni tuzatib, uning o‘rniga boshqasini keltiradi."},
{num:35,time:"00:03:01,960 --> 00:03:08,020",arabic:"مَا تَقُولُ فِي كِتَابِ اللَّهِ يَا نُمَيْرِيُّ؟",segs:[{ar:"مَا تَقُولُ",uz:"nima deysiz"},{ar:"فِي كِتَابِ اللَّهِ",uz:"Allohning Kitobi haqida"},{ar:"يَا نُمَيْرِيُّ؟",uz:"ey Numayriy?"}],full_uz:"Allohning Kitobi haqida nima deysiz, Numayriy?",note:null},
{num:36,time:"00:03:08,020 --> 00:03:10,620",arabic:"أَقُولُ إِنَّهُ كَلَامُ اللَّهِ.",segs:[{ar:"أَقُولُ",uz:"aytamanki"},{ar:"إِنَّهُ كَلَامُ اللَّهِ",uz:"u Allohning kalomidir"}],full_uz:"U Allohning kalomidir, deyman.",note:null},
{num:37,time:"00:03:10,620 --> 00:03:22,879",arabic:"أَهُوَ مَخْلُوقٌ يَا ابْنَ الْأَشْرَسِ؟",segs:[{ar:"أَهُوَ مَخْلُوقٌ",uz:"u yaratilganmi"},{ar:"يَا ابْنَ الْأَشْرَسِ؟",uz:"ey Ibn Ashras?"}],full_uz:"U yaratilganmi, Ibn Ashras?",note:"مَخْلُوقٌ — خَلَقَ fe’lining ismi maf’uli: «yaratilgan»."},
{num:38,time:"00:03:22,879 --> 00:03:25,800",arabic:"الْعِيَاذُ بِاللَّهِ مِنْ مَقَالَةٍ كَهَذِهِ.",segs:[{ar:"الْعِيَاذُ بِاللَّهِ",uz:"Allohdan panoh so‘rayman"},{ar:"مِنْ مَقَالَةٍ كَهَذِهِ",uz:"bunday gapdan"}],full_uz:"Bunday gapdan Allohdan panoh so‘rayman.",note:"الْعِيَاذُ بِاللَّهِ — «Allohdan panoh so‘rash». مَقَالَةٌ bu yerda «gap, qarash»."},
{num:39,time:"00:03:25,800 --> 00:03:27,040",arabic:"تَتَعَوَّذُ بِاللَّهِ؟",segs:null,full_uz:"Allohdan panoh so‘rayapsizmi?",note:null},
{num:40,time:"00:03:27,040 --> 00:03:29,360",arabic:"أَلَسْتَ مُعْتَزِلِيًّا؟",segs:null,full_uz:"Mu’taziliy emasmisiz?",note:"أَلَسْتَ — «siz ... emasmisiz?». مُعْتَزِلِيًّا — لَيْسَ ning mansub xabari."},
{num:41,time:"00:03:29,360 --> 00:03:30,900",arabic:"لَا، وَالْحَمْدُ لِلَّهِ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"وَالْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"}],full_uz:"Yo‘q, Allohga hamd bo‘lsin.",note:null},
{num:42,time:"00:03:30,900 --> 00:03:34,400",arabic:"وَلَكِنْ إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ أَنَّنِي مُعْتَزِلِيٌّ...",segs:[{ar:"وَلَكِنْ إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ",uz:"lekin mo‘minlar amiri shunday deb bilsalar"},{ar:"أَنَّنِي مُعْتَزِلِيٌّ",uz:"mening mu’taziliy ekanimni"}],full_uz:"Lekin mo‘minlar amiri meni mu’taziliy deb bilsalar...",note:"رَأَى bu yerda «ko‘rdi» emas, «deb bildi, hisob qildi» ma’nosida."},
{num:43,time:"00:03:34,400 --> 00:03:38,360",arabic:"فَأَنَا مُعْتَزِلِيٌّ رَغْمَ أَنَّنِي لَسْتُ مُعْتَزِلِيًّا.",segs:[{ar:"فَأَنَا مُعْتَزِلِيٌّ",uz:"unda men mu’taziliyman"},{ar:"رَغْمَ أَنَّنِي لَسْتُ مُعْتَزِلِيًّا",uz:"garchi mu’taziliy bo‘lmasam ham"}],full_uz:"Mu’taziliy bo‘lmasam ham, unda men mu’taziliyman.",note:"رَغْمَ أَنَّ — «garchi ... bo‘lsa ham». Gapda ataylab qarama-qarshi fikrlar qo‘llangan."},
{num:44,time:"00:03:38,360 --> 00:03:40,360",arabic:"أَوَتَحْفَظُ قَوْلَهُ تَعَالَى؟",segs:[{ar:"أَوَتَحْفَظُ قَوْلَهُ",uz:"Uning so‘zini yod bilasizmi"},{ar:"تَعَالَى؟",uz:"U yuksakdir?"}],full_uz:"Alloh taoloning ushbu so‘zini yod bilasizmi?",note:"حَفِظَ bu yerda «yod oldi, yoddan bildi». تَعَالَى — Allohni ulug‘lovchi ibora."},
{num:45,time:"00:03:40,360 --> 00:03:45,040",arabic:"آلْآنَ وَقَدْ عَصَيْتَ قَبْلُ وَكُنْتَ مِنَ الْمُفْسِدِينَ.",segs:[{ar:"آلْآنَ",uz:"endi-ya?"},{ar:"وَقَدْ عَصَيْتَ قَبْلُ",uz:"holbuki, ilgari osiylik qilgandingiz"},{ar:"وَكُنْتَ مِنَ الْمُفْسِدِينَ",uz:"va buzg‘unchilardan bo‘lgandingiz"}],full_uz:"Endi-ya? Holbuki, ilgari osiylik qilgan va buzg‘unchilardan bo‘lgan edingiz.",note:"آلْآنَ inkor va tanbeh ohangidagi savol: «Endimi?». قَبْلُ — «ilgari»."},
{num:46,time:"00:03:45,040 --> 00:03:47,960",arabic:"أَوَتُنْكِرُ اعْتِزَالَكَ الْآنَ إِذَنْ؟",segs:[{ar:"أَوَتُنْكِرُ اعْتِزَالَكَ",uz:"mu’taziliyligingizni inkor qilyapsizmi"},{ar:"الْآنَ إِذَنْ؟",uz:"endi, demak?"}],full_uz:"Demak, endi mu’taziliyligingizni inkor qilyapsizmi?",note:"اِعْتِزَالٌ bu kontekstda mu’tazila yo‘nalishiga mansublikni bildiradi."},
{num:47,time:"00:03:47,960 --> 00:03:53,680",arabic:"لَوْ كُنْتُ مُعْتَزِلِيًّا لَأَنْكَرْتُ ذَلِكَ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"لَوْ كُنْتُ مُعْتَزِلِيًّا",uz:"agar mu’taziliy bo‘lganimda"},{ar:"لَأَنْكَرْتُ ذَلِكَ",uz:"buni inkor qilgan bo‘lardim"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Mu’taziliy bo‘lganimda ham buni inkor qilgan bo‘lardim, ey mo‘minlar amiri.",note:"لَوْ ... لَـ ... — faraziy shart va uning javobi."},
{num:48,time:"00:03:53,680 --> 00:03:55,880",arabic:"فَكَيْفَ وَأَنَا لَسْتُ كَذَلِكَ؟",segs:[{ar:"فَكَيْفَ",uz:"unda qanday bo‘lsin"},{ar:"وَأَنَا لَسْتُ كَذَلِكَ؟",uz:"men bunday bo‘lmaganim holda?"}],full_uz:"Men aslida bunday bo‘lmasam, qanday qilib inkor qilmay?",note:"فَكَيْفَ وَأَنَا... — oldingi fikrni kuchaytiruvchi qisqa qurilish: «men ... bo‘lsam, yana qanday?»."},
{num:49,time:"00:03:55,880 --> 00:04:00,640",arabic:"لِمَ تُتْعِبُ نَفْسَكَ يَا مَوْلَايَ مَعَ مُرَاوِغٍ يَرُوغُ مِنْكَ كَمَا يَرُوغُ الثَّعْلَبُ؟",segs:[{ar:"لِمَ تُتْعِبُ نَفْسَكَ",uz:"nega o‘zingizni qiynaysiz"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"},{ar:"مَعَ مُرَاوِغٍ",uz:"bir ayyor bilan"},{ar:"يَرُوغُ مِنْكَ",uz:"sizdan chap beradigan"},{ar:"كَمَا يَرُوغُ الثَّعْلَبُ؟",uz:"tulki chap bergandek?"}],full_uz:"Hukmdorim, sizdan tulkidek chap beradigan ayyor bilan nega o‘zingizni qiynaysiz?",note:"رَاغَ — يَرُوغُ — «chap berdi, ayyorlik bilan chetlab o‘tdi». مُرَاوِغٌ — gapdan qochadigan ayyor."},
{num:50,time:"00:04:00,640 --> 00:04:03,460",arabic:"دَعِ السِّيَاطَ تَجُرُّ لِسَانَهُ يَا مَوْلَايَ.",segs:[{ar:"دَعِ السِّيَاطَ",uz:"qamchilarga qo‘yib bering"},{ar:"تَجُرُّ لِسَانَهُ",uz:"uning tilini tortsin"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Uni qamchilar gapirtirsin, hukmdorim.",note:"سِيَاطٌ — سَوْطٌ («qamchi»)ning ko‘pligi. تَجُرُّ لِسَانَهُ so‘zma-so‘z «tilini tortadi», ya’ni gapirtiradi."},
{num:51,time:"00:04:03,460 --> 00:04:07,640",arabic:"إِنْ كَانَ الْأَمْرُ عَائِدًا لِلسِّيَاطِ، وَزِيرَ أَمِيرِ الْمُؤْمِنِينَ...",segs:[{ar:"إِنْ كَانَ الْأَمْرُ عَائِدًا لِلسِّيَاطِ",uz:"agar ish qamchilarga bog‘liq bo‘lsa"},{ar:"وَزِيرَ أَمِيرِ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amirining vaziri"}],full_uz:"Agar ish qamchilarga bog‘liq bo‘lsa, ey mo‘minlar amirining vaziri...",note:"وَزِيرَ — يَا tushirilgan munodo; izofali bo‘lgani uchun mansub."},
{num:52,time:"00:04:07,640 --> 00:04:13,020",arabic:"فَسَأَعْتَرِفُ بِأَنَّنِي مِنْ قَتَلَةِ أَمِيرِ الْمُؤْمِنِينَ عُمَرَ بْنِ الْخَطَّابِ.",segs:[{ar:"فَسَأَعْتَرِفُ بِأَنَّنِي",uz:"unda men ... ekanimni tan olaman"},{ar:"مِنْ قَتَلَةِ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining qotillaridan"},{ar:"عُمَرَ بْنِ الْخَطَّابِ",uz:"Umar ibn Xattobning"}],full_uz:"Unda mo‘minlar amiri Umar ibn Xattobning qotillaridan ekanimni ham tan olaman.",note:"قَتَلَةٌ — قَاتِلٌ («qotil»)ning ko‘pligi. So‘zlovchi gapini mubolag‘a orqali ifodalamoqda."},
{num:53,time:"00:04:13,020 --> 00:04:16,139",arabic:"أَيُّهَا الْمَارِقُ!",segs:null,full_uz:"Ey yo‘ldan chiqqan!",note:"مَارِقٌ — «chiqib ketgan»; bu kontekstda dindan yoki itoatdan chiqqan kishiga aytilgan."},
{num:54,time:"00:04:16,139 --> 00:04:18,300",arabic:"عَلَى رِسْلِكَ يَا أَبَا الْعَبَّاسِ.",segs:[{ar:"عَلَى رِسْلِكَ",uz:"shoshilmang, o‘zingizni bosing"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"O‘zingizni bosing, Abu Abbos.",note:"عَلَى رِسْلِكَ — «shoshilmang, sekinroq, o‘zingizni bosing»."},
{num:55,time:"00:04:19,800 --> 00:04:21,460",arabic:"اُعْذُرْنِي يَا مَوْلَايَ.",segs:[{ar:"اُعْذُرْنِي",uz:"meni kechiring"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Meni kechiring, hukmdorim.",note:null},
{num:56,time:"00:04:21,460 --> 00:04:33,340",arabic:"فَمَا تَقُولُ فِي رُؤْيَةِ اللَّهِ فِي الْآخِرَةِ يَا ثُمَامَةُ؟",segs:[{ar:"فَمَا تَقُولُ",uz:"unda nima deysiz"},{ar:"فِي رُؤْيَةِ اللَّهِ",uz:"Allohni ko‘rish haqida"},{ar:"فِي الْآخِرَةِ",uz:"oxiratda"},{ar:"يَا ثُمَامَةُ؟",uz:"ey Sumoma?"}],full_uz:"Oxiratda Allohni ko‘rish haqida nima deysiz, Sumoma?",note:"رُؤْيَةٌ — «ko‘rish». رُؤْيَا esa odatda tushda ko‘rilgan narsani bildiradi."},
{num:57,time:"00:04:33,339 --> 00:04:40,239",arabic:"أَقُولُ إِنَّ النَّاسَ جَمِيعًا سَيَرَوْنَهُ، حَتَّى بَشَّارُ بْنُ بُرْدٍ.",segs:[{ar:"أَقُولُ إِنَّ النَّاسَ جَمِيعًا",uz:"aytamanki, barcha odamlar"},{ar:"سَيَرَوْنَهُ",uz:"Uni ko‘radilar"},{ar:"حَتَّى بَشَّارُ بْنُ بُرْدٍ",uz:"hatto Bashshor ibn Burd ham"}],full_uz:"Barcha odamlar Uni ko‘radilar, hatto Bashshor ibn Burd ham, deyman.",note:"سَيَرَوْنَهُ — «ular Uni ko‘radilar». حَتَّى bu yerda «hatto» ma’nosida."},
{num:58,time:"00:04:40,239 --> 00:04:46,439",arabic:"قَتَلَكَ اللَّهُ يَا ثُمَامَةُ!",segs:[{ar:"قَتَلَكَ اللَّهُ",uz:"Alloh joningizni olsin"},{ar:"يَا ثُمَامَةُ",uz:"ey Sumoma"}],full_uz:"Alloh joningizni olsin, Sumoma!",note:"Bu ibora ohangga qarab haqiqiy qarg‘ish yoki hazil aralash hayrat bo‘lishi mumkin."},
{num:59,time:"00:04:59,439 --> 00:05:01,839",arabic:"مَا الَّذِي فَعَلَهُ هَارُونُ بِإِخْوَتِنَا؟",segs:[{ar:"مَا الَّذِي فَعَلَهُ هَارُونُ",uz:"Horun nima qildi"},{ar:"بِإِخْوَتِنَا؟",uz:"birodarlarimizni?"}],full_uz:"Horun birodarlarimizni nima qildi?",note:null},
{num:60,time:"00:05:01,839 --> 00:05:03,839",arabic:"اِسْمَعْ أَيُّهَا الْأَحْمَقُ.",segs:[{ar:"اِسْمَعْ",uz:"eshiting"},{ar:"أَيُّهَا الْأَحْمَقُ",uz:"ey ahmoq"}],full_uz:"Eshiting, ey ahmoq.",note:null},
{num:61,time:"00:05:03,839 --> 00:05:06,839",arabic:"أُقْسِمُ إِنْ بَقِيتَ تُسَمِّيهِمْ إِخْوَتَكَ...",segs:[{ar:"أُقْسِمُ",uz:"qasam ichaman"},{ar:"إِنْ بَقِيتَ تُسَمِّيهِمْ إِخْوَتَكَ",uz:"ularni birodarlaringiz deb atashda davom etsangiz"}],full_uz:"Qasam ichaman, ularni birodarlaringiz deb atashda davom etsangiz...",note:"بَقِيَ + muzoriy fe’l — bir ishda davom etishni bildiradi."},
{num:62,time:"00:05:06,839 --> 00:05:09,839",arabic:"لَأَزُجَّنَّ بِكَ فِي السِّجْنِ بِيَدَيَّ هَاتَيْنِ.",segs:[{ar:"لَأَزُجَّنَّ بِكَ",uz:"sizni albatta tiqaman"},{ar:"فِي السِّجْنِ",uz:"qamoqqa"},{ar:"بِيَدَيَّ هَاتَيْنِ",uz:"mana shu ikki qo‘lim bilan"}],full_uz:"Sizni mana shu ikki qo‘lim bilan qamoqqa tiqaman.",note:"زَجَّ بِهِ فِي السِّجْنِ — «uni qamoqqa tiqdi». لَـ va نَّ qasam javobini kuchaytiradi."},
{num:63,time:"00:05:09,839 --> 00:05:13,839",arabic:"كَانَ شَرْطِي عَلَيْكَ أَنْ تَتْرُكَ مَا أَنْتَ فِيهِ مِنْ خِفَّةٍ وَحَمَاقَةٍ.",segs:[{ar:"كَانَ شَرْطِي عَلَيْكَ",uz:"sizga qo‘ygan shartim edi"},{ar:"أَنْ تَتْرُكَ مَا أَنْتَ فِيهِ",uz:"o‘zingizdagi holatni tark etishingiz"},{ar:"مِنْ خِفَّةٍ وَحَمَاقَةٍ",uz:"yengiltaklik va ahmoqlikdan iborat"}],full_uz:"Sizga qo‘ygan shartim o‘zingizdagi yengiltaklik va ahmoqlikni tark etishingiz edi.",note:"خِفَّةٌ bu yerda vazn yengilligi emas, «yengiltaklik, o‘ylamay ish qilish»."},
{num:64,time:"00:05:13,839 --> 00:05:18,839",arabic:"حَتَّى أَسْتَطِيعَ إِخْرَاجَكَ مِنَ الْمُصِيبَةِ الَّتِي أَوْقَعْتَ نَفْسَكَ فِي شَرَكِهَا.",segs:[{ar:"حَتَّى أَسْتَطِيعَ إِخْرَاجَكَ",uz:"sizni chiqara olishim uchun"},{ar:"مِنَ الْمُصِيبَةِ",uz:"musibatdan"},{ar:"الَّتِي أَوْقَعْتَ نَفْسَكَ فِي شَرَكِهَا",uz:"o‘zingizni uning tuzog‘iga tushirgan"}],full_uz:"O‘zingiz tuzog‘iga tushgan musibatdan sizni qutqara olishim uchun.",note:"شَرَكٌ — «tuzoq»; شِرْكٌ esa boshqa ma’nodagi so‘z. أَوْقَعَ نَفْسَهُ — «o‘zini tushirdi»."},
{num:65,time:"00:05:18,839 --> 00:05:21,839",arabic:"حَسَنًا، وَأَنَا عِنْدَ وَعْدِي.",segs:[{ar:"حَسَنًا",uz:"xo‘p"},{ar:"وَأَنَا عِنْدَ وَعْدِي",uz:"men va’damda turaman"}],full_uz:"Xo‘p, men va’damda turaman.",note:"أَنَا عِنْدَ وَعْدِي — «va’damga sodiqman, va’damda turaman»."},
{num:66,time:"00:05:21,839 --> 00:05:23,839",arabic:"عِنْدَ وَعْدِكَ؟",segs:null,full_uz:"Va’dangizda turibsizmi?",note:null},
{num:67,time:"00:05:25,839 --> 00:05:29,839",arabic:"مَنِ الَّذِي أَخْبَرَ الْمَرِيسِيَّ بِأَنْ يَفِرَّ قَبْلَ أَنْ يَصِلَ جُنُودُنَا إِلَيْهِ؟",segs:[{ar:"مَنِ الَّذِي أَخْبَرَ الْمَرِيسِيَّ",uz:"Marisiyga kim xabar berdi"},{ar:"بِأَنْ يَفِرَّ",uz:"qochish kerakligini"},{ar:"قَبْلَ أَنْ يَصِلَ جُنُودُنَا إِلَيْهِ؟",uz:"askarlarimiz uning oldiga yetib borishidan oldin?"}],full_uz:"Askarlarimiz uning oldiga yetib borishidan oldin qochish kerakligini Marisiyga kim aytdi?",note:"فَرَّ — يَفِرُّ — «qochmoq». أَنْ dan keyin يَفِرَّ bo‘lib mansub keladi."},
{num:68,time:"00:05:31,839 --> 00:05:35,279",arabic:"وَمَا أَدْرَانِي أَنَا؟",segs:null,full_uz:"Men qayerdan bilay?",note:"مَا أَدْرَانِي؟ — «men qayerdan bilay?». أَنَا qo‘shimcha ta’kid beradi."},
{num:69,time:"00:05:35,279 --> 00:05:37,219",arabic:"أُقْسِمُ أَنَّ لَا أَحَدَ غَيْرَكَ فَعَلَهَا.",segs:[{ar:"أُقْسِمُ",uz:"qasam ichaman"},{ar:"أَنَّ لَا أَحَدَ غَيْرَكَ فَعَلَهَا",uz:"buni sizdan boshqa hech kim qilmagan"}],full_uz:"Qasam ichaman, buni sizdan boshqa hech kim qilmagan.",note:null},
{num:70,time:"00:05:37,219 --> 00:05:41,019",arabic:"لَوْلَا أَنَّكَ صَدِيقِي لَقَبَضْتُ عَلَيْكَ بِنَفْسِي.",segs:[{ar:"لَوْلَا أَنَّكَ صَدِيقِي",uz:"do‘stim bo‘lmaganingizda"},{ar:"لَقَبَضْتُ عَلَيْكَ",uz:"sizni hibsga olgan bo‘lardim"},{ar:"بِنَفْسِي",uz:"shaxsan o‘zim"}],full_uz:"Do‘stim bo‘lmaganingizda, sizni shaxsan o‘zim hibsga olgan bo‘lardim.",note:"لَوْلَا — bir holat mavjudligi sababli boshqa ish amalga oshmaganini bildiradi."},
{num:71,time:"00:05:45,719 --> 00:05:47,839",arabic:"إِنْ بَقِيتَ عَلَى فَظَاظَتِكَ هَذِهِ...",segs:[{ar:"إِنْ بَقِيتَ",uz:"agar davom etsangiz"},{ar:"عَلَى فَظَاظَتِكَ هَذِهِ",uz:"shu qo‘polligingizda"}],full_uz:"Shu qo‘polligingizda davom etsangiz...",note:"فَظَاظَةٌ — «qo‘pollik, dag‘allik»."},
{num:72,time:"00:05:47,839 --> 00:05:51,199",arabic:"أُقْسِمُ أَنِّي سَأَخْرُجُ مِنْ هُنَا وَلَنْ تَرَى وَجْهِي مَرَّةً أُخْرَى.",segs:[{ar:"أُقْسِمُ أَنِّي سَأَخْرُجُ مِنْ هُنَا",uz:"qasam ichaman, bu yerdan chiqib ketaman"},{ar:"وَلَنْ تَرَى وَجْهِي",uz:"va yuzimni ko‘rmaysiz"},{ar:"مَرَّةً أُخْرَى",uz:"boshqa"}],full_uz:"Qasam ichaman, bu yerdan chiqib ketaman va yuzimni boshqa ko‘rmaysiz.",note:null},
{num:73,time:"00:05:51,199 --> 00:05:55,120",arabic:"فَظَاظَتِي هَذِهِ هِيَ الَّتِي أَخْرَجَتْكَ مِنْ مُصِيبَتِكَ أَيُّهَا الْأَحْمَقُ.",segs:[{ar:"فَظَاظَتِي هَذِهِ",uz:"shu qo‘polligim"},{ar:"هِيَ الَّتِي أَخْرَجَتْكَ",uz:"aynan sizni chiqardi"},{ar:"مِنْ مُصِيبَتِكَ",uz:"musibatingizdan"},{ar:"أَيُّهَا الْأَحْمَقُ",uz:"ey ahmoq"}],full_uz:"Sizni musibatingizdan aynan shu qo‘polligim qutqardi, ey ahmoq.",note:"هِيَ الَّتِي... — «aynan o‘sha ... qilgan» tarzidagi ta’kid."},
{num:74,time:"00:05:55,120 --> 00:06:00,959",arabic:"وَصَدَاقَتِي لَكَ هِيَ الَّتِي جَعَلَتْنِي أُغَامِرُ لِتَتَمَكَّنَ مِنَ الْهُرُوبِ مِنْ جُنْدِ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"وَصَدَاقَتِي لَكَ",uz:"siz bilan do‘stligim"},{ar:"هِيَ الَّتِي جَعَلَتْنِي أُغَامِرُ",uz:"meni tavakkal qilishga undadi"},{ar:"لِتَتَمَكَّنَ مِنَ الْهُرُوبِ",uz:"qochib qutula olishingiz uchun"},{ar:"مِنْ جُنْدِ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining askarlaridan"}],full_uz:"Mo‘minlar amirining askarlaridan qochib qutula olishingiz uchun meni tavakkal qilishga undagan narsa siz bilan do‘stligimdir.",note:"غَامَرَ — «tavakkal qildi, o‘zini xavfga qo‘ydi». تَمَكَّنَ مِنْ — «...ga erisha oldi»."},
{num:75,time:"00:06:00,959 --> 00:06:04,879",arabic:"وَمَا كُنْتُ تَجَشَّمْتُ عَنَاءَ إِخْفَائِكَ هُنَا فِي بَيْتِ ابْنِ عَمِّي هَذَا...",segs:[{ar:"وَمَا كُنْتُ تَجَشَّمْتُ",uz:"o‘z zimmamga olmagan bo‘lardim"},{ar:"عَنَاءَ إِخْفَائِكَ هُنَا",uz:"sizni bu yerda yashirish mashaqqatini"},{ar:"فِي بَيْتِ ابْنِ عَمِّي هَذَا",uz:"amakivachchamning shu uyida"}],full_uz:"Sizni amakivachchamning shu uyida yashirish mashaqqatini zimmamga olmagan bo‘lardim...",note:"تَجَشَّمَ عَنَاءَ شَيْءٍ — «bir ishning mashaqqatini o‘z zimmasiga oldi»."},
{num:76,time:"00:06:04,879 --> 00:06:08,979",arabic:"إِلَّا لِأَنَّكَ وَعَدْتَنِي بِأَنْ تَبْتَعِدَ عَنْ طَرِيقِ هَؤُلَاءِ الْمُبْتَدِعِينَ.",segs:[{ar:"إِلَّا لِأَنَّكَ وَعَدْتَنِي",uz:"faqat menga va’da berganingiz uchun"},{ar:"بِأَنْ تَبْتَعِدَ",uz:"uzoqlashishga"},{ar:"عَنْ طَرِيقِ هَؤُلَاءِ الْمُبْتَدِعِينَ",uz:"bu bid’atchilarning yo‘lidan"}],full_uz:"Bunga faqat bu bid’atchilarning yo‘lidan uzoqlashishga va’da berganingiz uchun rozi bo‘ldim.",note:"اِبْتَعَدَ عَنْ — «...dan uzoqlashdi»."},
{num:77,time:"00:06:08,979 --> 00:06:11,039",arabic:"مَا شَأْنُكَ أَنْتَ وَالْمُعْتَزِلَةَ؟",segs:[{ar:"مَا شَأْنُكَ أَنْتَ",uz:"sizning nima aloqangiz bor"},{ar:"وَالْمُعْتَزِلَةَ؟",uz:"mu’tazila bilan?"}],full_uz:"Sizning mu’tazila bilan nima aloqangiz bor?",note:"مَا شَأْنُكَ وَ...؟ — «sizning ...bilan nima ishingiz bor?»."},
{num:78,time:"00:06:11,039 --> 00:06:13,459",arabic:"اُنْظُرْ إِلَى أَيْنَ انْتَهَوْا وَإِلَى أَيْنَ صِرْتَ.",segs:[{ar:"اُنْظُرْ",uz:"qarang"},{ar:"إِلَى أَيْنَ انْتَهَوْا",uz:"ular qanday ahvolga kelganiga"},{ar:"وَإِلَى أَيْنَ صِرْتَ",uz:"siz qanday ahvolga kelganingizga"}],full_uz:"Ular qanday ahvolga, siz esa qanday ahvolga kelganingizga qarang.",note:"صَارَ — «bo‘lib qoldi, bir holatga keldi». صِرْتَ — «siz bo‘lib qoldingiz»."},
{num:79,time:"00:06:13,459 --> 00:06:15,439",arabic:"قِسْمٌ أَقَرَّ وَاعْتَرَفَ.",segs:[{ar:"قِسْمٌ",uz:"bir qismi"},{ar:"أَقَرَّ وَاعْتَرَفَ",uz:"iqror bo‘lib, tan oldi"}],full_uz:"Bir qismi iqror bo‘lib, tan oldi.",note:"أَقَرَّ va اِعْتَرَفَ bu yerda bir-biriga yaqin ma’noda, ta’kid uchun kelgan."},
{num:80,time:"00:06:15,439 --> 00:06:17,659",arabic:"فَتَكَفَّلَ بِهِ السَّيْفُ وَالنِّطْعُ.",segs:[{ar:"فَتَكَفَّلَ بِهِ",uz:"shunda uning ishini bitirdi"},{ar:"السَّيْفُ وَالنِّطْعُ",uz:"qilich va qatl to‘shamasi"}],full_uz:"Shunda uning ishini qilich va qatl to‘shamasi bitirdi.",note:"تَكَفَّلَ بِهِ — «uning ishini zimmasiga oldi». Bu yerda qatl etish kinoya bilan ifodalangan."},
{num:81,time:"00:06:17,659 --> 00:06:21,560",arabic:"وَقِسْمٌ أَنْكَرَ فَأُلْقِيَ بِهِ فِي السِّجْنِ.",segs:[{ar:"وَقِسْمٌ أَنْكَرَ",uz:"bir qismi esa inkor qildi"},{ar:"فَأُلْقِيَ بِهِ فِي السِّجْنِ",uz:"va qamoqqa tashlandi"}],full_uz:"Bir qismi esa inkor qilib, qamoqqa tashlandi.",note:"أُلْقِيَ بِهِ — majhul nisbat: «u tashlandi»."},
{num:82,time:"00:06:21,560 --> 00:06:23,959",arabic:"وَقِسْمٌ هَارِبٌ يَخَافُ مِنْ ظِلِّهِ.",segs:[{ar:"وَقِسْمٌ هَارِبٌ",uz:"yana bir qismi qochqin"},{ar:"يَخَافُ مِنْ ظِلِّهِ",uz:"o‘z soyasidan ham qo‘rqadi"}],full_uz:"Yana bir qismi qochqin bo‘lib, o‘z soyasidan ham qo‘rqadi.",note:"يَخَافُ مِنْ ظِلِّهِ — haddan tashqari qo‘rqoqlik yoki xavotirni tasvirlovchi ibora."},
{num:83,time:"00:06:23,959 --> 00:06:25,959",arabic:"أَهَذَا مَا تَتَمَنَّى؟",segs:null,full_uz:"Istaganingiz shumi?",note:null},
{num:84,time:"00:06:25,959 --> 00:06:30,319",arabic:"إِنَّمَا الْحَيَاةُ عَقِيدَةٌ وَجِهَادٌ.",segs:[{ar:"إِنَّمَا الْحَيَاةُ",uz:"hayot faqat"},{ar:"عَقِيدَةٌ وَجِهَادٌ",uz:"e’tiqod va kurashdir"}],full_uz:"Hayot faqat e’tiqod va kurashdir.",note:"إِنَّمَا cheklash va ta’kidni bildiradi. جِهَادٌ ning aniq ma’nosi kontekstga bog‘liq; bu yerda e’tiqod yo‘lidagi kurash."},
{num:85,time:"00:06:30,319 --> 00:06:34,259",arabic:"تَقُولُونَ إِنَّ الْحَيَاةَ عَقِيدَةٌ وَجِهَادٌ.",segs:[{ar:"تَقُولُونَ",uz:"sizlar deysizlar"},{ar:"إِنَّ الْحَيَاةَ عَقِيدَةٌ وَجِهَادٌ",uz:"hayot e’tiqod va kurashdir deb"}],full_uz:"Sizlar hayot e’tiqod va kurashdir, deysizlar.",note:null},
{num:86,time:"00:06:34,259 --> 00:06:37,399",arabic:"وَتَدَّعُونَ أَنَّكُمْ أَصْحَابُ رَأْيٍ وَمَبْدَإٍ.",segs:[{ar:"وَتَدَّعُونَ أَنَّكُمْ",uz:"va o‘zingizni deb da’vo qilasizlar"},{ar:"أَصْحَابُ رَأْيٍ وَمَبْدَإٍ",uz:"fikr va tamoyil egalari"}],full_uz:"O‘zingizni fikr va tamoyil egalari deb da’vo qilasizlar.",note:"اِدَّعَى — يَدَّعِي — «da’vo qilmoq». تَدَّعُونَ ni تَدْعُونَ («chaqirasizlar, duo qilasizlar») bilan adashtirmang."},
{num:87,time:"00:06:37,399 --> 00:06:40,060",arabic:"وَمَا أَنْتُمْ إِلَّا خَوَّارُونَ جُبَنَاءُ.",segs:[{ar:"وَمَا أَنْتُمْ إِلَّا",uz:"aslida sizlar faqat"},{ar:"خَوَّارُونَ جُبَنَاءُ",uz:"irodasiz qo‘rqoqlarsizlar"}],full_uz:"Aslida sizlar irodasiz qo‘rqoqlarsizlar, xolos.",note:"خَوَّارٌ — «zaif, bardoshsiz»; جُبَنَاءُ — جَبَانٌ («qo‘rqoq»)ning ko‘pligi."},
{num:88,time:"00:06:40,060 --> 00:06:41,719",arabic:"كَحَالِ شَيْخِكُمْ...",segs:null,full_uz:"Shayxingizning holi kabi...",note:null},
{num:89,time:"00:06:41,719 --> 00:06:44,159",arabic:"الْجَبَانِ ثُمَامَةَ بْنِ الْأَشْرَسِ.",segs:[{ar:"الْجَبَانِ",uz:"qo‘rqoq"},{ar:"ثُمَامَةَ بْنِ الْأَشْرَسِ",uz:"Sumoma ibn Ashrasning"}],full_uz:"Qo‘rqoq Sumoma ibn Ashrasning.",note:"الْجَبَانِ oldingi banddagi شَيْخِكُمْ ni sifatlab kelgan."},
{num:90,time:"00:06:44,159 --> 00:06:45,819",arabic:"وَيْحَكَ يَا شَفِيعُ!",segs:[{ar:"وَيْحَكَ",uz:"holingizga voy"},{ar:"يَا شَفِيعُ",uz:"ey Shafi’"}],full_uz:"Holingizga voy, Shafi’!",note:"وَيْحَكَ — achinish, tanbeh yoki hayrat ifodasi; ohangga qarab ma’nosi yumshoqroq bo‘lishi mumkin."},
{num:91,time:"00:06:45,819 --> 00:06:48,219",arabic:"كَيْفَ تَقُولُ عَنْ شَيْخِنَا جَبَانٌ؟",segs:[{ar:"كَيْفَ تَقُولُ عَنْ شَيْخِنَا",uz:"shayximiz haqida qanday aytasiz"},{ar:"جَبَانٌ؟",uz:"qo‘rqoq deb?"}],full_uz:"Shayximizni qanday qilib qo‘rqoq deysiz?",note:null},
{num:92,time:"00:06:48,219 --> 00:06:49,719",arabic:"إِنَّكَ لَا تَعْرِفُهُ جَيِّدًا.",segs:null,full_uz:"Siz uni yaxshi bilmaysiz.",note:null},
{num:93,time:"00:06:49,719 --> 00:06:53,639",arabic:"إِنَّهُ ثَابِتٌ عَلَى عَقِيدَتِهِ كَصَخْرَةٍ فِي جَبَلٍ أَصَمَّ.",segs:[{ar:"إِنَّهُ ثَابِتٌ عَلَى عَقِيدَتِهِ",uz:"u e’tiqodida sobit"},{ar:"كَصَخْرَةٍ",uz:"qoya kabi"},{ar:"فِي جَبَلٍ أَصَمَّ",uz:"mustahkam tog‘dagi"}],full_uz:"U mustahkam tog‘dagi qoya kabi e’tiqodida sobit.",note:"أَصَمُّ odatda «kar» degani; tog‘ haqida aytilganda «qattiq, mustahkam» ma’nosini beradi."},
{num:94,time:"00:06:53,639 --> 00:06:55,740",arabic:"أَنَا أَعْرِفُهُ أَكْثَرَ مِنْكَ.",segs:[{ar:"أَنَا أَعْرِفُهُ",uz:"men uni bilaman"},{ar:"أَكْثَرَ مِنْكَ",uz:"sizdan ko‘ra yaxshiroq"}],full_uz:"Men uni sizdan ko‘ra yaxshiroq bilaman.",note:null},
{num:95,time:"00:06:55,740 --> 00:06:59,000",arabic:"شَيْخُكُمُ الْهُمَامُ الصَّخْرِيُّ ابْنُ الْأَشْرَسِ...",segs:[{ar:"شَيْخُكُمُ الْهُمَامُ الصَّخْرِيُّ",uz:"o‘sha jasur, qoyadek shayxingiz"},{ar:"ابْنُ الْأَشْرَسِ",uz:"Ibn Ashras"}],full_uz:"O‘sha jasur, qoyadek shayxingiz Ibn Ashras...",note:"هُمَامٌ — «jasur, shijoatli». Bu yerda oldingi maqtovga kinoya bilan javob berilmoqda."},
{num:96,time:"00:06:59,000 --> 00:07:01,339",arabic:"عِنْدَمَا رَأَى السَّيْفَ أَمَامَ وَجْهِهِ...",segs:[{ar:"عِنْدَمَا رَأَى السَّيْفَ",uz:"qilichni ko‘rganida"},{ar:"أَمَامَ وَجْهِهِ",uz:"yuzi oldida"}],full_uz:"Qilichni yuzi oldida ko‘rganida...",note:null},
{num:97,time:"00:07:01,339 --> 00:07:02,980",arabic:"وَالنِّطْعَ يَتَرَصَّدُهُ...",segs:[{ar:"وَالنِّطْعَ",uz:"qatl to‘shamasi esa"},{ar:"يَتَرَصَّدُهُ",uz:"uni kutib turganini"}],full_uz:"Va qatl to‘shamasi uni kutib turganini...",note:"تَرَصَّدَ — «poyladi». Jonsiz narsa odamni poylayotgandek tasvirlangan."},
{num:98,time:"00:07:02,980 --> 00:07:05,839",arabic:"تَبَرَّأَ مِنْ كُلِّ تُرَّهَاتِهِ وَأَوْهَامِهِ.",segs:[{ar:"تَبَرَّأَ",uz:"voz kechdi"},{ar:"مِنْ كُلِّ تُرَّهَاتِهِ وَأَوْهَامِهِ",uz:"barcha safsatalari va xomxayollaridan"}],full_uz:"Barcha safsatalari va xomxayollaridan voz kechdi.",note:"تَبَرَّأَ مِنْ — «aloqasi yo‘qligini bildirdi, voz kechdi». تُرَّهَاتٌ — «safsatalar, bema’ni gaplar»."},
{num:99,time:"00:07:05,839 --> 00:07:07,759",arabic:"وَرَاحَ يُرَاوِغُ كَالْبُهْلُولِ.",segs:[{ar:"وَرَاحَ يُرَاوِغُ",uz:"va gapdan qochishga tushdi"},{ar:"كَالْبُهْلُولِ",uz:"masxaraboz kabi"}],full_uz:"Va masxaraboz kabi gapdan qochishga tushdi.",note:"رَاحَ + muzoriy bu yerda harakatning boshlanishini bildiradi: «...ga tushdi»."},
{num:100,time:"00:07:07,759 --> 00:07:10,519",arabic:"لَوْ كُنْتُمْ أَصْحَابَ حَقٍّ...",segs:[{ar:"لَوْ كُنْتُمْ",uz:"agar bo‘lganingizda"},{ar:"أَصْحَابَ حَقٍّ",uz:"haq tarafdorlari"}],full_uz:"Agar haq tarafdorlari bo‘lganingizda...",note:null},
{num:101,time:"00:07:10,519 --> 00:07:13,139",arabic:"مَا فَرَرْتُمْ وَلَا جَبُنْتُمْ.",segs:[{ar:"مَا فَرَرْتُمْ",uz:"qochmagan bo‘lardingiz"},{ar:"وَلَا جَبُنْتُمْ",uz:"va qo‘rqmagan bo‘lardingiz"}],full_uz:"Qochmagan ham, qo‘rqmagan ham bo‘lardingiz.",note:"فَرَّ fe’liga تُمْ qo‘shilganda shadda ochiladi: فَرَرْتُمْ."},
{num:102,time:"00:07:13,139 --> 00:07:14,800",arabic:"بَلْ لَبِثْتُمْ عَلَى مَوْقِفِكُمْ.",segs:[{ar:"بَلْ لَبِثْتُمْ",uz:"aksincha, qolgan bo‘lardingiz"},{ar:"عَلَى مَوْقِفِكُمْ",uz:"o‘z tutgan yo‘lingizda"}],full_uz:"Aksincha, o‘z tutgan yo‘lingizda qolgan bo‘lardingiz.",note:"لَبِثَ — «qoldi, turdi». مَوْقِفٌ bu yerda «tutgan yo‘l, pozitsiya»."},
{num:103,time:"00:07:14,800 --> 00:07:17,160",arabic:"حَتَّى وَلَوْ تَخَطَّفَتْكُمُ الطَّيْرُ.",segs:[{ar:"حَتَّى وَلَوْ",uz:"hatto ... bo‘lsa ham"},{ar:"تَخَطَّفَتْكُمُ الطَّيْرُ",uz:"qushlar sizni ilib ketsa"}],full_uz:"Hatto qushlar sizni ilib ketsa ham.",note:"تَخَطَّفَ — «tezda ilib ketdi». حَتَّى وَلَوْ — «hatto ... bo‘lsa ham»."},
{num:104,time:"00:07:17,160 --> 00:07:23,699",arabic:"لَا تَتَحَامَلْ عَلَى الرَّجُلِ يَا ابْنَ الرَّبِيعِ.",segs:[{ar:"لَا تَتَحَامَلْ عَلَى الرَّجُلِ",uz:"bu kishiga ortiqcha qattiqqo‘llik qilmang"},{ar:"يَا ابْنَ الرَّبِيعِ",uz:"ey Ibn Rabi’"}],full_uz:"Bu kishiga ortiqcha qattiqqo‘llik qilmang, Ibn Rabi’.",note:"تَحَامَلَ عَلَى — «bir kishiga nohaq yoki ortiqcha qattiq munosabatda bo‘ldi»."},
{num:105,time:"00:07:23,699 --> 00:07:25,279",arabic:"لَا تَتَحَامَلْ عَلَيْهِ.",segs:null,full_uz:"Unga ortiqcha qattiqqo‘llik qilmang.",note:null},
{num:106,time:"00:07:25,279 --> 00:07:28,160",arabic:"وَلَكِنَّهُ يُحَاوِلُ خِدَاعَكَ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"وَلَكِنَّهُ يُحَاوِلُ خِدَاعَكَ",uz:"lekin u sizni aldashga urinmoqda"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Lekin u sizni aldashga urinmoqda, ey mo‘minlar amiri.",note:"خِدَاعٌ — «aldash». يُحَاوِلُ خِدَاعَكَ — «sizni aldashga urinmoqda»."},
{num:107,time:"00:07:28,160 --> 00:07:30,920",arabic:"أَعْلَمُ ذَلِكَ، تَفَضَّلْ.",segs:[{ar:"أَعْلَمُ ذَلِكَ",uz:"buni bilaman"},{ar:"تَفَضَّلْ",uz:"marhamat"}],full_uz:"Buni bilaman, marhamat.",note:null},
{num:108,time:"00:07:30,920 --> 00:07:34,100",arabic:"الْكَرِيمُ إِذَا خَادَعْتَهُ انْخَدَعَ.",segs:[{ar:"الْكَرِيمُ",uz:"olijanob kishi"},{ar:"إِذَا خَادَعْتَهُ",uz:"uni aldashga urinsangiz"},{ar:"انْخَدَعَ",uz:"aldanadi"}],full_uz:"Olijanob kishini aldashga urinsangiz, u aldanadi.",note:"خَادَعَ — «aldashga urindi»; اِنْخَدَعَ — «aldandi». Bu yerda olijanoblik bilan ko‘z yumish ma’nosi ham anglashiladi."},
{num:109,time:"00:07:34,100 --> 00:07:37,080",arabic:"ثُمَّ إِنَّ الرَّجُلَ أَنْكَرَ أَنَّهُ مِنْ هَؤُلَاءِ الْقَوْمِ.",segs:[{ar:"ثُمَّ إِنَّ الرَّجُلَ أَنْكَرَ",uz:"qolaversa, bu kishi inkor qildi"},{ar:"أَنَّهُ مِنْ هَؤُلَاءِ الْقَوْمِ",uz:"o‘sha guruhdan ekanini"}],full_uz:"Qolaversa, bu kishi o‘sha guruhdan ekanini inkor qildi.",note:null},
{num:110,time:"00:07:37,080 --> 00:07:41,320",arabic:"أَلَمْ نُؤْمَرْ بِأَنْ نَدْرَأَ الْحُدُودَ بِالشُّبُهَاتِ؟",segs:[{ar:"أَلَمْ نُؤْمَرْ",uz:"bizga buyurilmaganmi"},{ar:"بِأَنْ نَدْرَأَ الْحُدُودَ",uz:"hadd jazolarini chetlatish"},{ar:"بِالشُّبُهَاتِ؟",uz:"shubhalar sababli?"}],full_uz:"Shubhalar sababli hadd jazolarini chetlatish bizga buyurilmaganmi?",note:"نُؤْمَرْ — majhul nisbat: «bizga buyuriladi». دَرَأَ — «chetlatdi, daf qildi»."},
{num:111,time:"00:07:41,320 --> 00:07:45,340",arabic:"دِينُنَا دِينُ رَحْمَةٍ يَا ابْنَ الرَّبِيعِ.",segs:[{ar:"دِينُنَا دِينُ رَحْمَةٍ",uz:"dinimiz rahmat dinidir"},{ar:"يَا ابْنَ الرَّبِيعِ",uz:"ey Ibn Rabi’"}],full_uz:"Dinimiz rahmat dinidir, Ibn Rabi’.",note:null},
{num:112,time:"00:07:47,100 --> 00:07:50,220",arabic:"فَلَا تَجْعَلْ غَضَبَكَ يُعْمِيكَ عَنِ اتِّبَاعِ الصَّوَابِ.",segs:[{ar:"فَلَا تَجْعَلْ غَضَبَكَ",uz:"g‘azabingizga yo‘l qo‘ymang"},{ar:"يُعْمِيكَ",uz:"ko‘zingizni ko‘r qilishiga"},{ar:"عَنِ اتِّبَاعِ الصَّوَابِ",uz:"to‘g‘ri yo‘lga ergashishdan"}],full_uz:"G‘azabingiz to‘g‘ri yo‘lni ko‘rishingizga to‘sqinlik qilishiga yo‘l qo‘ymang.",note:"أَعْمَى عَنْ — «bir narsani ko‘rmaydigan qilib qo‘ydi». Bu yerda ko‘chma ma’noda."},
{num:113,time:"00:07:50,220 --> 00:07:52,000",arabic:"وَإِذَا كُنْتَ مُقْتَدِرًا...",segs:null,full_uz:"Agar qudratli bo‘lsangiz...",note:"مُقْتَدِرٌ — «qudratli, imkoniyati va kuchi bor»."},
{num:114,time:"00:07:52,000 --> 00:07:55,500",arabic:"فَلَا تَجْعَلْ قُدْرَتَكَ تُعْمِيكَ عَنِ اتِّبَاعِ الْحَقِّ.",segs:[{ar:"فَلَا تَجْعَلْ قُدْرَتَكَ",uz:"qudratingizga yo‘l qo‘ymang"},{ar:"تُعْمِيكَ",uz:"ko‘zingizni ko‘r qilishiga"},{ar:"عَنِ اتِّبَاعِ الْحَقِّ",uz:"haqqa ergashishdan"}],full_uz:"Qudratingiz haqqa ergashishingizga to‘sqinlik qilishiga yo‘l qo‘ymang.",note:null},
{num:115,time:"00:07:55,500 --> 00:07:58,959",arabic:"ثُمَّ إِنَّ الرَّجُلَ وَاللَّهِ ظَرِيفٌ.",segs:[{ar:"ثُمَّ إِنَّ الرَّجُلَ",uz:"qolaversa, bu kishi"},{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"ظَرِيفٌ",uz:"hazilkash"}],full_uz:"Qolaversa, Allohga qasam, bu kishi hazilkash.",note:"ظَرِيفٌ — «yoqimli, nozikfahm, hazilkash»; bu yerda topqir gapiradigan kishi haqida."},
{num:116,time:"00:07:58,959 --> 00:08:00,439",arabic:"تَصَوَّرْ.",segs:null,full_uz:"Tasavvur qiling.",note:null},
{num:117,time:"00:08:00,439 --> 00:08:04,399",arabic:"حَتَّى بَشَّارُ بْنُ بُرْدٍ الْأَعْمَى...",segs:[{ar:"حَتَّى بَشَّارُ بْنُ بُرْدٍ",uz:"hatto Bashshor ibn Burd ham"},{ar:"الْأَعْمَى",uz:"ko‘zi ojiz"}],full_uz:"Hatto ko‘zi ojiz Bashshor ibn Burd ham...",note:"الْأَعْمَى — «ko‘zi ojiz»."},
{num:118,time:"00:08:04,399 --> 00:08:06,660",arabic:"سَيَرَى اللَّهَ يَوْمَ الْقِيَامَةِ.",segs:[{ar:"سَيَرَى اللَّهَ",uz:"Allohni ko‘radi"},{ar:"يَوْمَ الْقِيَامَةِ",uz:"qiyomat kuni"}],full_uz:"Qiyomat kuni Allohni ko‘radi.",note:null},
{num:119,time:"00:08:06,660 --> 00:08:07,959",arabic:"وَاللَّهِ إِنَّهُ ظَرِيفٌ.",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"إِنَّهُ ظَرِيفٌ",uz:"u hazilkash"}],full_uz:"Allohga qasam, u hazilkash.",note:null},
{num:120,time:"00:08:07,959 --> 00:08:16,259",arabic:"أَنَا لَا أُوَافِقُكَ الرَّأْيَ فِيمَا تَعْتَقِدُ يَا ابْنَ أَكْثَمَ.",segs:[{ar:"أَنَا لَا أُوَافِقُكَ الرَّأْيَ",uz:"men sizning fikringizga qo‘shilmayman"},{ar:"فِيمَا تَعْتَقِدُ",uz:"ishonayotgan narsangiz borasida"},{ar:"يَا ابْنَ أَكْثَمَ",uz:"ey Ibn Aksam"}],full_uz:"Bu boradagi fikringizga qo‘shilmayman, Ibn Aksam.",note:"وَافَقَهُ الرَّأْيَ — «uning fikriga qo‘shildi»."},
{num:121,time:"00:08:16,259 --> 00:08:20,939",arabic:"وَلْنَزْعُمْ أَنَّ الْمُعْتَزِلَةَ كَانُوا عَلَى خَطَإٍ فِيمَا يَعْتَقِدُونَ.",segs:[{ar:"وَلْنَزْعُمْ",uz:"faraz qilaylik"},{ar:"أَنَّ الْمُعْتَزِلَةَ كَانُوا عَلَى خَطَإٍ",uz:"mu’tazila xato qilgan deb"},{ar:"فِيمَا يَعْتَقِدُونَ",uz:"o‘z e’tiqodlarida"}],full_uz:"Mu’tazila o‘z e’tiqodlarida xato qilgan deb faraz qilaylik.",note:"لْ buyruq lomi bu yerda «...qilaylik» ma’nosini beradi: وَلْنَزْعُمْ."},
{num:122,time:"00:08:20,939 --> 00:08:23,939",arabic:"أَتُؤْخَذُ الْحُدُودُ بِالْخَطَإِ؟",segs:[{ar:"أَتُؤْخَذُ الْحُدُودُ",uz:"hadd jazolari qo‘llanadimi"},{ar:"بِالْخَطَإِ؟",uz:"xato sababli?"}],full_uz:"Xato sababli hadd jazolari qo‘llanadimi?",note:"تُؤْخَذُ — majhul nisbat. بِـ bu yerda sababni bildiradi."},
{num:123,time:"00:08:23,939 --> 00:08:27,899",arabic:"أَمِيرُ الْمُؤْمِنِينَ لَمْ يَقْتُلْهُمْ لِاعْتِقَادِهِمْ بِمَا يَعْتَقِدُونَ.",segs:[{ar:"أَمِيرُ الْمُؤْمِنِينَ لَمْ يَقْتُلْهُمْ",uz:"mo‘minlar amiri ularni o‘ldirmadi"},{ar:"لِاعْتِقَادِهِمْ بِمَا يَعْتَقِدُونَ",uz:"o‘z e’tiqodlariga ishonganlari uchun"}],full_uz:"Mo‘minlar amiri ularni shunchaki o‘z e’tiqodlariga ishonganlari uchun o‘ldirmadi.",note:"لِـ masdar oldida sababni bildiradi: لِاعْتِقَادِهِمْ — «ularning ishonishi sababli»."},
{num:124,time:"00:08:27,899 --> 00:08:29,600",arabic:"وَأَنْتَ تَعْلَمُ ذَلِكَ.",segs:null,full_uz:"Siz buni bilasiz.",note:null},
{num:125,time:"00:08:29,600 --> 00:08:31,939",arabic:"وَإِذَنْ؟",segs:null,full_uz:"Unda-chi?",note:null},
{num:126,time:"00:08:32,899 --> 00:08:35,460",arabic:"إِنَّ الَّذِينَ أُلْقِيَ الْقَبْضُ عَلَيْهِمْ...",segs:[{ar:"إِنَّ الَّذِينَ",uz:"albatta, o‘sha kishilar"},{ar:"أُلْقِيَ الْقَبْضُ عَلَيْهِمْ",uz:"hibsga olingan"}],full_uz:"Hibsga olingan kishilar...",note:"أُلْقِيَ الْقَبْضُ عَلَيْهِ — «u hibsga olindi» degan turg‘un birikma."},
{num:127,time:"00:08:35,460 --> 00:08:38,179",arabic:"كَانُوا يَنْشُرُونَ اعْتِقَادَهُمْ بَيْنَ النَّاسِ.",segs:[{ar:"كَانُوا يَنْشُرُونَ اعْتِقَادَهُمْ",uz:"o‘z e’tiqodlarini tarqatardilar"},{ar:"بَيْنَ النَّاسِ",uz:"odamlar orasida"}],full_uz:"O‘z e’tiqodlarini odamlar orasida tarqatardilar.",note:null},
{num:128,time:"00:08:38,179 --> 00:08:41,139",arabic:"وَيَسْتَغِلُّونَ الْجُهَّالَ وَالشَّبَابَ وَالْيَافِعِينَ.",segs:[{ar:"وَيَسْتَغِلُّونَ",uz:"va foydalanardilar"},{ar:"الْجُهَّالَ وَالشَّبَابَ وَالْيَافِعِينَ",uz:"bilimsiz kishilar, yoshlar va o‘smirlardan"}],full_uz:"Bilimsiz kishilar, yoshlar va o‘smirlardan foydalanardilar.",note:"اِسْتَغَلَّ kishilar bilan kelganda «o‘z manfaati yo‘lida foydalandi». جُهَّالٌ — جَاهِلٌ ning ko‘pligi."},
{num:129,time:"00:08:41,139 --> 00:08:43,500",arabic:"وَيَبُثُّونَ الشُّبُهَاتِ فِيمَا بَيْنَهُمْ.",segs:[{ar:"وَيَبُثُّونَ الشُّبُهَاتِ",uz:"va shubhalarni yoyardilar"},{ar:"فِيمَا بَيْنَهُمْ",uz:"ular orasida"}],full_uz:"Ular orasida shubhalarni yoyardilar.",note:"بَثَّ — يَبُثُّ — «yoymoq, tarqatmoq»."},
{num:130,time:"00:08:43,500 --> 00:08:47,639",arabic:"فَيُشِيعُونَ بَيْنَ النَّاسِ الْبَلْبَلَةَ وَيَفْتِنُونَهُمْ فِي دِينِهِمْ.",segs:[{ar:"فَيُشِيعُونَ بَيْنَ النَّاسِ الْبَلْبَلَةَ",uz:"odamlar orasida sarosima tarqatardilar"},{ar:"وَيَفْتِنُونَهُمْ فِي دِينِهِمْ",uz:"va ularni dinlarida chalg‘itardilar"}],full_uz:"Odamlar orasida sarosima tarqatib, ularni dinlarida chalg‘itardilar.",note:"بَلْبَلَةٌ — «chalkashlik, sarosima». أَشَاعَ — «keng tarqatdi»."},
{num:131,time:"00:08:47,639 --> 00:08:50,500",arabic:"وَهَذَا مَا حَدَّهُمْ عَلَيْهِ أَمِيرُ الْمُؤْمِنِينَ.",segs:[{ar:"وَهَذَا مَا حَدَّهُمْ عَلَيْهِ",uz:"ularni aynan shu sababli jazoladi"},{ar:"أَمِيرُ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri"}],full_uz:"Mo‘minlar amiri ularga aynan shu sababli hadd jazosini qo‘llagan.",note:"حَدَّهُ bu kontekstda «unga hadd jazosini qo‘lladi»."},
{num:132,time:"00:08:50,500 --> 00:08:57,519",arabic:"وَلَكِنَّكَ تَعْلَمُ أَنَّ هَؤُلَاءِ الْمُعْتَزِلَةَ قَدْ ضَيَّقَ عَلَيْهِمْ هَارُونُ.",segs:[{ar:"وَلَكِنَّكَ تَعْلَمُ",uz:"lekin siz bilasiz"},{ar:"أَنَّ هَؤُلَاءِ الْمُعْتَزِلَةَ",uz:"bu mu’tazilaga"},{ar:"قَدْ ضَيَّقَ عَلَيْهِمْ هَارُونُ",uz:"Horun bosim o‘tkazganini"}],full_uz:"Lekin Horun bu mu’tazilaga bosim o‘tkazganini bilasiz.",note:"ضَيَّقَ عَلَى — «siquvga oldi, imkoniyatlarini chekladi»."},
{num:133,time:"00:08:57,519 --> 00:09:02,120",arabic:"وَلَمْ يَتْرُكْ لَهُمْ سَبِيلًا إِلَى نَشْرِ دَعْوَتِهِمْ وَبَثِّ مَذْهَبِهِمْ.",segs:[{ar:"وَلَمْ يَتْرُكْ لَهُمْ سَبِيلًا",uz:"ularga yo‘l qoldirmadi"},{ar:"إِلَى نَشْرِ دَعْوَتِهِمْ",uz:"da’vatlarini tarqatishga"},{ar:"وَبَثِّ مَذْهَبِهِمْ",uz:"va mazhablarini yoyishga"}],full_uz:"Ularga da’vatlarini tarqatish va mazhablarini yoyish uchun yo‘l qoldirmadi.",note:null},
{num:134,time:"00:09:02,120 --> 00:09:05,419",arabic:"رَغْمَ أَنَّهُمْ لَمْ يُجَاهِرُوا بِدَعْوَتِهِمْ.",segs:[{ar:"رَغْمَ أَنَّهُمْ لَمْ يُجَاهِرُوا",uz:"garchi oshkor qilmagan bo‘lsalar ham"},{ar:"بِدَعْوَتِهِمْ",uz:"da’vatlarini"}],full_uz:"Garchi ular da’vatlarini oshkor qilmagan bo‘lsalar ham.",note:"جَاهَرَ بِـ — «ochiq bildirdi». لَمْ يُجَاهِرُوا da jazm sababli oxirgi ن tushgan."},
{num:135,time:"00:09:05,419 --> 00:09:07,519",arabic:"هَا أَنْتَ تَعْتَقِدُ مُعْتَقَدَهُمْ.",segs:[{ar:"هَا أَنْتَ",uz:"mana, siz ham"},{ar:"تَعْتَقِدُ مُعْتَقَدَهُمْ",uz:"ularning e’tiqodiga ishonasiz"}],full_uz:"Mana, siz ham ularning e’tiqodiga ishonasiz.",note:"مُعْتَقَدٌ — «e’tiqod, ishoniladigan qarash»."},
{num:136,time:"00:09:07,519 --> 00:09:10,720",arabic:"هَلْ جَاءَ أَحَدُهُمْ لِلْقَبْضِ عَلَيْكَ؟",segs:[{ar:"هَلْ جَاءَ أَحَدُهُمْ",uz:"ulardan birortasi keldimi"},{ar:"لِلْقَبْضِ عَلَيْكَ؟",uz:"sizni hibsga olish uchun?"}],full_uz:"Ulardan birortasi sizni hibsga olish uchun keldimi?",note:null},
{num:137,time:"00:09:10,720 --> 00:09:14,899",arabic:"أَنْتَ لَمْ تُجَاهِرْ بِرَأْيِكَ وَلِذَلِكَ جَنَّبْتَ نَفْسَكَ مَصِيرَهُمْ.",segs:[{ar:"أَنْتَ لَمْ تُجَاهِرْ بِرَأْيِكَ",uz:"siz fikringizni oshkor qilmadingiz"},{ar:"وَلِذَلِكَ",uz:"shu sababli"},{ar:"جَنَّبْتَ نَفْسَكَ مَصِيرَهُمْ",uz:"o‘zingizni ularning taqdiridan saqladingiz"}],full_uz:"Siz fikringizni oshkor qilmadingiz, shu sababli o‘zingizni ularning taqdiridan saqladingiz.",note:"جَنَّبَ نَفْسَهُ شَيْئًا — «o‘zini bir narsadan saqladi»."},
{num:138,time:"00:09:14,899 --> 00:09:20,299",arabic:"أَمَّا مَنْ جَاهَرَ بِرَأْيِهِ فَقَدْ أَعْلَنَ الْحَرْبَ عَلَى أَمِيرِ الْمُؤْمِنِينَ وَالْأُمَّةِ.",segs:[{ar:"أَمَّا مَنْ جَاهَرَ بِرَأْيِهِ",uz:"fikrini oshkor qilgan kishiga kelsak"},{ar:"فَقَدْ أَعْلَنَ الْحَرْبَ",uz:"u urush e’lon qilgan"},{ar:"عَلَى أَمِيرِ الْمُؤْمِنِينَ وَالْأُمَّةِ",uz:"mo‘minlar amiri va ummatga qarshi"}],full_uz:"Fikrini oshkor qilgan kishi esa mo‘minlar amiri va ummatga qarshi urush e’lon qilgan.",note:"أَعْلَنَ الْحَرْبَ عَلَى — «...ga qarshi urush e’lon qildi»."},
{num:139,time:"00:09:20,299 --> 00:09:28,939",arabic:"وَلَكِنْ يَا أُمِّي...",segs:[{ar:"وَلَكِنْ",uz:"lekin"},{ar:"يَا أُمِّي",uz:"ey onajon"}],full_uz:"Lekin, onajon...",note:null},
{num:140,time:"00:09:28,939 --> 00:09:32,299",arabic:"وَلَكِنْ مَاذَا أَيُّهَا الْأَحْمَقُ؟",segs:[{ar:"وَلَكِنْ مَاذَا",uz:"lekin nima"},{ar:"أَيُّهَا الْأَحْمَقُ؟",uz:"ey ahmoq?"}],full_uz:"Lekin nima, ey ahmoq?",note:null},
{num:141,time:"00:09:32,299 --> 00:09:36,379",arabic:"هَلْ تَخْشَى مِنْ زَوْجَتِكَ الْقَبِيحَةِ؟",segs:[{ar:"هَلْ تَخْشَى",uz:"qo‘rqasizmi"},{ar:"مِنْ زَوْجَتِكَ الْقَبِيحَةِ؟",uz:"xunuk xotiningizdan?"}],full_uz:"Xunuk xotiningizdan qo‘rqasizmi?",note:"خَشِيَ — يَخْشَى — «qo‘rqmoq»."},
{num:142,time:"00:09:36,379 --> 00:09:38,699",arabic:"نَعَمْ... لَا، لَا أَخْشَى يَا أُمِّي.",segs:[{ar:"نَعَمْ... لَا",uz:"ha... yo‘q"},{ar:"لَا أَخْشَى",uz:"qo‘rqmayman"},{ar:"يَا أُمِّي",uz:"ey onajon"}],full_uz:"Ha... yo‘q, qo‘rqmayman, onajon.",note:"Birinchi لَا oldingi javobni tuzatadi; ikkinchisi fe’lni inkor qiladi."},
{num:143,time:"00:09:38,699 --> 00:09:42,219",arabic:"وَلَكِنَّ سَلْمَى لَنْ تَرْضَى أَنْ أَتَزَوَّجَ بِغَيْرِهَا.",segs:[{ar:"وَلَكِنَّ سَلْمَى لَنْ تَرْضَى",uz:"lekin Salmo rozi bo‘lmaydi"},{ar:"أَنْ أَتَزَوَّجَ بِغَيْرِهَا",uz:"undan boshqa ayolga uylanishimga"}],full_uz:"Lekin Salmo undan boshqa ayolga uylanishimga rozi bo‘lmaydi.",note:"رَضِيَ — يَرْضَى — «rozi bo‘lmoq». بِغَيْرِهَا — «undan boshqasiga»."},
{num:144,time:"00:09:42,219 --> 00:09:47,579",arabic:"سَأَجِدُ لَكَ عَرُوسًا جَمِيلَةً.",segs:[{ar:"سَأَجِدُ لَكَ",uz:"sizga topib beraman"},{ar:"عَرُوسًا جَمِيلَةً",uz:"chiroyli kelin"}],full_uz:"Sizga chiroyli kelin topib beraman.",note:null},
{num:145,time:"00:09:47,580 --> 00:09:50,740",arabic:"شَقْرَاءَ، عَيْنَاهَا خَضْرَاوَانِ.",segs:[{ar:"شَقْرَاءَ",uz:"sariq sochli"},{ar:"عَيْنَاهَا خَضْرَاوَانِ",uz:"ikki ko‘zi yashil"}],full_uz:"Sariq sochli, ko‘zlari yashil.",note:"خَضْرَاوَانِ — خَضْرَاءُ ning ikkilik shakli. عَيْنَاهَا — «uning ikki ko‘zi»."},
{num:146,time:"00:09:50,740 --> 00:09:54,780",arabic:"تُرِيدِينَ أَنْ أَتَزَوَّجَ مِنْ رُومِيَّةٍ؟",segs:[{ar:"تُرِيدِينَ أَنْ أَتَزَوَّجَ",uz:"uylanishimni istaysizmi"},{ar:"مِنْ رُومِيَّةٍ؟",uz:"rumlik ayolga?"}],full_uz:"Rumlik ayolga uylanishimni istaysizmi?",note:"رُومِيَّةٌ — «rumlik ayol»; nisbat sifatining muannas shakli."},
{num:147,time:"00:09:54,780 --> 00:09:57,139",arabic:"وَشَعْرُهَا يَا أُمِّي أَسْوَدُ.",segs:[{ar:"وَشَعْرُهَا",uz:"uning sochi esa"},{ar:"يَا أُمِّي",uz:"ey onajon"},{ar:"أَسْوَدُ",uz:"qora"}],full_uz:"Uning sochi esa qora bo‘lsin, onajon.",note:null},
{num:148,time:"00:09:57,139 --> 00:10:01,960",arabic:"أَيُّهَا الْأَحْمَقُ، كَيْفَ تَكُونُ شَقْرَاءَ وَشَعْرُهَا أَسْوَدُ؟",segs:[{ar:"أَيُّهَا الْأَحْمَقُ",uz:"ey ahmoq"},{ar:"كَيْفَ تَكُونُ شَقْرَاءَ",uz:"qanday sariq sochli bo‘ladi"},{ar:"وَشَعْرُهَا أَسْوَدُ؟",uz:"sochi qora bo‘la turib?"}],full_uz:"Ey ahmoq, sochi qora bo‘la turib qanday sariq sochli bo‘ladi?",note:"وَشَعْرُهَا أَسْوَدُ — hol gap: «sochi qora bo‘lgan holda»."},
{num:149,time:"00:10:01,960 --> 00:10:05,440",arabic:"أُمِّي، الْمُهِمُّ أَنْ تَكُونَ جَمِيلَةً مِثْلَكِ أَنْتِ.",segs:[{ar:"أُمِّي",uz:"onajon"},{ar:"الْمُهِمُّ أَنْ تَكُونَ جَمِيلَةً",uz:"muhimi, chiroyli bo‘lsin"},{ar:"مِثْلَكِ أَنْتِ",uz:"aynan siz kabi"}],full_uz:"Onajon, muhimi, siz kabi chiroyli bo‘lsin.",note:"أَنْتِ bu yerda مِثْلَكِ ni ta’kidlaydi: «sizning o‘zingiz kabi»."},
{num:150,time:"00:10:05,440 --> 00:10:09,480",arabic:"أَجْمَلِ نِسَاءِ بَغْدَادَ.",segs:null,full_uz:"Bag‘dod ayollarining eng go‘zali.",note:"أَجْمَلُ نِسَاءِ بَغْدَادَ — izofali orttirma daraja: «Bag‘dod ayollarining eng go‘zali»."},
{num:151,time:"00:10:09,480 --> 00:10:15,280",arabic:"لَا يَا أُمِّي، لَا تَبْدُو لِي الْفِكْرَةُ سَيِّئَةً.",segs:[{ar:"لَا يَا أُمِّي",uz:"yo‘q, onajon"},{ar:"لَا تَبْدُو لِي الْفِكْرَةُ سَيِّئَةً",uz:"bu fikr menga yomon ko‘rinmayapti"}],full_uz:"Yo‘q, onajon, bu fikr menga yomon ko‘rinmayapti.",note:"بَدَا لِي — «menga ... bo‘lib ko‘rindi». لَا تَبْدُو لِي — «menga ... bo‘lib ko‘rinmayapti»."},
{num:152,time:"00:10:15,280 --> 00:10:16,740",arabic:"أَلَمْ أَقُلْ إِنَّكَ أَحْمَقُ؟",segs:[{ar:"أَلَمْ أَقُلْ",uz:"aytmadimmi"},{ar:"إِنَّكَ أَحْمَقُ؟",uz:"sizning ahmoq ekaningizni?"}],full_uz:"Sizni ahmoq demaganmidim?",note:"أَقُولُ → لَمْ أَقُلْ: jazmda o‘rta illat harfi tushgan."},
{num:153,time:"00:10:16,740 --> 00:10:21,879",arabic:"مَا رَأْيُكِ يَا أُمِّي أَنْ نَأْخُذَ مُوَافَقَةَ أُمِّ عُمَيْرٍ؟",segs:[{ar:"مَا رَأْيُكِ يَا أُمِّي",uz:"nima deysiz, onajon"},{ar:"أَنْ نَأْخُذَ مُوَافَقَةَ أُمِّ عُمَيْرٍ؟",uz:"Ummu Umayrning roziligini olsak?"}],full_uz:"Nima deysiz, onajon, Ummu Umayrning roziligini olsak?",note:"أَخَذَ مُوَافَقَةَ شَخْصٍ — «bir kishining roziligini oldi»."},
{num:154,time:"00:10:21,879 --> 00:10:23,639",arabic:"تَعْسًا لَكَ وَلِمَنْ تُكَلِّمُكَ!",segs:[{ar:"تَعْسًا لَكَ",uz:"holingizga voy"},{ar:"وَلِمَنْ تُكَلِّمُكَ",uz:"siz bilan gaplashayotgan ayolning ham"}],full_uz:"Holingizga voy, siz bilan gaplashayotgan mening ham holimga voy!",note:"تَعْسًا لَكَ — qarg‘ish yoki keskin koyish ifodasi. تُكَلِّمُكَ ning muannas shakli gapirayotgan onaga ishora qiladi."},
{num:155,time:"00:10:23,639 --> 00:10:25,519",arabic:"أَنْتَ الرَّجُلُ أَمْ هِيَ؟",segs:[{ar:"أَنْتَ الرَّجُلُ",uz:"erkak sizmisiz"},{ar:"أَمْ هِيَ؟",uz:"yoki u ayolmi?"}],full_uz:"Erkak sizmisiz yoki u ayolmi?",note:null},
{num:156,time:"00:10:25,519 --> 00:10:27,159",arabic:"هِيَ... أَنَا، أَنَا يَا أُمِّي.",segs:[{ar:"هِيَ... أَنَا، أَنَا",uz:"u... men, men"},{ar:"يَا أُمِّي",uz:"ey onajon"}],full_uz:"U... men, men, onajon.",note:"Bu yerda so‘zlovchi avvalgi javobini darhol tuzatmoqda."},
{num:157,time:"00:10:27,159 --> 00:10:29,680",arabic:"وَلَكِنْ أَمْهِلِينِي بَعْضَ الْوَقْتِ لِأُفَكِّرَ.",segs:[{ar:"وَلَكِنْ أَمْهِلِينِي",uz:"lekin menga muhlat bering"},{ar:"بَعْضَ الْوَقْتِ",uz:"biroz vaqt"},{ar:"لِأُفَكِّرَ",uz:"o‘ylashim uchun"}],full_uz:"Lekin o‘ylashim uchun menga biroz muhlat bering.",note:"أَمْهِلِينِي — ayol kishiga buyruq: «menga muhlat bering». لِأُفَكِّرَ maqsadni bildiradi."},
{num:158,time:"00:10:29,680 --> 00:10:32,220",arabic:"حَسَنًا، وَلَكِنْ لَا تُبْطِئْ.",segs:[{ar:"حَسَنًا",uz:"xo‘p"},{ar:"وَلَكِنْ لَا تُبْطِئْ",uz:"lekin cho‘zib yubormang"}],full_uz:"Xo‘p, lekin cho‘zib yubormang.",note:"أَبْطَأَ — يُبْطِئُ — «sekinlashmoq, kechikmoq». Taqiqda لَا تُبْطِئْ bo‘ladi."},
{num:159,time:"00:10:32,220 --> 00:10:35,080",arabic:"لَنْ أُبْطِئَ، أَنَا ذَاهِبٌ إِلَى الدُّكَّانِ.",segs:[{ar:"لَنْ أُبْطِئَ",uz:"cho‘zib yubormayman"},{ar:"أَنَا ذَاهِبٌ إِلَى الدُّكَّانِ",uz:"men do‘konga ketyapman"}],full_uz:"Cho‘zib yubormayman, men do‘konga ketyapman.",note:null},
{num:160,time:"00:10:35,080 --> 00:10:37,080",arabic:"لَا تَنْسَ مَا اتَّفَقْنَا عَلَيْهِ.",segs:[{ar:"لَا تَنْسَ",uz:"unutmang"},{ar:"مَا اتَّفَقْنَا عَلَيْهِ",uz:"kelishgan narsamizni"}],full_uz:"Kelishgan narsamizni unutmang.",note:"تَنْسَى taqiqdagi لَا dan keyin لَا تَنْسَ bo‘ladi: oxirgi illat harfi tushadi."},
{num:161,time:"00:10:37,080 --> 00:10:39,379",arabic:"مَا هُوَ؟",segs:null,full_uz:"U nima edi?",note:null},
{num:162,time:"00:10:39,379 --> 00:10:41,480",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.",segs:[{ar:"لَا حَوْلَ وَلَا قُوَّةَ",uz:"hech qanday kuch-quvvat yo‘q"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Allohning yordami bilangina"}],full_uz:"Kuch-quvvat faqat Allohning yordami bilandir.",note:null},
{num:163,time:"00:10:41,480 --> 00:10:43,379",arabic:"اُغْرُبْ عَنْ وَجْهِي.",segs:null,full_uz:"Ko‘zimdan yo‘qoling.",note:"اُغْرُبْ عَنْ وَجْهِي — keskin haydash ifodasi: «ko‘zimdan yo‘qoling»."},
{num:164,time:"00:10:43,379 --> 00:10:45,480",arabic:"حَسَنًا يَا أُمِّي، تَذَكَّرْتُ.",segs:[{ar:"حَسَنًا يَا أُمِّي",uz:"xo‘p, onajon"},{ar:"تَذَكَّرْتُ",uz:"esladim"}],full_uz:"Xo‘p, onajon, esladim.",note:null},
{num:165,time:"00:10:45,480 --> 00:10:56,440",arabic:"مَمْشُوقَةُ الْقَوَامِ، فَارِعَةٌ، أَنْفُهَا إِبْرِيقُ الْفِضَّةِ، رَقَبَتُهَا كَالسَّيْفِ، عُيُونُهَا قَتَلْنَنَا ثُمَّ لَمْ يُحْيِينَ قَتْلَانَا... لَا، أَنَا ذَاهِبٌ إِلَى الدُّكَّانِ.",segs:[{ar:"مَمْشُوقَةُ الْقَوَامِ",uz:"qomati kelishgan"},{ar:"فَارِعَةٌ",uz:"uzun bo‘yli"},{ar:"أَنْفُهَا إِبْرِيقُ الْفِضَّةِ",uz:"burni kumush ko‘za"},{ar:"رَقَبَتُهَا كَالسَّيْفِ",uz:"bo‘yni qilichdek"},{ar:"عُيُونُهَا قَتَلْنَنَا",uz:"ko‘zlari bizni o‘ldirdi"},{ar:"ثُمَّ لَمْ يُحْيِينَ قَتْلَانَا",uz:"so‘ng o‘lganlarimizni tiriltirmadi"},{ar:"لَا",uz:"yo‘q"},{ar:"أَنَا ذَاهِبٌ إِلَى الدُّكَّانِ",uz:"men do‘konga ketyapman"}],full_uz:"Qomati kelishgan, uzun bo‘yli, burni kumush ko‘za, bo‘yni qilichdek, ko‘zlari bizni o‘ldirdi-yu, o‘lganlarimizni tiriltirmadi... Yo‘q, men do‘konga ketyapman.",note:"مَمْشُوقَةُ الْقَوَامِ — «qomati kelishgan». قَتَلْنَ va يُحْيِينَ da نَ ayollar ko‘pligini bildiradi; ko‘zlar she’riy tarzda jonlantirilgan."},
{num:166,time:"00:11:15,480 --> 00:11:23,759",arabic:"حَفِظَكَ اللَّهُ يَا وَلَدِي.",segs:[{ar:"حَفِظَكَ اللَّهُ",uz:"Alloh sizni asrasin"},{ar:"يَا وَلَدِي",uz:"ey bolam"}],full_uz:"Alloh sizni asrasin, bolam.",note:null},
{num:167,time:"00:11:23,759 --> 00:11:28,800",arabic:"وَتَقَبَّلَ مِنْكَ حَجَّكَ.",segs:[{ar:"وَتَقَبَّلَ مِنْكَ",uz:"va sizdan qabul qilsin"},{ar:"حَجَّكَ",uz:"hajingizni"}],full_uz:"Va hajingizni qabul qilsin.",note:"O‘tgan zamon shakli bu yerda duo bildiradi: تَقَبَّلَ — «qabul qilsin»."},
{num:168,time:"00:11:28,800 --> 00:11:32,920",arabic:"وَسَهَّلَ لَكَ أَسْبَابَ الْعِلْمِ.",segs:[{ar:"وَسَهَّلَ لَكَ",uz:"va siz uchun oson qilsin"},{ar:"أَسْبَابَ الْعِلْمِ",uz:"ilm olish vositalarini"}],full_uz:"Va sizga ilm olish yo‘llarini oson qilsin.",note:"أَسْبَابٌ bu yerda «sabablar»dan ko‘ra «vositalar, yo‘llar, imkoniyatlar» ma’nosida."},
{num:169,time:"00:11:32,920 --> 00:11:36,539",arabic:"بِمَا يُحِبُّهُ وَيَرْضَاهُ.",segs:[{ar:"بِمَا يُحِبُّهُ",uz:"O‘zi sevgan tarzda"},{ar:"وَيَرْضَاهُ",uz:"va rozi bo‘ladigan"}],full_uz:"O‘zi sevgan va rozi bo‘ladigan tarzda.",note:null},
{num:170,time:"00:11:36,539 --> 00:11:40,240",arabic:"آمِينَ.",segs:null,full_uz:"Omin.",note:null},
{num:171,time:"00:12:15,480 --> 00:12:28,539",arabic:"عَرُوسٌ جَدِيدَةٌ.",segs:null,full_uz:"Yangi kelin.",note:null},
{num:172,time:"00:12:30,779 --> 00:12:34,580",arabic:"لَكِنْ مَاذَا سَتَفْعَلُ بِابْنَةِ الْجَزَّارِ؟",segs:[{ar:"لَكِنْ مَاذَا سَتَفْعَلُ",uz:"lekin nima qilasiz"},{ar:"بِابْنَةِ الْجَزَّارِ؟",uz:"qassobning qizini?"}],full_uz:"Lekin qassobning qizini nima qilasiz?",note:null},
{num:173,time:"00:12:36,039 --> 00:12:38,039",arabic:"سَأَقُولُ لِأُمِّ عَامِرٍ: لَا.",segs:[{ar:"سَأَقُولُ لِأُمِّ عَامِرٍ",uz:"Ummu Omirga aytaman"},{ar:"لَا",uz:"yo‘q deb"}],full_uz:"Ummu Omirga yo‘q deyman.",note:null},
{num:174,time:"00:12:38,600 --> 00:12:43,960",arabic:"وَلَكِنْ لِمَ لَا؟",segs:null,full_uz:"Lekin nega yo‘q?",note:null},
{num:175,time:"00:12:43,960 --> 00:12:49,860",arabic:"إِذَا كَانَتِ الْعَرُوسُ جَدِيدَةً وَجَمِيلَةً وَخَجُولَةً...",segs:[{ar:"إِذَا كَانَتِ الْعَرُوسُ",uz:"agar kelin bo‘lsa"},{ar:"جَدِيدَةً وَجَمِيلَةً وَخَجُولَةً",uz:"yangi, chiroyli va uyatchan"}],full_uz:"Agar kelin yangi, chiroyli va uyatchan bo‘lsa...",note:"خَجُولَةٌ — «uyatchan». Sifatlar كَانَتْ ning xabari sifatida mansub kelgan."},
{num:176,time:"00:12:49,860 --> 00:12:52,900",arabic:"سَأَقُولُ لِأُمِّ عَامِرٍ: نَعَمْ.",segs:[{ar:"سَأَقُولُ لِأُمِّ عَامِرٍ",uz:"Ummu Omirga aytaman"},{ar:"نَعَمْ",uz:"ha deb"}],full_uz:"Ummu Omirga ha deyman.",note:null},
{num:177,time:"00:14:43,960 --> 00:14:48,740",arabic:"أَيُّهَا الْأَحْمَقُ، لَقَدْ جِئْتُ إِلَيْكَ بِمَسَاءَةٍ تُنْسِيكَ طَعَامَكَ الشَّهِيَّ هَذَا.",segs:[{ar:"أَيُّهَا الْأَحْمَقُ",uz:"ey ahmoq"},{ar:"لَقَدْ جِئْتُ إِلَيْكَ بِمَسَاءَةٍ",uz:"sizga noxush xabar olib keldim"},{ar:"تُنْسِيكَ",uz:"sizga unuttiradigan"},{ar:"طَعَامَكَ الشَّهِيَّ هَذَا",uz:"mana bu mazali taomingizni"}],full_uz:"Ey ahmoq, sizga mana bu mazali taomingizni unuttiradigan noxush xabar olib keldim.",note:"أَنْسَى — «unuttirdi». تُنْسِيكَ — «sizga unuttiradi». شَهِيٌّ — «ishtahani ochadigan, mazali»."},
{num:178,time:"00:14:48,740 --> 00:14:55,960",arabic:"بَعْدَ سُؤَالِي وَتَدْقِيقِي، تَبَيَّنَ أَنَّ اسْمَكَ لَمْ يَرِدْ فِي قَوَائِمِ الْمَطْلُوبِينَ.",segs:[{ar:"بَعْدَ سُؤَالِي وَتَدْقِيقِي",uz:"surishtirib, tekshirganimdan keyin"},{ar:"تَبَيَّنَ أَنَّ اسْمَكَ لَمْ يَرِدْ",uz:"ismingiz keltirilmagani aniqlandi"},{ar:"فِي قَوَائِمِ الْمَطْلُوبِينَ",uz:"qidiruvdagilar ro‘yxatlarida"}],full_uz:"Surishtirib, tekshirganimdan keyin ismingiz qidiruvdagilar ro‘yxatlarida yo‘qligi aniqlandi.",note:"وَرَدَ فِي الْقَائِمَةِ — «ro‘yxatda keltirildi». مَطْلُوبٌ bu yerda qidiruvdagi kishi."},
{num:179,time:"00:15:01,180 --> 00:15:02,500",arabic:"لَسْتُ مَطْلُوبًا لِأَحَدٍ؟",segs:[{ar:"لَسْتُ مَطْلُوبًا",uz:"qidiruvda emasmanmi"},{ar:"لِأَحَدٍ؟",uz:"hech kim tomonidan?"}],full_uz:"Meni hech kim qidirmayaptimi?",note:null},
{num:180,time:"00:15:02,500 --> 00:15:04,960",arabic:"أَمُتَأَكِّدٌ أَنْتَ؟",segs:null,full_uz:"Ishonchingiz komilmi?",note:null},
{num:181,time:"00:15:05,560 --> 00:15:10,360",arabic:"كَمَا سَمِعْتَ، يَبْدُو أَنَّكَ أَدْنَى مِنْ أَنْ يُهْتَمَّ بِكَ يَا صَاحِبَ شَفِيعٍ.",segs:[{ar:"كَمَا سَمِعْتَ",uz:"eshitganingizdek"},{ar:"يَبْدُو أَنَّكَ أَدْنَى",uz:"aftidan, siz juda arzimas ekansiz"},{ar:"مِنْ أَنْ يُهْتَمَّ بِكَ",uz:"sizga e’tibor berilishi uchun"},{ar:"يَا صَاحِبَ شَفِيعٍ",uz:"ey Shafi’ning do‘sti"}],full_uz:"Eshitganingizdek. Aftidan, siz e’tibor berishga ham arzimaysiz, ey Shafi’ning do‘sti.",note:"يُهْتَمَّ بِكَ — majhul nisbat: «sizga e’tibor berilishi». أَدْنَى مِنْ أَنْ... bu yerda kamsitish ma’nosida."},
{num:182,time:"00:15:13,960 --> 00:15:19,280",arabic:"حَدَّثَنَا عَمْرُو بْنُ دِينَارٍ عَنْ أَبِي قَابُوسَ.",segs:[{ar:"حَدَّثَنَا عَمْرُو بْنُ دِينَارٍ",uz:"bizga Amr ibn Dinor rivoyat qildi"},{ar:"عَنْ أَبِي قَابُوسَ",uz:"Abu Qobusdan"}],full_uz:"Bizga Amr ibn Dinor Abu Qobusdan rivoyat qildi.",note:"حَدَّثَنَا — «bizga rivoyat qildi». Isnodda عَنْ rivoyat kimdan olinganini bildiradi."},
{num:183,time:"00:15:19,280 --> 00:15:22,820",arabic:"عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ.",segs:null,full_uz:"Abdulloh ibn Amr ibn Osdan.",note:"عَمْرِو ismidagi oxirgi و talaffuz qilinmaydi."},
{num:184,time:"00:15:22,820 --> 00:15:26,700",arabic:"عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:[{ar:"عَنْ رَسُولِ اللَّهِ",uz:"Alloh Rasulidan"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Alloh Rasulidan, Alloh unga salovot va salom yo‘llasin.",note:null},
{num:185,time:"00:15:26,700 --> 00:15:30,120",arabic:"أَنَّهُ كَانَ يَقُولُ...",segs:null,full_uz:"U zot shunday der edilar...",note:null},
{num:186,time:"00:15:30,120 --> 00:15:33,660",arabic:"الرَّاحِمُونَ يَرْحَمُهُمُ اللَّهُ.",segs:[{ar:"الرَّاحِمُونَ",uz:"rahm qiluvchilar"},{ar:"يَرْحَمُهُمُ اللَّهُ",uz:"ularga Alloh rahm qiladi"}],full_uz:"Rahm qiluvchilarga Alloh rahm qiladi.",note:"رَاحِمٌ — «rahm qiluvchi»; الرَّاحِمُونَ — uning muzakkar solim ko‘pligi."},
{num:187,time:"00:15:33,660 --> 00:15:36,860",arabic:"اِرْحَمُوا أَهْلَ الْأَرْضِ.",segs:[{ar:"اِرْحَمُوا",uz:"rahm qilinglar"},{ar:"أَهْلَ الْأَرْضِ",uz:"yer ahliga"}],full_uz:"Yer ahliga rahm qilinglar.",note:null},
{num:188,time:"00:15:36,860 --> 00:15:39,920",arabic:"يَرْحَمْكُمْ أَهْلُ السَّمَاءِ.",segs:[{ar:"يَرْحَمْكُمْ",uz:"sizlarga rahm qiladi"},{ar:"أَهْلُ السَّمَاءِ",uz:"osmon ahli"}],full_uz:"Osmon ahli sizlarga rahm qiladi.",note:"يَرْحَمْ buyruqning natijasi bo‘lgani uchun majzum: «rahm qilinglar — sizlarga rahm qilinadi»."},
{num:189,time:"00:15:39,919 --> 00:15:44,659",arabic:"الرَّحِمُ شُجْنَةٌ مِنَ الرَّحْمَنِ.",segs:[{ar:"الرَّحِمُ",uz:"qarindoshlik rishtasi"},{ar:"شُجْنَةٌ مِنَ الرَّحْمَنِ",uz:"Rahmon bilan bog‘liq bir rishtadir"}],full_uz:"Qarindoshlik rishtasi Rahmon bilan bog‘liq bir rishtadir.",note:"الرَّحِمُ bu yerda «qarindoshlik aloqasi». شُجْنَةٌ — bir-biriga tutashgan shox yoki rishta; ma’naviy bog‘liqlik tasvirlangan."},
{num:190,time:"00:15:44,659 --> 00:15:48,000",arabic:"مَنْ قَطَعَهَا قَطَعَهُ اللَّهُ.",segs:[{ar:"مَنْ قَطَعَهَا",uz:"kim uni uzsa"},{ar:"قَطَعَهُ اللَّهُ",uz:"Alloh undan aloqani uzadi"}],full_uz:"Kim uni uzsa, Alloh undan aloqani uzadi.",note:"مَنْ — shart olmoshi. هَا qarindoshlik rishtasiga, هُ esa uni uzgan kishiga qaytadi."},
{num:191,time:"00:15:48,000 --> 00:15:51,279",arabic:"وَمَنْ وَصَلَهَا وَصَلَهُ اللَّهُ.",segs:[{ar:"وَمَنْ وَصَلَهَا",uz:"kim uni bog‘lasa"},{ar:"وَصَلَهُ اللَّهُ",uz:"Alloh u bilan aloqani bog‘laydi"}],full_uz:"Kim qarindoshlik rishtasini bog‘lasa, Alloh u bilan aloqani bog‘laydi.",note:"وَصَلَ الرَّحِمَ — «qarindoshlik aloqasini saqladi»."},
{num:192,time:"00:16:09,919 --> 00:16:18,559",arabic:"كُنْ مُطْمَئِنًّا يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"كُنْ مُطْمَئِنًّا",uz:"xotirjam bo‘ling"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh"}],full_uz:"Xotirjam bo‘ling, Abu Abdulloh.",note:"مُطْمَئِنٌّ — «xotirjam». كُنْ dan keyin xabar mansub keladi: مُطْمَئِنًّا."},
{num:193,time:"00:16:18,559 --> 00:16:22,079",arabic:"فَشَيْخُنَا الْمَرِيسِيُّ فِي مَكَانٍ آمِنٍ، وَالْحَمْدُ لِلَّهِ.",segs:[{ar:"فَشَيْخُنَا الْمَرِيسِيُّ",uz:"shayximiz Marisiy"},{ar:"فِي مَكَانٍ آمِنٍ",uz:"xavfsiz joyda"},{ar:"وَالْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"}],full_uz:"Shayximiz Marisiy xavfsiz joyda, Allohga hamd bo‘lsin.",note:null},
{num:194,time:"00:16:22,079 --> 00:16:23,899",arabic:"الْحَمْدُ لِلَّهِ.",segs:null,full_uz:"Allohga hamd bo‘lsin.",note:null},
{num:195,time:"00:16:23,899 --> 00:16:27,579",arabic:"وَلَكِنَّنَا فِي قَلَقٍ عَلَى الشَّيْخِ ابْنِ الْأَشْرَسِ.",segs:[{ar:"وَلَكِنَّنَا فِي قَلَقٍ",uz:"lekin biz xavotirdamiz"},{ar:"عَلَى الشَّيْخِ ابْنِ الْأَشْرَسِ",uz:"shayx Ibn Ashras uchun"}],full_uz:"Lekin shayx Ibn Ashras uchun xavotirdamiz.",note:"قَلَقٌ عَلَى شَخْصٍ — «bir kishi uchun xavotir»."},
{num:196,time:"00:16:27,579 --> 00:16:28,699",arabic:"لَا تَقْلَقُوا عَلَيْهِ.",segs:null,full_uz:"U uchun xavotir olmanglar.",note:null},
{num:197,time:"00:16:28,699 --> 00:16:32,579",arabic:"فَهُوَ بِخَيْرٍ مَا دَامَ لِسَانُهُ بِخَيْرٍ.",segs:[{ar:"فَهُوَ بِخَيْرٍ",uz:"uning holi yaxshi"},{ar:"مَا دَامَ لِسَانُهُ بِخَيْرٍ",uz:"tili yaxshi ishlab turgan ekan"}],full_uz:"Tili yaxshi ishlab turgan ekan, uning holi ham yaxshi.",note:"مَا دَامَ — «...ekan, ...guncha». Bu yerda uning gapga ustaligi nazarda tutilgan."},
{num:198,time:"00:16:32,579 --> 00:16:35,699",arabic:"عِنْدَكَ خَبَرٌ عَنْهُ؟",segs:null,full_uz:"U haqida xabaringiz bormi?",note:null},
{num:199,time:"00:16:36,079 --> 00:16:39,379",arabic:"قَدْ أَخْبَرَنِي يَحْيَى بْنُ أَكْثَمَ...",segs:[{ar:"قَدْ أَخْبَرَنِي",uz:"menga xabar berdi"},{ar:"يَحْيَى بْنُ أَكْثَمَ",uz:"Yahyo ibn Aksam"}],full_uz:"Menga Yahyo ibn Aksam xabar berdi...",note:null},
{num:200,time:"00:16:39,379 --> 00:16:43,080",arabic:"أَنَّ ابْنَ الْأَشْرَسِ صَارَ مِنْ جُلَسَاءِ هَارُونَ.",segs:[{ar:"أَنَّ ابْنَ الْأَشْرَسِ صَارَ",uz:"Ibn Ashras aylanganini"},{ar:"مِنْ جُلَسَاءِ هَارُونَ",uz:"Horunning suhbatdoshlaridan biriga"}],full_uz:"Ibn Ashras Horunning suhbatdoshlaridan biriga aylanganini.",note:"جُلَسَاءُ — جَلِيسٌ ning ko‘pligi: birga o‘tiradigan suhbatdoshlar."},
{num:201,time:"00:16:43,080 --> 00:16:45,840",arabic:"وَرُبَّمَا مِنْ نُدَمَائِهِ.",segs:null,full_uz:"Balki uning yaqin bazmdoshlaridan ham.",note:"نُدَمَاءُ — نَدِيمٌ ning ko‘pligi: yaqin suhbatdosh, bazmdosh."},
{num:202,time:"00:16:45,840 --> 00:16:50,759",arabic:"فَلَا تَنْقُصُهُ الْحِيلَةُ.",segs:null,full_uz:"Axir unga hiyla yetishmaydi emas.",note:"لَا تَنْقُصُهُ الْحِيلَةُ — «u hiyla topishga usta, chorasiz qolmaydi»."},
{num:203,time:"00:16:50,759 --> 00:16:54,240",arabic:"لِأَنَّ لِسَانَهُ يُطَوِّقُ أَعْنَاقَ الرِّجَالِ.",segs:[{ar:"لِأَنَّ لِسَانَهُ",uz:"chunki uning tili"},{ar:"يُطَوِّقُ أَعْنَاقَ الرِّجَالِ",uz:"kishilarning bo‘ynini halqadek o‘raydi"}],full_uz:"Chunki u tili bilan kishilarni o‘ziga bo‘ysundiradi.",note:"طَوَّقَ — «halqadek o‘radi». Bu yerda so‘z bilan odamlarni o‘ziga qaratish tasvirlangan."},
{num:204,time:"00:16:54,240 --> 00:16:55,700",arabic:"أَحَقًّا؟",segs:null,full_uz:"Rostdanmi?",note:null},
{num:205,time:"00:16:55,700 --> 00:16:57,939",arabic:"أَجَلْ يَا بَدْرُ.",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"يَا بَدْرُ",uz:"ey Badr"}],full_uz:"Ha, Badr.",note:null},
{num:206,time:"00:16:57,939 --> 00:17:01,639",arabic:"لَا تَخَفْ عَلَى ابْنِ الْأَشْرَسِ.",segs:[{ar:"لَا تَخَفْ",uz:"xavotir olmang"},{ar:"عَلَى ابْنِ الْأَشْرَسِ",uz:"Ibn Ashras uchun"}],full_uz:"Ibn Ashras uchun xavotir olmang.",note:"خَافَ عَلَى — «uchun xavotirlandi»; خَافَ مِنْ — «...dan qo‘rqdi»."},
{num:207,time:"00:17:01,639 --> 00:17:05,740",arabic:"لِأَنَّهُ لَنْ يُسَلِّمَهُمْ قِيَادَهُ.",segs:[{ar:"لِأَنَّهُ لَنْ يُسَلِّمَهُمْ",uz:"chunki u ularga topshirmaydi"},{ar:"قِيَادَهُ",uz:"o‘z jilovini"}],full_uz:"Chunki u o‘z jilovini ularning qo‘liga topshirmaydi.",note:"قِيَادٌ — «jilov». سَلَّمَ قِيَادَهُ — ko‘chma ma’noda «o‘z ixtiyorini topshirdi»."},
{num:208,time:"00:17:05,740 --> 00:17:08,740",arabic:"وَلَقَدْ وَجَدَ لِنَفْسِهِ مَنْجًى.",segs:[{ar:"وَلَقَدْ وَجَدَ لِنَفْسِهِ",uz:"u o‘zi uchun topdi"},{ar:"مَنْجًى",uz:"najot yo‘lini"}],full_uz:"U o‘zi uchun najot yo‘lini topdi.",note:"مَنْجًى — «qutulish yo‘li, najot joyi»."},
{num:209,time:"00:17:09,380 --> 00:17:22,480",arabic:"يَا شَيْخَنَا.",segs:null,full_uz:"Ey shayximiz.",note:null},
{num:210,time:"00:17:22,480 --> 00:17:25,680",arabic:"نَحْنُ مِنْ بَغْدَادَ.",segs:null,full_uz:"Biz Bag‘doddanmiz.",note:null},
{num:211,time:"00:17:25,680 --> 00:17:29,420",arabic:"مُنْذُ صِغَرِنَا وَنَحْنُ نَحْلُمُ بِلِقَائِكَ.",segs:[{ar:"مُنْذُ صِغَرِنَا",uz:"bolaligimizdan beri"},{ar:"وَنَحْنُ نَحْلُمُ بِلِقَائِكَ",uz:"siz bilan uchrashishni orzu qilamiz"}],full_uz:"Bolaligimizdan beri siz bilan uchrashishni orzu qilamiz.",note:"حَلِمَ بِـ — «...ni orzu qildi»."},
{num:212,time:"00:17:29,420 --> 00:17:33,020",arabic:"لَيْتَكُمْ بَقِيتُمْ فِي بَغْدَادَ تَحْلُمُونَ.",segs:[{ar:"لَيْتَكُمْ بَقِيتُمْ فِي بَغْدَادَ",uz:"qaniydi Bag‘dodda qolgan bo‘lsangizlar"},{ar:"تَحْلُمُونَ",uz:"orzu qilib"}],full_uz:"Qaniydi Bag‘dodda orzu qilib qolgan bo‘lsangizlar.",note:"لَيْتَ — «qaniydi». تَحْلُمُونَ bu yerda qolish paytidagi holatni bildiradi."},
{num:213,time:"00:17:33,020 --> 00:17:36,640",arabic:"وَكَأَنَّ شَيْخَنَا قَدْ كَرِهَ لِقَاءَنَا.",segs:[{ar:"وَكَأَنَّ شَيْخَنَا",uz:"go‘yo shayximiz"},{ar:"قَدْ كَرِهَ لِقَاءَنَا",uz:"biz bilan uchrashishni yoqtirmagandek"}],full_uz:"Go‘yo shayximiz biz bilan uchrashishni yoqtirmagandek.",note:null},
{num:214,time:"00:17:36,640 --> 00:17:39,360",arabic:"بَلْ كَرِهْتُ لَكُمْ مَآلَكُمْ.",segs:[{ar:"بَلْ كَرِهْتُ لَكُمْ",uz:"aksincha, sizlar uchun yomon ko‘rdim"},{ar:"مَآلَكُمْ",uz:"kelajakdagi oqibatingizni"}],full_uz:"Aksincha, kelajakdagi oqibatingizdan sizlar uchun xavotirlandim.",note:"مَآلٌ — «oqibat, oxir-oqibat boriladigan holat». كَرِهْتُ لَكُمْ — «sizlarga ravo ko‘rmadim»."},
{num:215,time:"00:17:39,359 --> 00:17:40,139",arabic:"أَيُّهَا الْفِتْيَةُ.",segs:null,full_uz:"Ey yigitlar.",note:null},
{num:216,time:"00:17:40,139 --> 00:17:44,439",arabic:"وَهَلْ فِي طَلَبِنَا لِلْحَدِيثِ مَا يُكْرَهُ يَا شَيْخَنَا؟",segs:[{ar:"وَهَلْ فِي طَلَبِنَا لِلْحَدِيثِ",uz:"hadis o‘rganishga intilishimizda bormi"},{ar:"مَا يُكْرَهُ",uz:"yomon ko‘riladigan biror narsa"},{ar:"يَا شَيْخَنَا؟",uz:"ey shayximiz?"}],full_uz:"Hadis o‘rganishga intilishimizda yomon ko‘riladigan biror narsa bormi, shayximiz?",note:"طَلَبُ الْحَدِيثِ — hadis izlash va o‘rganish. يُكْرَهُ — «yomon ko‘riladi», majhul nisbat."},
{num:217,time:"00:17:44,439 --> 00:17:45,119",arabic:"مَعَاذَ اللَّهِ.",segs:null,full_uz:"Alloh saqlasin.",note:"مَعَاذَ اللَّهِ keskin rad etish yoki Allohdan panoh so‘rash ifodasi."},
{num:218,time:"00:17:45,119 --> 00:17:49,539",arabic:"لَا، طَلَبُ الْعِلْمِ أَجَلُّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"طَلَبُ الْعِلْمِ أَجَلُّ",uz:"ilm talab qilish ulug‘roqdir"},{ar:"مِمَّا طَلَعَتْ عَلَيْهِ الشَّمْسُ",uz:"quyosh chiqqan barcha narsalardan"}],full_uz:"Yo‘q, ilm talab qilish quyosh nuri tushgan barcha narsalardan ulug‘roqdir.",note:"أَجَلُّ — «ulug‘roq, yuksakroq». مَا طَلَعَتْ عَلَيْهِ الشَّمْسُ dunyodagi narsalarni umumlashtirib bildiradi."},
{num:219,time:"00:17:49,539 --> 00:17:56,359",arabic:"وَلَكِنْ أَتَعْرِفُونَ مَا مَعْنَى طَلَبِ حَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟",segs:[{ar:"وَلَكِنْ أَتَعْرِفُونَ",uz:"lekin bilasizlarmi"},{ar:"مَا مَعْنَى طَلَبِ حَدِيثِ رَسُولِ اللَّهِ",uz:"Alloh Rasulining hadislarini o‘rganish nimani anglatishini"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Lekin Alloh Rasulining hadislarini o‘rganish nimani anglatishini bilasizlarmi? Alloh unga salovot va salom yo‘llasin.",note:null},
{num:220,time:"00:17:56,359 --> 00:17:58,000",arabic:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:null,full_uz:"Alloh unga salovot va salom yo‘llasin.",note:null},
{num:221,time:"00:17:58,000 --> 00:18:01,699",arabic:"بَعْضُ الطَّلَبَةِ مِنْ قِصَارِ النَّظَرِ وَالْبَصَرِ...",segs:[{ar:"بَعْضُ الطَّلَبَةِ",uz:"ayrim talabalar"},{ar:"مِنْ قِصَارِ النَّظَرِ وَالْبَصَرِ",uz:"uzoqni ko‘rolmaydigan kishilardan"}],full_uz:"Uzoqni ko‘rolmaydigan ayrim talabalar...",note:"قِصَارُ النَّظَرِ — ko‘chma ma’noda oqibatni chuqur o‘ylamaydigan kishilar."},
{num:222,time:"00:18:01,699 --> 00:18:05,039",arabic:"يَنْظُرُونَ إِلَى التَّشْرِيفِ وَيَنْسَوْنَ التَّكْلِيفَ.",segs:[{ar:"يَنْظُرُونَ إِلَى التَّشْرِيفِ",uz:"sharafga qaraydilar"},{ar:"وَيَنْسَوْنَ التَّكْلِيفَ",uz:"mas’uliyatni esa unutadilar"}],full_uz:"Sharafga qaraydilar-u, mas’uliyatni unutadilar.",note:"تَشْرِيفٌ — «sharaf berish»; تَكْلِيفٌ — «vazifa va mas’uliyat yuklash»."},
{num:223,time:"00:18:05,039 --> 00:18:09,480",arabic:"إِنَّ رِوَايَةَ حَدِيثِ الْمُصْطَفَى صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ...",segs:[{ar:"إِنَّ رِوَايَةَ حَدِيثِ الْمُصْطَفَى",uz:"albatta, Mustafoning hadislarini rivoyat qilish"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Albatta, Mustafoning hadislarini rivoyat qilish, Alloh unga salovot va salom yo‘llasin...",note:"الْمُصْطَفَى — «tanlangan zot», bu yerda Payg‘ambarga nisbatan qo‘llangan."},
{num:224,time:"00:18:10,920 --> 00:18:16,139",arabic:"أَمَانَةٌ عَظِيمَةٌ، لِأَنَّ اللَّهَ سَائِلُهُمْ عَنْ أَدَائِهِ وَتَبْلِيغِهِ.",segs:[{ar:"أَمَانَةٌ عَظِيمَةٌ",uz:"ulkan omonatdir"},{ar:"لِأَنَّ اللَّهَ سَائِلُهُمْ",uz:"chunki Alloh ulardan so‘raydi"},{ar:"عَنْ أَدَائِهِ وَتَبْلِيغِهِ",uz:"uni ado etish va yetkazish haqida"}],full_uz:"Ulkan omonatdir, chunki Alloh ulardan uni ado etish va yetkazish haqida so‘raydi.",note:"سَائِلٌ — «so‘rovchi»; bu yerda kelajakda so‘rashni bildiradi. تَبْلِيغٌ — «yetkazish»."},
{num:225,time:"00:18:16,139 --> 00:18:24,159",arabic:"قَالَ تَعَالَى: فَلَوْلَا نَفَرَ مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ طَائِفَةٌ لِيَتَفَقَّهُوا فِي الدِّينِ.",segs:[{ar:"قَالَ تَعَالَى",uz:"Alloh taolo aytdi"},{ar:"فَلَوْلَا نَفَرَ",uz:"nega yo‘lga chiqmasa"},{ar:"مِنْ كُلِّ فِرْقَةٍ مِنْهُمْ",uz:"ularning har bir guruhidan"},{ar:"طَائِفَةٌ",uz:"bir toifa"},{ar:"لِيَتَفَقَّهُوا فِي الدِّينِ",uz:"dinni chuqur anglashlari uchun"}],full_uz:"Alloh taolo aytdi: «Ularning har bir guruhidan bir toifa dinni chuqur anglash uchun yo‘lga chiqsa edi».",note:"لَوْلَا bu yerda undash ma’nosida: «nega ... qilmasin?». تَفَقَّهَ — «chuqur anglab yetdi»."},
{num:226,time:"00:18:24,159 --> 00:18:25,480",arabic:"أَكْمِلْ.",segs:null,full_uz:"Davom ettiring.",note:null},
{num:227,time:"00:18:25,480 --> 00:18:30,319",arabic:"وَلِيُنْذِرُوا قَوْمَهُمْ إِذَا رَجَعُوا إِلَيْهِمْ لَعَلَّهُمْ يَحْذَرُونَ.",segs:[{ar:"وَلِيُنْذِرُوا قَوْمَهُمْ",uz:"va o‘z qavmlarini ogohlantirishlari uchun"},{ar:"إِذَا رَجَعُوا إِلَيْهِمْ",uz:"ularning oldiga qaytganlarida"},{ar:"لَعَلَّهُمْ يَحْذَرُونَ",uz:"shoyad ular ehtiyot bo‘lsalar"}],full_uz:"Va qavmlari oldiga qaytganlarida ularni ogohlantirishlari uchun, shoyad ular ehtiyot bo‘lsalar.",note:"أَنْذَرَ — «ogohlantirdi». لَعَلَّ bu yerda ko‘zlangan natijani bildiradi."},
{num:228,time:"00:18:30,319 --> 00:18:35,619",arabic:"وَالتَّفَقُّهُ الَّذِي عَنَتْهُ الْآيَةُ لَيْسَ الْحِفْظَ الظَّاهِرَ فَحَسْبُ.",segs:[{ar:"وَالتَّفَقُّهُ",uz:"chuqur anglash esa"},{ar:"الَّذِي عَنَتْهُ الْآيَةُ",uz:"oyat nazarda tutgan"},{ar:"لَيْسَ الْحِفْظَ الظَّاهِرَ فَحَسْبُ",uz:"faqat yuzaki yodlash emas"}],full_uz:"Oyat nazarda tutgan chuqur anglash faqat yuzaki yodlash emas.",note:"عَنَى — «nazarda tutdi». فَحَسْبُ — «xolos, faqat shuning o‘zi»."},
{num:229,time:"00:18:35,619 --> 00:18:40,919",arabic:"بَلْ إِضَافَةً إِلَى ذَلِكَ أَنْ تَتَشَرَّبَ رُوحُكَ الْعِلْمَ وَالدِّينَ.",segs:[{ar:"بَلْ إِضَافَةً إِلَى ذَلِكَ",uz:"balki bunga qo‘shimcha ravishda"},{ar:"أَنْ تَتَشَرَّبَ رُوحُكَ",uz:"ruhingiz singdirib olishi"},{ar:"الْعِلْمَ وَالدِّينَ",uz:"ilm va dinni"}],full_uz:"Balki bunga qo‘shimcha ravishda ruhingiz ilm va dinni o‘ziga singdirib olishidir.",note:"تَشَرَّبَ — «singdirib oldi»; ilm yoki g‘oya qalbga chuqur o‘rnashishiga nisbatan ham ishlatiladi."},
{num:230,time:"00:18:40,919 --> 00:18:46,579",arabic:"فَتَفِيضَ بِهِمَا جَوَارِحُكَ فِي حَيَاتِكَ سُلُوكًا وَعَمَلًا.",segs:[{ar:"فَتَفِيضَ بِهِمَا جَوَارِحُكَ",uz:"shunda a’zolaringiz u ikkisiga to‘lib-toshsin"},{ar:"فِي حَيَاتِكَ",uz:"hayotingizda"},{ar:"سُلُوكًا وَعَمَلًا",uz:"xulq va amal sifatida"}],full_uz:"Shunda ilm va din hayotingizda a’zolaringiz orqali xulq va amal sifatida namoyon bo‘lsin.",note:"جَوَارِحُ — insonning amal qiladigan tana a’zolari. بِهِمَا dagi ikkilik ilm va dinga qaytadi."},
{num:231,time:"00:18:46,579 --> 00:18:49,859",arabic:"وَأَيُّ شَقِيٍّ هُوَ سُفْيَانُ بْنُ عُيَيْنَةَ...",segs:[{ar:"وَأَيُّ شَقِيٍّ هُوَ",uz:"naqadar baxtsiz bo‘ladi u"},{ar:"سُفْيَانُ بْنُ عُيَيْنَةَ",uz:"Sufyon ibn Uyayna"}],full_uz:"Sufyon ibn Uyayna naqadar baxtsiz bo‘ladi...",note:"أَيُّ شَقِيٍّ bu yerda savol emas, kuchli taajjub va tashvishni bildiradi."},
{num:232,time:"00:18:49,859 --> 00:18:55,059",arabic:"إِنْ أَخْطَأَ فِي حَرْفٍ مِنْ عِنْدِهِ وَنَسَبَهُ إِلَى نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:[{ar:"إِنْ أَخْطَأَ فِي حَرْفٍ مِنْ عِنْدِهِ",uz:"agar o‘zidan bir harfda xato qilsa"},{ar:"وَنَسَبَهُ إِلَى نَبِيِّهِ",uz:"va uni Payg‘ambariga nisbat bersa"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Agar o‘zidan bir harfda xato qilib, uni Payg‘ambariga nisbat bersa. Alloh unga salovot va salom yo‘llasin.",note:"نَسَبَ شَيْئًا إِلَى شَخْصٍ — «bir narsani bir kishiga nisbat berdi»."},
{num:233,time:"00:18:57,079 --> 00:18:59,980",arabic:"وَلِحِرْصِنَا عَلَى مَا قُلْتَ يَا شَيْخَنَا قَصَدْنَاكَ.",segs:[{ar:"وَلِحِرْصِنَا عَلَى مَا قُلْتَ",uz:"aytgan narsangizga intilganimiz uchun"},{ar:"يَا شَيْخَنَا",uz:"ey shayximiz"},{ar:"قَصَدْنَاكَ",uz:"sizning oldingizga keldik"}],full_uz:"Aynan aytgan narsangizga intilganimiz uchun oldingizga keldik, shayximiz.",note:"حِرْصٌ عَلَى — «bir narsaga qattiq intilish». قَصَدْنَاكَ — «sizni maqsad qilib keldik»."},
{num:234,time:"00:18:59,980 --> 00:19:02,400",arabic:"نَبْتَغِي عِلْمَكَ وَنَطْلُبُ أَدَبَكَ.",segs:[{ar:"نَبْتَغِي عِلْمَكَ",uz:"ilmingizni izlaymiz"},{ar:"وَنَطْلُبُ أَدَبَكَ",uz:"va odobingizni o‘rganishni istaymiz"}],full_uz:"Ilmingizni va odobingizni o‘rganishni istaymiz.",note:"اِبْتَغَى — «izladi, talab qildi»."},
{num:235,time:"00:19:02,400 --> 00:19:04,940",arabic:"بَارَكَ اللَّهُ فِيكُمْ أَيُّهَا الْفِتْيَةُ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكُمْ",uz:"Alloh sizlarga baraka bersin"},{ar:"أَيُّهَا الْفِتْيَةُ",uz:"ey yigitlar"}],full_uz:"Alloh sizlarga baraka bersin, yigitlar.",note:null},
{num:236,time:"00:19:04,940 --> 00:19:08,180",arabic:"وَاعْذُرُونِي إِنْ أَنَا شَقَقْتُ عَلَيْكُمْ.",segs:[{ar:"وَاعْذُرُونِي",uz:"meni kechiringlar"},{ar:"إِنْ أَنَا شَقَقْتُ عَلَيْكُمْ",uz:"agar sizlarga qattiqlik qilgan bo‘lsam"}],full_uz:"Agar sizlarga qattiqlik qilgan bo‘lsam, meni kechiringlar.",note:"شَقَّ عَلَى شَخْصٍ — «unga og‘irlik qildi». شَقَقْتُ da shadda ochilgan."},
{num:237,time:"00:19:08,180 --> 00:19:10,539",arabic:"فَسَتَعْلَمُونَ مَا أَقُولُ لَكُمْ.",segs:[{ar:"فَسَتَعْلَمُونَ",uz:"keyin tushunasizlar"},{ar:"مَا أَقُولُ لَكُمْ",uz:"sizlarga aytayotgan gapimni"}],full_uz:"Sizlarga aytayotgan gapimni keyin tushunasizlar.",note:null},
{num:238,time:"00:19:10,539 --> 00:19:12,000",arabic:"السَّلَامُ عَلَيْكُمْ.",segs:null,full_uz:"Assalomu alaykum.",note:null},
{num:239,time:"00:19:12,000 --> 00:19:14,980",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"sizga ham tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"va Allohning rahmati hamda barakalari"}],full_uz:"Sizga ham tinchlik, Allohning rahmati va barakalari bo‘lsin.",note:null},
{num:240,time:"00:19:15,880 --> 00:19:25,740",arabic:"أَلَا تُحَدِّثُنَا يَا شَيْخُ؟",segs:[{ar:"أَلَا تُحَدِّثُنَا",uz:"bizga hadis rivoyat qilib bermaysizmi"},{ar:"يَا شَيْخُ؟",uz:"ey shayx?"}],full_uz:"Bizga hadis rivoyat qilib bermaysizmi, shayx?",note:"أَلَا bu yerda iltimos yoki taklif bildiradi."},
{num:241,time:"00:19:29,980 --> 00:19:38,440",arabic:"حَدَّثَنِي الرَّبِيعُ بْنُ صَبِيحٍ عَنِ الْحَسَنِ عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، قَالَتْ...",segs:[{ar:"حَدَّثَنِي الرَّبِيعُ بْنُ صَبِيحٍ",uz:"menga Rabi’ ibn Sabih rivoyat qildi"},{ar:"عَنِ الْحَسَنِ",uz:"Hasandan"},{ar:"عَنْ عَائِشَةَ",uz:"Oishadan"},{ar:"رَضِيَ اللَّهُ عَنْهَا",uz:"Alloh undan rozi bo‘lsin"},{ar:"قَالَتْ",uz:"u aytdi"}],full_uz:"Menga Rabi’ ibn Sabih Hasandan, u Oishadan rivoyat qildi. Alloh undan rozi bo‘lsin. U aytdi...",note:"قَالَتْ muannas shaklda kelib, Oishaga tegishli."},
{num:242,time:"00:19:38,440 --> 00:19:45,279",arabic:"لَوْ أَدْرَكْتُ لَيْلَةَ الْقَدْرِ مَا سَأَلْتُ اللَّهَ إِلَّا الْعَفْوَ وَالْعَافِيَةَ.",segs:[{ar:"لَوْ أَدْرَكْتُ لَيْلَةَ الْقَدْرِ",uz:"agar Qadr kechasiga yetishsam"},{ar:"مَا سَأَلْتُ اللَّهَ إِلَّا",uz:"Allohdan faqat so‘rardim"},{ar:"الْعَفْوَ وَالْعَافِيَةَ",uz:"afv va ofiyatni"}],full_uz:"Qadr kechasiga yetishsam, Allohdan faqat afv va ofiyat so‘rardim.",note:"عَفْوٌ — «kechirish»; عَافِيَةٌ — «salomatlik, balo va zararlaridan omonlik»."},
{num:243,time:"00:19:45,279 --> 00:19:50,099",arabic:"اللَّهُمَّ إِنَّا نَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ.",segs:[{ar:"اللَّهُمَّ",uz:"Allohim"},{ar:"إِنَّا نَسْأَلُكَ",uz:"biz Sendan so‘raymiz"},{ar:"الْعَفْوَ وَالْعَافِيَةَ",uz:"afv va ofiyatni"}],full_uz:"Allohim, biz Sendan afv va ofiyat so‘raymiz.",note:null},
{num:244,time:"00:19:50,099 --> 00:19:53,599",arabic:"يَا مُغِيثُ، أَغِثْنَا يَا اللَّهُ.",segs:[{ar:"يَا مُغِيثُ",uz:"ey madad beruvchi"},{ar:"أَغِثْنَا",uz:"bizga madad ber"},{ar:"يَا اللَّهُ",uz:"ey Alloh"}],full_uz:"Ey madad beruvchi Alloh, bizga madad ber.",note:"أَغَاثَ — يُغِيثُ — «madad bermoq». Buyruq shakli أَغِثْ."},
{num:245,time:"00:20:29,980 --> 00:20:51,180",arabic:"هَذِهِ الشُّمُوعُ.",segs:null,full_uz:"Mana bu shamlar.",note:"شُمُوعٌ — شَمْعَةٌ («sham»)ning ko‘pligi."},
{num:246,time:"00:20:51,180 --> 00:20:53,960",arabic:"مَتَى احْتَجْتَ غَيْرَهَا سَتَجِدُ عِنْدِي طَلَبَكَ.",segs:[{ar:"مَتَى احْتَجْتَ غَيْرَهَا",uz:"yana boshqalari kerak bo‘lganda"},{ar:"سَتَجِدُ عِنْدِي طَلَبَكَ",uz:"istaganingizni mendan topasiz"}],full_uz:"Yana sham kerak bo‘lganda, istaganingizni mendan topasiz.",note:"طَلَبَكَ bu yerda «siz izlayotgan yoki so‘rayotgan narsa»."},
{num:247,time:"00:20:53,960 --> 00:20:57,039",arabic:"هَذَا يَعْتَمِدُ عَلَى جَوْدَةِ شُمُوعِكَ وَحُسْنِ سِعْرِكَ.",segs:[{ar:"هَذَا يَعْتَمِدُ عَلَى",uz:"bu ...ga bog‘liq"},{ar:"جَوْدَةِ شُمُوعِكَ",uz:"shamlaringizning sifatiga"},{ar:"وَحُسْنِ سِعْرِكَ",uz:"va narxingizning yaxshiligiga"}],full_uz:"Bu shamlaringizning sifati va narxingizning yaxshiligiga bog‘liq.",note:"اِعْتَمَدَ عَلَى — «...ga bog‘liq bo‘ldi, tayandi»."},
{num:248,time:"00:20:57,039 --> 00:20:59,400",arabic:"إِذَنْ أَنَا عَلَى يَقِينٍ مِنْ عَوْدَتِكَ.",segs:[{ar:"إِذَنْ أَنَا عَلَى يَقِينٍ",uz:"unda ishonchim komil"},{ar:"مِنْ عَوْدَتِكَ",uz:"qaytib kelishingizga"}],full_uz:"Unda qaytib kelishingizga ishonchim komil.",note:"عَلَى يَقِينٍ مِنْ — «...ga ishonchi komil»."},
{num:249,time:"00:21:00,740 --> 00:21:01,800",arabic:"وَعَلَيْكُمُ السَّلَامُ.",segs:null,full_uz:"Va alaykum assalom.",note:null},
{num:250,time:"00:21:01,800 --> 00:21:04,400",arabic:"لَا تَنْسَ الْجَوْدَةَ وَالسِّعْرَ.",segs:[{ar:"لَا تَنْسَ",uz:"unutmang"},{ar:"الْجَوْدَةَ وَالسِّعْرَ",uz:"sifat va narxni"}],full_uz:"Sifat va narxni unutmang.",note:null},
{num:251,time:"00:21:05,220 --> 00:21:13,400",arabic:"مَا هَذَا؟",segs:null,full_uz:"Bu nima?",note:null},
{num:252,time:"00:21:14,980 --> 00:21:16,400",arabic:"لَا بُدَّ أَنَّ الرَّجُلَ نَسِيَ صُنْدُوقَهُ.",segs:[{ar:"لَا بُدَّ أَنَّ الرَّجُلَ",uz:"shubhasiz, bu kishi"},{ar:"نَسِيَ صُنْدُوقَهُ",uz:"sandig‘ini unutib qoldirgan"}],full_uz:"Shubhasiz, bu kishi sandig‘ini unutib qoldirgan.",note:"لَا بُدَّ أَنَّ... kuchli taxminni bildiradi: «aniq, ...bo‘lsa kerak»."},
{num:253,time:"00:21:18,620 --> 00:21:20,420",arabic:"اِنْتَبِهْ لِلدُّكَّانِ.",segs:null,full_uz:"Do‘konga qarab turing.",note:"اِنْتَبَهَ لِـ — «e’tibor berdi, qarab turdi»."},
{num:254,time:"00:21:36,840 --> 00:21:41,780",arabic:"السَّلَامُ عَلَى مَوْلَايَ أَمِيرِ الْمُؤْمِنِينَ وَصَحْبِهِ.",segs:[{ar:"السَّلَامُ عَلَى مَوْلَايَ",uz:"hukmdorimga salom bo‘lsin"},{ar:"أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiriga"},{ar:"وَصَحْبِهِ",uz:"va uning hamrohlariga"}],full_uz:"Hukmdorim mo‘minlar amiriga va uning hamrohlariga salom bo‘lsin.",note:"صَحْبٌ — «hamrohlar, suhbatdoshlar»."},
{num:255,time:"00:21:41,780 --> 00:21:46,960",arabic:"وَعَلَيْكَ السَّلَامُ يَا أَبَا الْعَبَّاسِ، تَعَالَ، اِجْلِسْ مَعَنَا وَاسْتَمِعْ وَاضْحَكْ.",segs:[{ar:"وَعَلَيْكَ السَّلَامُ",uz:"sizga ham salom bo‘lsin"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"},{ar:"تَعَالَ",uz:"keling"},{ar:"اِجْلِسْ مَعَنَا",uz:"biz bilan o‘tiring"},{ar:"وَاسْتَمِعْ وَاضْحَكْ",uz:"tinglang va kuling"}],full_uz:"Sizga ham salom bo‘lsin, Abu Abbos. Keling, biz bilan o‘tiring, tinglang va kuling.",note:null},
{num:256,time:"00:21:46,960 --> 00:21:51,080",arabic:"أَخْشَى يَا مَوْلَايَ أَنَّنِي سَأَقْطَعُ أُنْسَ حُضُورِكَ بِكَ.",segs:[{ar:"أَخْشَى يَا مَوْلَايَ",uz:"xavotirdaman, hukmdorim"},{ar:"أَنَّنِي سَأَقْطَعُ",uz:"men buzib qo‘yishimdan"},{ar:"أُنْسَ حُضُورِكَ بِكَ",uz:"huzuringizdagilarning siz bilan xush suhbatini"}],full_uz:"Hukmdorim, huzuringizdagilarning siz bilan xush suhbatini buzib qo‘yishdan xavotirdaman.",note:"أُنْسٌ — «dilkashlik, suhbatdan huzur». حُضُورٌ bu yerda hozir bo‘lgan kishilarni bildiradi."},
{num:257,time:"00:21:51,080 --> 00:21:54,080",arabic:"وَلَكِنَّ الْأَمْرَ أَوْلَى وَأَدْهَى.",segs:[{ar:"وَلَكِنَّ الْأَمْرَ",uz:"lekin bu ish"},{ar:"أَوْلَى وَأَدْهَى",uz:"muhimroq va jiddiyroq"}],full_uz:"Lekin bu ish muhimroq va jiddiyroq.",note:"أَوْلَى — «ustunroq, muhimroq»; أَدْهَى — «og‘irroq, dahshatliroq»."},
{num:258,time:"00:21:54,080 --> 00:21:57,800",arabic:"مَا وَرَاءَكَ يَا ابْنَ الرَّبِيعِ؟",segs:[{ar:"مَا وَرَاءَكَ",uz:"qanday xabar olib keldingiz"},{ar:"يَا ابْنَ الرَّبِيعِ؟",uz:"ey Ibn Rabi’?"}],full_uz:"Qanday xabar olib keldingiz, Ibn Rabi’?",note:"مَا وَرَاءَكَ؟ so‘zma-so‘z «ortingizda nima bor?»; suhbatda «qanday xabaringiz bor?»."},
{num:259,time:"00:21:57,799 --> 00:22:01,659",arabic:"رِسَالَةٌ مِنْ مَلِكِ بَنِي الْأَصْفَرِ نِقْفُورَ يَا مَوْلَايَ.",segs:[{ar:"رِسَالَةٌ",uz:"bir maktub"},{ar:"مِنْ مَلِكِ بَنِي الْأَصْفَرِ نِقْفُورَ",uz:"Banu Asfar podshohi Niqfurdan"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Banu Asfar podshohi Niqfurdan maktub, hukmdorim.",note:"بَنُو الْأَصْفَرِ — rumliklarga nisbatan qo‘llangan tarixiy nom."},
{num:260,time:"00:22:01,659 --> 00:22:05,319",arabic:"أَرِنِيهَا.",segs:null,full_uz:"Uni menga ko‘rsating.",note:"أَرِنِيهَا = أَرِ («ko‘rsating») + نِي («menga») + هَا («uni»)."},
{num:261,time:"00:22:13,960 --> 00:22:19,119",arabic:"مِنْ نِقْفُورَ مَلِكِ الرُّومِ إِلَى هَارُونَ مَلِكِ الْعَرَبِ.",segs:[{ar:"مِنْ نِقْفُورَ مَلِكِ الرُّومِ",uz:"Rum podshohi Niqfurdan"},{ar:"إِلَى هَارُونَ مَلِكِ الْعَرَبِ",uz:"arablar podshohi Horunga"}],full_uz:"Rum podshohi Niqfurdan arablar podshohi Horunga.",note:null},
{num:262,time:"00:22:19,119 --> 00:22:27,119",arabic:"أَمَّا بَعْدُ، فَإِنَّ الْمَلِكَةَ الَّتِي كَانَتْ قَبْلِي أَقَامَتْكَ مَقَامَ الرُّخِّ.",segs:[{ar:"أَمَّا بَعْدُ",uz:"so‘ngra"},{ar:"فَإِنَّ الْمَلِكَةَ الَّتِي كَانَتْ قَبْلِي",uz:"mendan oldingi malika"},{ar:"أَقَامَتْكَ مَقَامَ الرُّخِّ",uz:"sizni rux o‘rniga qo‘ydi"}],full_uz:"So‘ngra, mendan oldingi malika sizni shaxmatdagi rux o‘rniga qo‘ydi.",note:"الرُّخُّ — shaxmatdagi rux. أَقَامَهُ مَقَامَ... — «uni ... o‘rniga qo‘ydi»."},
{num:263,time:"00:22:27,119 --> 00:22:30,419",arabic:"وَأَقَامَتْ نَفْسَهَا مَقَامَ الْبَيْدَقِ.",segs:[{ar:"وَأَقَامَتْ نَفْسَهَا",uz:"o‘zini esa qo‘ydi"},{ar:"مَقَامَ الْبَيْدَقِ",uz:"piyoda o‘rniga"}],full_uz:"O‘zini esa piyoda o‘rniga qo‘ydi.",note:"الْبَيْدَقُ — shaxmatdagi piyoda."},
{num:264,time:"00:22:30,419 --> 00:22:36,739",arabic:"فَحَمَلَتْ إِلَيْكَ مِنْ أَمْوَالِهَا مَا كُنْتَ حَقِيقًا بِحَمْلِ أَضْعَافِهَا إِلَيْهَا.",segs:[{ar:"فَحَمَلَتْ إِلَيْكَ مِنْ أَمْوَالِهَا",uz:"sizga o‘z molidan yubordi"},{ar:"مَا كُنْتَ حَقِيقًا",uz:"aslida siz lozim bo‘lgan narsani"},{ar:"بِحَمْلِ أَضْعَافِهَا إِلَيْهَا",uz:"unga bir necha barobar qilib yuborishga"}],full_uz:"Sizga o‘z molidan yubordi, aslida esa siz unga buning bir necha barobarini yuborishingiz lozim edi.",note:"حَقِيقٌ بِـ — «...ga loyiq, ...qilishi lozim». أَضْعَافٌ — «bir necha barobar»."},
{num:265,time:"00:22:36,739 --> 00:22:42,000",arabic:"لَكِنَّ ذَلِكَ ضَعْفُ النِّسَاءِ وَحُمْقُهُنَّ.",segs:[{ar:"لَكِنَّ ذَلِكَ",uz:"lekin bu"},{ar:"ضَعْفُ النِّسَاءِ وَحُمْقُهُنَّ",uz:"ayollarning zaifligi va ahmoqligidir"}],full_uz:"Lekin bu ayollarning zaifligi va ahmoqligidir.",note:"ـهُنَّ — ayollar ko‘pligiga tegishli olmosh."},
{num:266,time:"00:22:42,000 --> 00:22:46,099",arabic:"فَإِذَا قَرَأْتَ كِتَابِي هَذَا...",segs:[{ar:"فَإِذَا قَرَأْتَ",uz:"o‘qiganingizda"},{ar:"كِتَابِي هَذَا",uz:"mana bu maktubimni"}],full_uz:"Mana bu maktubimni o‘qiganingizda...",note:"كِتَابٌ bu yerda «kitob» emas, «maktub»."},
{num:267,time:"00:22:46,099 --> 00:22:51,599",arabic:"فَارْدُدْ مَا حَصَلَ لَكَ مِنْ أَمْوَالِهَا.",segs:[{ar:"فَارْدُدْ",uz:"qaytaring"},{ar:"مَا حَصَلَ لَكَ",uz:"qo‘lingizga tushgan narsani"},{ar:"مِنْ أَمْوَالِهَا",uz:"uning mollaridan"}],full_uz:"Uning mollaridan qo‘lingizga tushganini qaytaring.",note:"اُرْدُدْ — رَدَّ fe’lining buyruq shakllaridan biri; shadda ochilgan."},
{num:268,time:"00:22:51,599 --> 00:22:53,179",arabic:"وَافْتَدِ نَفْسَكَ بِهِ.",segs:[{ar:"وَافْتَدِ نَفْسَكَ",uz:"va o‘zingizni qutqarib qoling"},{ar:"بِهِ",uz:"shu bilan"}],full_uz:"Va shu bilan o‘zingizni qutqarib qoling.",note:"اِفْتَدَى نَفْسَهُ بِـ — «bir narsa evaziga o‘zini qutqardi». Buyruqda oxirgi illat harfi tushadi: اِفْتَدِ."},
{num:269,time:"00:22:53,180 --> 00:22:57,500",arabic:"وَإِلَّا فَالسَّيْفُ بَيْنَنَا وَبَيْنَكَ.",segs:[{ar:"وَإِلَّا",uz:"aks holda"},{ar:"فَالسَّيْفُ بَيْنَنَا وَبَيْنَكَ",uz:"biz bilan sizning oramizda qilich bo‘ladi"}],full_uz:"Aks holda, oramizdagi ishni qilich hal qiladi.",note:"السَّيْفُ بَيْنَنَا وَبَيْنَكَ — urush bilan hal qilish tahdidi."},
{num:270,time:"00:22:57,500 --> 00:23:18,180",arabic:"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ.",segs:[{ar:"بِسْمِ اللَّهِ",uz:"Allohning nomi bilan"},{ar:"الرَّحْمَنِ الرَّحِيمِ",uz:"mehribon va rahmli"}],full_uz:"Mehribon va rahmli Allohning nomi bilan.",note:null},
{num:271,time:"00:23:18,180 --> 00:23:35,220",arabic:"مِنْ هَارُونَ أَمِيرِ الْمُؤْمِنِينَ إِلَى نِقْفُورَ كَلْبِ الرُّومِ.",segs:[{ar:"مِنْ هَارُونَ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri Horundan"},{ar:"إِلَى نِقْفُورَ كَلْبِ الرُّومِ",uz:"Rumning iti Niqfurga"}],full_uz:"Mo‘minlar amiri Horundan Rumning iti Niqfurga.",note:null},
{num:272,time:"00:23:35,220 --> 00:23:48,220",arabic:"أَمَّا بَعْدُ، فَقَدْ وَصَلَنِي كِتَابُكَ.",segs:[{ar:"أَمَّا بَعْدُ",uz:"so‘ngra"},{ar:"فَقَدْ وَصَلَنِي كِتَابُكَ",uz:"menga maktubingiz yetib keldi"}],full_uz:"So‘ngra, menga maktubingiz yetib keldi.",note:null},
{num:273,time:"00:23:48,819 --> 00:24:01,220",arabic:"وَالْجَوَابُ مَا تَرَاهُ دُونَ مَا تَسْمَعُهُ.",segs:[{ar:"وَالْجَوَابُ مَا تَرَاهُ",uz:"javob — ko‘radigan narsangiz"},{ar:"دُونَ مَا تَسْمَعُهُ",uz:"eshitadigan narsangiz emas"}],full_uz:"Javobni eshitmaysiz, ko‘rasiz.",note:"دُونَ bu yerda qarama-qarshi qo‘yishni bildiradi: «...emas». Gap amaliy javob berilishini anglatadi."},
{num:274,time:"00:24:01,220 --> 00:24:04,559",arabic:"وَالسَّلَامُ.",segs:null,full_uz:"Salom bilan.",note:"Maktubni yakunlashda ishlatiladigan qisqa ibora."},
{num:275,time:"00:24:04,559 --> 00:24:26,860",arabic:"مَا بِكَ يَا حَنْظَلَةُ؟",segs:[{ar:"مَا بِكَ",uz:"sizga nima bo‘ldi"},{ar:"يَا حَنْظَلَةُ؟",uz:"ey Hanzala?"}],full_uz:"Sizga nima bo‘ldi, Hanzala?",note:null},
{num:276,time:"00:24:26,860 --> 00:24:28,759",arabic:"مُنْذُ غَادَرَتْنَا الْجَارِيَةُ فَوْزٌ...",segs:[{ar:"مُنْذُ غَادَرَتْنَا",uz:"bizdan ketganidan beri"},{ar:"الْجَارِيَةُ فَوْزٌ",uz:"joriya Favz"}],full_uz:"Joriya Favz bizdan ketganidan beri...",note:null},
{num:277,time:"00:24:28,759 --> 00:24:31,200",arabic:"وَأَنْتَ عَلَى هَذِهِ الْحَالَةِ مِنْ نِسْيَانٍ وَشُرُودٍ.",segs:[{ar:"وَأَنْتَ عَلَى هَذِهِ الْحَالَةِ",uz:"siz shu ahvoldasiz"},{ar:"مِنْ نِسْيَانٍ وَشُرُودٍ",uz:"unutuvchanlik va xayolga cho‘mishdan iborat"}],full_uz:"Siz shu unutuvchan va xayolga cho‘mgan ahvoldasiz.",note:"شُرُودٌ — fikrning boshqa joyda bo‘lishi, xayolga cho‘mish."},
{num:278,time:"00:24:31,200 --> 00:24:34,500",arabic:"مَاذَا أَمْلِكُ لَكَ وَقَدْ ذَهَبَ عَقْلُكَ يَا رَجُلُ؟",segs:[{ar:"مَاذَا أَمْلِكُ لَكَ",uz:"siz uchun nima qila olaman"},{ar:"وَقَدْ ذَهَبَ عَقْلُكَ",uz:"axir aqlingizni yo‘qotibsiz"},{ar:"يَا رَجُلُ؟",uz:"ey odam?"}],full_uz:"Siz uchun nima qila olaman, axir aqlingizni yo‘qotibsiz, ey odam?",note:"مَاذَا أَمْلِكُ لَكَ؟ — «siz uchun qo‘limdan nima keladi?»."},
{num:279,time:"00:24:34,500 --> 00:24:37,000",arabic:"فَوْزٌ وَجَدْنَاهَا فَتَاةً حُرَّةً.",segs:[{ar:"فَوْزٌ وَجَدْنَاهَا",uz:"Favzni topganimizda"},{ar:"فَتَاةً حُرَّةً",uz:"ozod qiz edi"}],full_uz:"Favzni topganimizda, u ozod qiz edi.",note:null},
{num:280,time:"00:24:37,000 --> 00:24:40,059",arabic:"فَأَصْبَحَتْ بِأَيْدِينَا جَارِيَةً تُبَاعُ وَتُشْتَرَى.",segs:[{ar:"فَأَصْبَحَتْ بِأَيْدِينَا",uz:"bizning qo‘limizda aylanib qoldi"},{ar:"جَارِيَةً",uz:"joriyaga"},{ar:"تُبَاعُ وَتُشْتَرَى",uz:"sotiladigan va sotib olinadigan"}],full_uz:"Bizning qo‘limizda sotiladigan va sotib olinadigan joriyaga aylandi.",note:"تُبَاعُ va تُشْتَرَى — majhul nisbat: «sotiladi» va «sotib olinadi»."},
{num:281,time:"00:24:40,059 --> 00:24:41,480",arabic:"أَنَسِيتِ مَا فَعَلْنَاهُ بِهَا؟",segs:[{ar:"أَنَسِيتِ",uz:"unutdingizmi"},{ar:"مَا فَعَلْنَاهُ بِهَا؟",uz:"unga qilgan ishimizni?"}],full_uz:"Unga qilgan ishimizni unutdingizmi?",note:"نَسِيتِ — ayol kishiga murojaat shakli."},
{num:282,time:"00:24:41,480 --> 00:24:42,900",arabic:"إِذَنْ نَحْنُ ظَالِمُونَ.",segs:null,full_uz:"Demak, biz zolimmiz.",note:null},
{num:283,time:"00:24:42,900 --> 00:24:44,019",arabic:"مَا بِكَ يَا رَجُلُ؟",segs:[{ar:"مَا بِكَ",uz:"sizga nima bo‘ldi"},{ar:"يَا رَجُلُ؟",uz:"ey odam?"}],full_uz:"Sizga nima bo‘ldi, ey odam?",note:null},
{num:284,time:"00:24:44,019 --> 00:24:46,299",arabic:"مَا الَّذِي بَدَّلَ حَالَكَ هَكَذَا؟",segs:[{ar:"مَا الَّذِي بَدَّلَ حَالَكَ",uz:"holingizni nima o‘zgartirdi"},{ar:"هَكَذَا؟",uz:"bunday?"}],full_uz:"Holingizni nima bunday o‘zgartirdi?",note:null},
{num:285,time:"00:24:46,299 --> 00:24:48,319",arabic:"لَوْ لَمْ نَأْخُذْهَا جَارِيَةً...",segs:[{ar:"لَوْ لَمْ نَأْخُذْهَا",uz:"agar uni olmaganimizda"},{ar:"جَارِيَةً",uz:"joriya qilib"}],full_uz:"Agar uni joriya qilib olmaganimizda...",note:null},
{num:286,time:"00:24:48,319 --> 00:24:50,500",arabic:"لَمَا وَجَدْنَا مَا نَحْنُ فِيهِ مِنْ نَعِيمٍ.",segs:[{ar:"لَمَا وَجَدْنَا",uz:"erishmagan bo‘lardik"},{ar:"مَا نَحْنُ فِيهِ مِنْ نَعِيمٍ",uz:"hozirgi farovonligimizga"}],full_uz:"Hozirgi farovonligimizga erishmagan bo‘lardik.",note:"لَمَا bu yerda لَـ + inkor مَا; oldingi لَوْ shartining javobi."},
{num:287,time:"00:24:50,500 --> 00:24:51,840",arabic:"قُضِيَ الْأَمْرُ.",segs:null,full_uz:"Ish bitgan.",note:"قُضِيَ — majhul nisbat: «hal qilindi, tugatildi»."},
{num:288,time:"00:24:51,840 --> 00:24:53,819",arabic:"فَلَا تَعُدْ إِلَى ذِكْرِهَا ثَانِيَةً.",segs:[{ar:"فَلَا تَعُدْ إِلَى ذِكْرِهَا",uz:"uni tilga olishga qaytmang"},{ar:"ثَانِيَةً",uz:"yana"}],full_uz:"Endi uni yana tilga olmang.",note:"لَا تَعُدْ — «qaytmang». تَعُودُ jazmda o‘rta illat harfini yo‘qotadi."},
{num:289,time:"00:24:53,819 --> 00:24:56,759",arabic:"لَسْتُ أَنَا مَنْ أَتَى عَلَى ذِكْرِهَا.",segs:[{ar:"لَسْتُ أَنَا",uz:"men emasman"},{ar:"مَنْ أَتَى عَلَى ذِكْرِهَا",uz:"uni tilga olgan"}],full_uz:"Uni tilga olgan men emasman.",note:"أَتَى عَلَى ذِكْرِ شَخْصٍ — «bir kishini tilga oldi»."},
{num:290,time:"00:24:56,759 --> 00:24:57,880",arabic:"أَنْتِ مَنْ فَعَلْتِ ذَلِكَ.",segs:null,full_uz:"Buni siz qildingiz.",note:null},
{num:291,time:"00:25:05,340 --> 00:25:07,180",arabic:"لَقَدْ نَسِيتَ هَذَا الصُّنْدُوقَ فِي دُكَّانِي.",segs:[{ar:"لَقَدْ نَسِيتَ هَذَا الصُّنْدُوقَ",uz:"bu sandiqni unutib qoldirdingiz"},{ar:"فِي دُكَّانِي",uz:"do‘konimda"}],full_uz:"Bu sandiqni do‘konimda unutib qoldirdingiz.",note:null},
{num:292,time:"00:25:07,180 --> 00:25:08,700",arabic:"وَقَدْ أَتَيْتُكَ لِأُعِيدَهُ إِلَيْكَ.",segs:[{ar:"وَقَدْ أَتَيْتُكَ",uz:"oldingizga keldim"},{ar:"لِأُعِيدَهُ إِلَيْكَ",uz:"uni sizga qaytarish uchun"}],full_uz:"Uni sizga qaytarish uchun oldingizga keldim.",note:"أَعَادَ — يُعِيدُ — «qaytarmoq». لِأُعِيدَهُ — «uni qaytarishim uchun»."},
{num:293,time:"00:25:08,700 --> 00:25:10,180",arabic:"صُنْدُوقِي؟",segs:null,full_uz:"Sandig‘immi?",note:null},
{num:294,time:"00:25:10,180 --> 00:25:11,240",arabic:"بَارَكَ اللَّهُ فِيكَ.",segs:null,full_uz:"Alloh sizga baraka bersin.",note:null},
{num:295,time:"00:25:11,240 --> 00:25:13,340",arabic:"لَمْ أَعْرِفْ رَجُلًا بِمِثْلِ أَمَانَتِكَ.",segs:[{ar:"لَمْ أَعْرِفْ رَجُلًا",uz:"biror kishini bilmaganman"},{ar:"بِمِثْلِ أَمَانَتِكَ",uz:"sizdek omonatdor"}],full_uz:"Sizdek omonatdor kishini ko‘rmaganman.",note:"أَمَانَةٌ bu yerda «halollik, ishonchni oqlash, omonatdorlik»."},
{num:296,time:"00:25:13,340 --> 00:25:14,920",arabic:"تَفَضَّلْ إِلَى الدَّارِ نُكْرِمْكَ.",segs:[{ar:"تَفَضَّلْ إِلَى الدَّارِ",uz:"uyga marhamat qiling"},{ar:"نُكْرِمْكَ",uz:"sizni mehmon qilaylik"}],full_uz:"Uyga marhamat qiling, sizni mehmon qilaylik.",note:"نُكْرِمْكَ buyruqning natijasi sifatida majzum: «kiring — sizni mehmon qilamiz»."},
{num:297,time:"00:25:14,920 --> 00:25:15,480",arabic:"تَفَضَّلْ.",segs:null,full_uz:"Marhamat.",note:null},
{num:298,time:"00:25:16,580 --> 00:25:18,259",arabic:"لَقَدْ تَرَكْتُ الدُّكَّانَ مَفْتُوحًا.",segs:[{ar:"لَقَدْ تَرَكْتُ الدُّكَّانَ",uz:"do‘konni qoldirdim"},{ar:"مَفْتُوحًا",uz:"ochiq holda"}],full_uz:"Do‘konni ochiq qoldirdim.",note:"مَفْتُوحًا do‘kon qanday holatda qoldirilganini bildiradi."},
{num:299,time:"00:25:18,259 --> 00:25:20,740",arabic:"وَيَجِبُ أَنْ أَعُودَ، فَقَدْ قَرُبَتِ الشَّمْسُ مِنَ الْمَغِيبِ.",segs:[{ar:"وَيَجِبُ أَنْ أَعُودَ",uz:"qaytishim kerak"},{ar:"فَقَدْ قَرُبَتِ الشَّمْسُ",uz:"chunki quyosh yaqinlashdi"},{ar:"مِنَ الْمَغِيبِ",uz:"botishga"}],full_uz:"Qaytishim kerak, chunki quyosh botishga yaqinlashdi.",note:"مَغِيبٌ — «botish, ko‘zdan g‘oyib bo‘lish»."},
{num:300,time:"00:25:20,740 --> 00:25:23,660",arabic:"بَعْدَ الْآنِ لَنْ أَشْتَرِيَ الشَّمْعَ إِلَّا مِنْ عِنْدِكَ.",segs:[{ar:"بَعْدَ الْآنِ",uz:"bundan buyon"},{ar:"لَنْ أَشْتَرِيَ الشَّمْعَ",uz:"sham sotib olmayman"},{ar:"إِلَّا مِنْ عِنْدِكَ",uz:"faqat sizdan boshqa joydan"}],full_uz:"Bundan buyon shamni faqat sizdan sotib olaman.",note:"لَنْ ... إِلَّا ... inkor va istisno orqali «faqat» ma’nosini beradi."},
{num:301,time:"00:25:23,660 --> 00:25:25,000",arabic:"عَلَى الرَّحْبِ وَالسَّعَةِ.",segs:null,full_uz:"Jon deb, marhamat.",note:"عَلَى الرَّحْبِ وَالسَّعَةِ — mamnuniyat bilan qabul qilishni bildiruvchi turg‘un ibora."},
{num:302,time:"00:25:53,180 --> 00:25:56,860",arabic:"أَيُعْقَلُ أَنَّهُ كَانَ يَتَحَدَّثُ عَنْ فَوْزٍ أُخْتِ شَهْنَازَ؟",segs:[{ar:"أَيُعْقَلُ",uz:"nahotki"},{ar:"أَنَّهُ كَانَ يَتَحَدَّثُ عَنْ فَوْزٍ",uz:"u Favz haqida gapirgan bo‘lsa"},{ar:"أُخْتِ شَهْنَازَ؟",uz:"Shahnozning opasi?"}],full_uz:"Nahotki u Shahnozning opasi Favz haqida gapirgan bo‘lsa?",note:"أُخْتِ شَهْنَازَ oldingi فَوْزٍ kimligini izohlab kelgan."},
{num:303,time:"00:25:56,860 --> 00:26:00,019",arabic:"هَذَا الِاسْمُ لَا يَتَدَاوَلُهُ أَهْلُ بَغْدَادَ كَثِيرًا.",segs:[{ar:"هَذَا الِاسْمُ",uz:"bu ismni"},{ar:"لَا يَتَدَاوَلُهُ أَهْلُ بَغْدَادَ كَثِيرًا",uz:"Bag‘dod ahli ko‘p ishlatmaydi"}],full_uz:"Bu ismni Bag‘dod ahli ko‘p ishlatmaydi.",note:"تَدَاوَلَ — «o‘zaro ishlatdi, muomalada qo‘lladi»."},
{num:304,time:"00:26:01,200 --> 00:26:05,340",arabic:"كَيْفَ أَسْتَطِيعُ مَعْرِفَةَ إِنْ كَانَتْ هِيَ أَمْ لَا؟",segs:[{ar:"كَيْفَ أَسْتَطِيعُ مَعْرِفَةَ",uz:"qanday bila olaman"},{ar:"إِنْ كَانَتْ هِيَ أَمْ لَا؟",uz:"o‘sha qizmi yoki yo‘qmi?"}],full_uz:"O‘sha qiz ekanini yoki yo‘qligini qanday bila olaman?",note:null},
{num:305,time:"00:26:05,340 --> 00:26:06,779",arabic:"لَيْسَ لِي إِلَّا أَنْ أَسْأَلَ الرَّجُلَ.",segs:[{ar:"لَيْسَ لِي إِلَّا",uz:"menda boshqa yo‘l yo‘q"},{ar:"أَنْ أَسْأَلَ الرَّجُلَ",uz:"o‘sha kishidan so‘rashdan"}],full_uz:"O‘sha kishidan so‘rashdan boshqa yo‘lim yo‘q.",note:"لَيْسَ لِي إِلَّا أَنْ... — «...ishdan boshqa ilojim yo‘q»."},
{num:306,time:"00:26:06,779 --> 00:26:11,299",arabic:"وَلَكِنْ مَاذَا سَأَقُولُ لَهُ؟",segs:null,full_uz:"Lekin unga nima deyman?",note:null},
{num:307,time:"00:26:11,299 --> 00:26:13,340",arabic:"وَهَلْ سَيَقُولُ لِي الْحَقِيقَةَ؟",segs:[{ar:"وَهَلْ سَيَقُولُ لِي",uz:"menga aytarmikan"},{ar:"الْحَقِيقَةَ؟",uz:"haqiqatni?"}],full_uz:"U menga haqiqatni aytarmikan?",note:null},
{num:308,time:"00:27:01,200 --> 00:27:21,980",arabic:"سَتَسْمَعُ مَا يَسُرُّكَ وَلَنْ تَنْدَمَ عَلَى قُدُومِكَ إِلَى دَارِ شَيْخِنَا الشَّافِعِيِّ.",segs:[{ar:"سَتَسْمَعُ مَا يَسُرُّكَ",uz:"sizni quvontiradigan narsalarni eshitasiz"},{ar:"وَلَنْ تَنْدَمَ عَلَى قُدُومِكَ",uz:"va kelganingizga afsuslanmaysiz"},{ar:"إِلَى دَارِ شَيْخِنَا الشَّافِعِيِّ",uz:"shayximiz Shofi’iyning uyiga"}],full_uz:"Sizni quvontiradigan narsalarni eshitasiz va shayximiz Shofi’iyning uyiga kelganingizga afsuslanmaysiz.",note:"سَرَّ — يَسُرُّ — «quvontirmoq». نَدِمَ عَلَى — «...dan afsuslandi»."},
{num:309,time:"00:27:21,980 --> 00:27:22,680",arabic:"إِنْ شَاءَ اللَّهُ.",segs:null,full_uz:"Alloh xohlasa.",note:null},
{num:310,time:"00:27:41,660 --> 00:27:44,559",arabic:"أَهْلًا بِطُلَّابِ الْعِلْمِ، تَفَضَّلُوا.",segs:[{ar:"أَهْلًا بِطُلَّابِ الْعِلْمِ",uz:"xush kelibsizlar, ilm talabalari"},{ar:"تَفَضَّلُوا",uz:"marhamat qilinglar"}],full_uz:"Xush kelibsizlar, ilm talabalari, marhamat qilinglar.",note:null},
{num:311,time:"00:27:47,840 --> 00:27:53,960",arabic:"أَهْلًا وَسَهْلًا، تَفَضَّلْ بِالْجُلُوسِ.",segs:[{ar:"أَهْلًا وَسَهْلًا",uz:"xush kelibsiz"},{ar:"تَفَضَّلْ بِالْجُلُوسِ",uz:"marhamat, o‘tiring"}],full_uz:"Xush kelibsiz, marhamat, o‘tiring.",note:"تَفَضَّلْ بِالْجُلُوسِ — o‘tirishga muloyim taklif."},
{num:312,time:"00:28:01,200 --> 00:28:08,299",arabic:"اِعْلَمُوا أَنَّهُ مِمَّا يَشِيعُ مِنَ الْخَطَإِ لَدَى طُلَّابِ الْعِلْمِ فِي زَمَانِنَا...",segs:[{ar:"اِعْلَمُوا",uz:"bilib qo‘yinglar"},{ar:"أَنَّهُ مِمَّا يَشِيعُ مِنَ الْخَطَإِ",uz:"keng tarqalgan xatolardan biri ekanini"},{ar:"لَدَى طُلَّابِ الْعِلْمِ",uz:"ilm talabalari orasida"},{ar:"فِي زَمَانِنَا",uz:"zamonamizda"}],full_uz:"Bilib qo‘yinglar, zamonamizda ilm talabalari orasida keng tarqalgan xatolardan biri...",note:"شَاعَ — يَشِيعُ — «tarqalmoq, keng yoyilmoq». لَدَى bu yerda «orasida» ma’nosida."},
{num:313,time:"00:28:08,299 --> 00:28:12,100",arabic:"الْخَلْطُ بَيْنَ الْفَهْمِ وَالْفِقْهِ.",segs:[{ar:"الْخَلْطُ",uz:"aralashtirib yuborish"},{ar:"بَيْنَ الْفَهْمِ وَالْفِقْهِ",uz:"tushunish bilan chuqur anglashni"}],full_uz:"Tushunish bilan chuqur anglashni aralashtirib yuborishdir.",note:"Bu suhbatda الْفَهْمُ oddiy tushunish, الْفِقْهُ esa gapning maqsadini chuqur anglash ma’nosida qo‘llanmoqda."},
{num:314,time:"00:28:12,100 --> 00:28:15,900",arabic:"فَالْفَهْمُ هُوَ مَعْرِفَةُ مَعْنَى اللَّفْظِ.",segs:[{ar:"فَالْفَهْمُ هُوَ",uz:"tushunish bu"},{ar:"مَعْرِفَةُ مَعْنَى اللَّفْظِ",uz:"so‘zning ma’nosini bilish"}],full_uz:"Tushunish — so‘zning ma’nosini bilishdir.",note:"لَفْظٌ — «talaffuz qilingan so‘z yoki ibora»."},
{num:315,time:"00:28:15,900 --> 00:28:21,180",arabic:"أَمَّا الْفِقْهُ فَهُوَ مَرْتَبَةٌ أَخَصُّ مِنَ الْفَهْمِ.",segs:[{ar:"أَمَّا الْفِقْهُ",uz:"chuqur anglashga kelsak"},{ar:"فَهُوَ مَرْتَبَةٌ أَخَصُّ",uz:"u xosroq darajadir"},{ar:"مِنَ الْفَهْمِ",uz:"oddiy tushunishdan"}],full_uz:"Chuqur anglash esa oddiy tushunishdan xosroq darajadir.",note:"أَخَصُّ — «xosroq, doirasi aniqroq». أَمَّا ... فَـ ... bir mavzuni alohida izohlash uchun ishlatiladi."},
{num:316,time:"00:28:21,180 --> 00:28:25,799",arabic:"فَهُوَ مَعْرِفَةُ مُرَادِ الْمُتَكَلِّمِ مِنْ كَلَامِهِ.",segs:[{ar:"فَهُوَ مَعْرِفَةُ",uz:"u bilishdir"},{ar:"مُرَادِ الْمُتَكَلِّمِ",uz:"so‘zlovchining maqsadini"},{ar:"مِنْ كَلَامِهِ",uz:"o‘z gapidan"}],full_uz:"U so‘zlovchi o‘z gapi bilan nimani nazarda tutganini bilishdir.",note:"مُرَادٌ — «ko‘zlangan narsa, maqsad». الْمُتَكَلِّمُ — «so‘zlovchi»."},
{num:317,time:"00:28:25,799 --> 00:28:28,879",arabic:"قَالَ اللَّهُ تَعَالَى...",segs:null,full_uz:"Alloh taolo aytdi...",note:null},
{num:318,time:"00:28:28,879 --> 00:28:34,720",arabic:"فَمَالِ هَؤُلَاءِ الْقَوْمِ لَا يَكَادُونَ يَفْقَهُونَ حَدِيثًا.",segs:[{ar:"فَمَالِ هَؤُلَاءِ الْقَوْمِ",uz:"bu qavmga nima bo‘ldiki"},{ar:"لَا يَكَادُونَ يَفْقَهُونَ",uz:"deyarli anglamaydilar"},{ar:"حَدِيثًا",uz:"biror gapni"}],full_uz:"Bu qavmga nima bo‘ldiki, deyarli biror gapni anglamaydilar?",note:"لَا يَكَادُونَ — «deyarli ...maydilar». حَدِيثٌ bu yerda umumiy «gap, so‘z» ma’nosida."},
{num:319,time:"00:28:34,720 --> 00:28:39,279",arabic:"فَمَنْ ذَمَّهُمُ اللَّهُ كَانُوا عَرَبًا أَقْحَاحًا.",segs:[{ar:"فَمَنْ ذَمَّهُمُ اللَّهُ",uz:"Alloh qoralagan kishilar"},{ar:"كَانُوا عَرَبًا أَقْحَاحًا",uz:"asl arablar edilar"}],full_uz:"Alloh qoralagan kishilar asl arablar edilar.",note:"أَقْحَاحٌ — قُحٌّ ning ko‘pligi: «asl, sof». ذَمَّ — «qoraladi»."},
{num:320,time:"00:28:39,279 --> 00:28:45,559",arabic:"يَعْرِفُونَ مَعَانِيَ الْأَلْفَاظِ، فَهُمْ فَهِمُوهَا وَلَكِنْ لَمْ يَفْقَهُوهَا.",segs:[{ar:"يَعْرِفُونَ مَعَانِيَ الْأَلْفَاظِ",uz:"so‘zlarning ma’nolarini bilardilar"},{ar:"فَهُمْ فَهِمُوهَا",uz:"ular bu so‘zlarni tushundilar"},{ar:"وَلَكِنْ لَمْ يَفْقَهُوهَا",uz:"lekin chuqur anglamadilar"}],full_uz:"Ular so‘zlarning ma’nolarini bilardilar. So‘zlarni tushundilar, lekin chuqur anglamadilar.",note:"فَهِمُوا va فَقِهُوا bu izohda lug‘aviy ma’noni tushunish hamda ko‘zlangan maqsadni anglash sifatida farqlanmoqda."},
{num:321,time:"00:28:45,559 --> 00:28:51,180",arabic:"فَإِذَا عُلِمَ هَذَا صَارَ لِزَامًا عَلَى طَالِبِ الْعِلْمِ...",segs:[{ar:"فَإِذَا عُلِمَ هَذَا",uz:"bu anglab yetilgach"},{ar:"صَارَ لِزَامًا",uz:"zarur bo‘lib qoladi"},{ar:"عَلَى طَالِبِ الْعِلْمِ",uz:"ilm talabasi uchun"}],full_uz:"Bu anglab yetilgach, ilm talabasi uchun zarur bo‘lib qoladi...",note:"عُلِمَ — majhul nisbat: «bilindi». لِزَامًا — «zarur, lozim bo‘lgan narsa»."},
{num:322,time:"00:28:51,180 --> 00:28:54,680",arabic:"أَنْ يَجْتَهِدَ فِي مَعْرِفَةِ مُرَادِ اللَّهِ.",segs:[{ar:"أَنْ يَجْتَهِدَ",uz:"astoydil harakat qilishi"},{ar:"فِي مَعْرِفَةِ مُرَادِ اللَّهِ",uz:"Allohning murodini bilishga"}],full_uz:"Allohning murodini bilishga astoydil harakat qilishi.",note:"اِجْتَهَدَ فِي — «bir ishda bor kuchi bilan harakat qildi»."},
{num:323,time:"00:28:54,680 --> 00:28:57,840",arabic:"وَمَعْرِفَةِ مُرَادِ رَسُولِ اللَّهِ.",segs:null,full_uz:"Va Alloh Rasulining murodini bilishga.",note:null},
{num:324,time:"00:28:57,840 --> 00:29:00,680",arabic:"فَإِذَا فَعَلْنَا ذَلِكَ...",segs:null,full_uz:"Agar shunday qilsak...",note:null},
{num:325,time:"00:29:00,680 --> 00:29:05,120",arabic:"زَالَ بِعَوْنِ اللَّهِ كَثِيرٌ مِنْ لَبْسِ الْفُهُومِ.",segs:[{ar:"زَالَ بِعَوْنِ اللَّهِ",uz:"Allohning yordami bilan yo‘qoladi"},{ar:"كَثِيرٌ مِنْ لَبْسِ الْفُهُومِ",uz:"tushunishdagi ko‘plab chalkashliklar"}],full_uz:"Allohning yordami bilan tushunishdagi ko‘plab chalkashliklar yo‘qoladi.",note:"لَبْسٌ — «chalkashlik, noaniqlik»; لُبْسٌ esa «kiyish». فُهُومٌ — فَهْمٌ ning ko‘pligi."},
{num:326,time:"00:29:05,120 --> 00:29:08,440",arabic:"حِيَالَ مَعَانِي النُّصُوصِ الشَّرْعِيَّةِ.",segs:[{ar:"حِيَالَ مَعَانِي",uz:"ma’nolariga doir"},{ar:"النُّصُوصِ الشَّرْعِيَّةِ",uz:"shar’iy matnlarning"}],full_uz:"Shar’iy matnlarning ma’nolariga doir.",note:"حِيَالَ — «...borasida, ...ga nisbatan»."},
{num:327,time:"00:29:08,440 --> 00:29:14,660",arabic:"فَالتَّعَارُضُ وَالِاخْتِلَافُ لَا وُجُودَ لَهُمَا فِي كَلَامِ اللَّهِ.",segs:[{ar:"فَالتَّعَارُضُ وَالِاخْتِلَافُ",uz:"ziddiyat va qarama-qarshilikning"},{ar:"لَا وُجُودَ لَهُمَا",uz:"ikkalasi ham mavjud emas"},{ar:"فِي كَلَامِ اللَّهِ",uz:"Allohning kalomida"}],full_uz:"Allohning kalomida ziddiyat va qarama-qarshilik mavjud emas.",note:"لَهُمَا dagi ikkilik olmoshi التَّعَارُضُ va الِاخْتِلَافُ ga qaytadi."},
{num:328,time:"00:29:14,660 --> 00:29:17,640",arabic:"وَلَا كَلَامِ رَسُولِهِ.",segs:null,full_uz:"Uning Rasulining so‘zlarida ham yo‘q.",note:"Oldingi gapdagi فِي ma’nosi bu bandda ham davom etadi."},
{num:329,time:"00:29:17,640 --> 00:29:21,880",arabic:"بَلْ مَبْعَثُهُ وَمَنْشَؤُهُ مِنْ فُهُومِنَا.",segs:[{ar:"بَلْ مَبْعَثُهُ وَمَنْشَؤُهُ",uz:"aksincha, uning kelib chiqishi va manbai"},{ar:"مِنْ فُهُومِنَا",uz:"bizning tushunchalarimizdandir"}],full_uz:"Aksincha, uning kelib chiqishi va manbai bizning tushunchalarimizdadir.",note:"مَبْعَثٌ va مَنْشَأٌ — bir narsaning kelib chiqish manbai."},
{num:330,time:"00:29:21,880 --> 00:29:26,980",arabic:"الَّتِي قَدْ تَقْصُرُ عَنْ فَهْمِ مُرَادِ اللَّهِ وَرَسُولِهِ.",segs:[{ar:"الَّتِي قَدْ تَقْصُرُ",uz:"ular ojizlik qilishi mumkin"},{ar:"عَنْ فَهْمِ مُرَادِ اللَّهِ وَرَسُولِهِ",uz:"Alloh va Rasulining murodini anglashda"}],full_uz:"Ular Alloh va Rasulining murodini anglashda ojizlik qilishi mumkin.",note:"قَصُرَ عَنْ — «...ga yetmadi, ojizlik qildi». قَدْ muzoriy bilan ehtimolni bildiradi."},
{num:331,time:"00:29:26,980 --> 00:29:42,880",arabic:"مَا سِرُّ هَذَا الصَّمْتِ يَا فَوْزُ؟",segs:[{ar:"مَا سِرُّ هَذَا الصَّمْتِ",uz:"bu sukutning sababi nima"},{ar:"يَا فَوْزُ؟",uz:"ey Favz?"}],full_uz:"Bu sukutning sababi nima, Favz?",note:"سِرٌّ aslida «sir»; bu yerda yashirin sababni so‘rash uchun ishlatilgan."},
{num:332,time:"00:29:44,800 --> 00:29:45,780",arabic:"أَخْبِرِينِي.",segs:null,full_uz:"Menga ayting.",note:null},
{num:333,time:"00:29:45,780 --> 00:29:48,880",arabic:"أَحْيَانًا حِينَ لَا تَمْلِكِينَ الْأَدِلَّةَ عَلَى مَا تَقُولِينَ...",segs:[{ar:"أَحْيَانًا",uz:"ba’zan"},{ar:"حِينَ لَا تَمْلِكِينَ الْأَدِلَّةَ",uz:"dalillaringiz bo‘lmaganida"},{ar:"عَلَى مَا تَقُولِينَ",uz:"aytayotgan gaplaringizga"}],full_uz:"Ba’zan aytayotgan gaplaringizga dalillaringiz bo‘lmaganida...",note:"أَدِلَّةٌ — دَلِيلٌ («dalil»)ning ko‘pligi."},
{num:334,time:"00:29:48,880 --> 00:29:52,580",arabic:"يُصْبِحُ الصِّدْقُ جُنُونًا لَا يَقْبَلُهُ عَقْلٌ.",segs:[{ar:"يُصْبِحُ الصِّدْقُ جُنُونًا",uz:"rost gap telbalikka aylanadi"},{ar:"لَا يَقْبَلُهُ عَقْلٌ",uz:"hech bir aql qabul qilmaydigan"}],full_uz:"Rost gap hech bir aql qabul qilmaydigan telbalikka aylanadi.",note:"يُصْبِحُ bu yerda «aylanadi, bo‘lib qoladi». جُنُونًا — uning mansub xabari."},
{num:335,time:"00:29:52,580 --> 00:29:55,380",arabic:"وَالْكَذِبُ الْمُتْقَنُ وَالْمُزَخْرَفُ...",segs:[{ar:"وَالْكَذِبُ الْمُتْقَنُ",uz:"puxta to‘qilgan yolg‘on esa"},{ar:"وَالْمُزَخْرَفُ",uz:"va bezatilgan"}],full_uz:"Puxta to‘qilgan va bezatilgan yolg‘on esa...",note:"مُتْقَنٌ — «puxta ishlangan»; مُزَخْرَفٌ — «bezatilgan»."},
{num:336,time:"00:29:55,380 --> 00:29:58,540",arabic:"حَقِيقَةٌ تُرْضِي الْجَمِيعَ وَتُرِيحُهُمْ.",segs:[{ar:"حَقِيقَةٌ",uz:"haqiqat bo‘ladi"},{ar:"تُرْضِي الْجَمِيعَ",uz:"barchani rozi qiladigan"},{ar:"وَتُرِيحُهُمْ",uz:"va ularni xotirjam qiladigan"}],full_uz:"Barchani rozi va xotirjam qiladigan haqiqat bo‘ladi.",note:"أَرْضَى — «rozi qildi»; أَرَاحَ — «rohatlantirdi, xotirjam qildi»."},
{num:337,time:"00:29:58,540 --> 00:30:03,280",arabic:"وَحِينَهَا مِنَ الْأَفْضَلِ لِلْمَرْءِ أَنْ يَصْمُتَ.",segs:[{ar:"وَحِينَهَا",uz:"shunday paytda"},{ar:"مِنَ الْأَفْضَلِ لِلْمَرْءِ",uz:"kishi uchun yaxshiroq"},{ar:"أَنْ يَصْمُتَ",uz:"sukut saqlashi"}],full_uz:"Shunday paytda kishi sukut saqlagani yaxshiroq.",note:"مِنَ الْأَفْضَلِ أَنْ... — «...gani yaxshiroq»."},
{num:338,time:"00:30:03,280 --> 00:30:06,180",arabic:"وَإِلَّا صَارَ أَفَّاكًا.",segs:[{ar:"وَإِلَّا",uz:"aks holda"},{ar:"صَارَ أَفَّاكًا",uz:"yolg‘onchiga aylanadi"}],full_uz:"Aks holda, u yolg‘onchiga aylanadi.",note:"أَفَّاكٌ — ko‘p yolg‘on gapiruvchi, bo‘htonchi; mubolag‘ali shakl."},
{num:339,time:"00:30:06,180 --> 00:30:09,140",arabic:"كَلَامُكِ هَذَا مُفْعَمٌ بِالصِّدْقِ.",segs:[{ar:"كَلَامُكِ هَذَا",uz:"bu gapingiz"},{ar:"مُفْعَمٌ بِالصِّدْقِ",uz:"rostlikka to‘la"}],full_uz:"Bu gapingiz rostlikka to‘la.",note:"مُفْعَمٌ بِـ — «...ga to‘la»."},
{num:340,time:"00:30:09,140 --> 00:30:11,880",arabic:"لِأَنَّهُ قَدْ مَسَّ قَلْبِي.",segs:null,full_uz:"Chunki u qalbimga ta’sir qildi.",note:"مَسَّ قَلْبِي — so‘zma-so‘z «qalbimga tegdi»; ya’ni chuqur ta’sir qildi."},
{num:341,time:"00:30:13,880 --> 00:30:18,320",arabic:"أَعْتَذِرُ لَكِ عَنْ كُلِّ مَا بَدَرَ مِنِّي.",segs:[{ar:"أَعْتَذِرُ لَكِ",uz:"sizdan uzr so‘rayman"},{ar:"عَنْ كُلِّ مَا بَدَرَ مِنِّي",uz:"mendan sodir bo‘lgan barcha ishlar uchun"}],full_uz:"Sizga qilgan barcha ishlarim uchun uzr so‘rayman.",note:"بَدَرَ مِنْهُ — «undan bir gap yoki xatti-harakat sodir bo‘ldi». اِعْتَذَرَ لِـ ... عَنْ ... — «...dan ...uchun uzr so‘radi»."},
{num:342,time:"00:30:18,880 --> 00:30:22,420",arabic:"إِنْ شِئْتِ أَنْ تُخْبِرِينِي قِصَّتَكِ...",segs:[{ar:"إِنْ شِئْتِ",uz:"agar istasangiz"},{ar:"أَنْ تُخْبِرِينِي قِصَّتَكِ",uz:"menga hikoyangizni aytib berishni"}],full_uz:"Agar menga hikoyangizni aytib berishni istasangiz...",note:"شِئْتِ — ayol kishiga «istadingiz». تُخْبِرِينِي tarkibidagi ن himoya nunidir."},
{num:343,time:"00:30:22,420 --> 00:30:24,560",arabic:"وَإِلَّا فَلَا.",segs:null,full_uz:"Istamasangiz, shart emas.",note:"To‘liq ma’no oldingi shartdan anglashiladi: «agar istamasangiz, aytishingiz shart emas»."},
{num:344,time:"00:30:24,560 --> 00:30:29,280",arabic:"وَلَكِنْ أُرِيدُكِ أَنْ تَعْلَمِي...",segs:[{ar:"وَلَكِنْ أُرِيدُكِ",uz:"lekin sizdan istayman"},{ar:"أَنْ تَعْلَمِي",uz:"bilishingizni"}],full_uz:"Lekin bilishingizni istayman...",note:null},
{num:345,time:"00:30:29,280 --> 00:30:32,040",arabic:"أَنَّكِ وَمُنْذُ هَذِهِ اللَّحْظَةِ...",segs:[{ar:"أَنَّكِ",uz:"siz"},{ar:"وَمُنْذُ هَذِهِ اللَّحْظَةِ",uz:"aynan shu lahzadan boshlab"}],full_uz:"Siz aynan shu lahzadan boshlab...",note:null},
{num:346,time:"00:30:32,040 --> 00:30:33,380",arabic:"أُخْتِي.",segs:null,full_uz:"Singlimsiz.",note:null},
{num:347,time:"00:30:33,380 --> 00:30:36,040",arabic:"وَلَسْتِ خَادِمَتِي.",segs:null,full_uz:"Xizmatkorim emassiz.",note:"لَسْتِ — ayol kishiga «siz ... emassiz»."},
{num:348,time:"00:30:36,040 --> 00:30:39,080",arabic:"أَسَمِعْتِ يَا أُخْتِي؟",segs:[{ar:"أَسَمِعْتِ",uz:"eshitdingizmi"},{ar:"يَا أُخْتِي؟",uz:"ey singlim?"}],full_uz:"Eshitdingizmi, singlim?",note:null},
{num:349,time:"00:30:39,080 --> 00:30:47,340",arabic:"أَنَا فَتَاةٌ حُرَّةٌ.",segs:null,full_uz:"Men ozod qizman.",note:null},
{num:350,time:"00:30:47,339 --> 00:30:51,919",arabic:"وَابْنَةُ تَاجِرٍ فِي خُرَاسَانَ.",segs:[{ar:"وَابْنَةُ تَاجِرٍ",uz:"va bir savdogarning qiziman"},{ar:"فِي خُرَاسَانَ",uz:"Xurosondagi"}],full_uz:"Va Xurosondagi bir savdogarning qiziman.",note:null},
{num:351,time:"00:30:51,919 --> 00:30:56,339",arabic:"فَتَاةٌ كَكُلِّ الْفَتَيَاتِ.",segs:null,full_uz:"Barcha qizlar kabi bir qiz.",note:null},
{num:352,time:"00:30:56,339 --> 00:31:01,980",arabic:"تُحِبُّ الْحَيَاةَ وَتَعْشَقُ الْحُرِّيَّةَ.",segs:[{ar:"تُحِبُّ الْحَيَاةَ",uz:"hayotni sevadi"},{ar:"وَتَعْشَقُ الْحُرِّيَّةَ",uz:"va ozodlikni juda sevadi"}],full_uz:"Hayotni sevadi va ozodlikni juda sevadi.",note:"عَشِقَ — kuchli muhabbatni bildiradi; faqat kishilarga nisbatan ishlatilmaydi."},
{num:353,time:"00:31:01,980 --> 00:31:07,480",arabic:"وَتَحْلُمُ بِذَلِكَ الْفَارِسِ الْمُنْتَظَرِ...",segs:[{ar:"وَتَحْلُمُ",uz:"va orzu qiladi"},{ar:"بِذَلِكَ الْفَارِسِ الْمُنْتَظَرِ",uz:"o‘sha kutilgan chavandozni"}],full_uz:"Va o‘sha kutilgan chavandozni orzu qiladi...",note:"الْفَارِسُ الْمُنْتَظَرُ bu yerda orzudagi bo‘lajak umr yo‘ldoshga ishora qiladi."},
{num:354,time:"00:31:07,480 --> 00:31:11,859",arabic:"الَّذِي يَأْخُذُهَا إِلَى جَنَّتِهَا الْجَدِيدَةِ.",segs:[{ar:"الَّذِي يَأْخُذُهَا",uz:"uni olib ketadigan"},{ar:"إِلَى جَنَّتِهَا الْجَدِيدَةِ",uz:"yangi jannatiga"}],full_uz:"Uni yangi jannatiga olib ketadigan.",note:"جَنَّتُهَا الْجَدِيدَةُ — baxtli yangi hayotning ko‘chma tasviri."},
{num:355,time:"00:31:13,859 --> 00:31:16,240",arabic:"فَتَاةٌ أَلَحَّتْ عَلَى أَبِيهَا...",segs:[{ar:"فَتَاةٌ",uz:"bir qiz"},{ar:"أَلَحَّتْ عَلَى أَبِيهَا",uz:"otasidan qayta-qayta so‘ragan"}],full_uz:"Otasidan qayta-qayta so‘ragan bir qiz...",note:"أَلَحَّ عَلَى — «qayta-qayta talab yoki iltimos qildi»."},
{num:356,time:"00:31:16,240 --> 00:31:19,759",arabic:"أَنْ تُرَافِقَهُ هِيَ وَأُخْتُهَا...",segs:[{ar:"أَنْ تُرَافِقَهُ",uz:"unga hamroh bo‘lishni"},{ar:"هِيَ وَأُخْتُهَا",uz:"o‘zi va singlisi"}],full_uz:"O‘zi va singlisi unga hamroh bo‘lishini...",note:"هِيَ ayol kishini alohida ko‘rsatib, وَأُخْتُهَا bilan ikkinchi ishtirokchini qo‘shmoqda."},
{num:357,time:"00:31:19,759 --> 00:31:23,380",arabic:"فِي سَفَرٍ مِنْ أَسْفَارِهِ إِلَى بَغْدَادَ.",segs:[{ar:"فِي سَفَرٍ مِنْ أَسْفَارِهِ",uz:"uning safarlaridan birida"},{ar:"إِلَى بَغْدَادَ",uz:"Bag‘dodga"}],full_uz:"Uning Bag‘dodga qiladigan safarlaridan birida.",note:"أَسْفَارٌ — سَفَرٌ («safar»)ning ko‘pligi."},
{num:358,time:"00:31:23,380 --> 00:31:26,160",arabic:"إِلَى أَنْ وَافَقَ.",segs:null,full_uz:"Nihoyat, u rozi bo‘lguniga qadar.",note:"إِلَى أَنْ — «...guniga qadar». وَافَقَ — «rozi bo‘ldi»."},
{num:359,time:"00:31:46,240 --> 00:31:53,079",arabic:"اِنْتَظِرْ أَيُّهَا الشَّابُّ.",segs:[{ar:"اِنْتَظِرْ",uz:"to‘xtang, kuting"},{ar:"أَيُّهَا الشَّابُّ",uz:"ey yigit"}],full_uz:"To‘xtang, ey yigit.",note:null},
{num:360,time:"00:31:53,079 --> 00:32:02,400",arabic:"مِنْ أَيِّ الْبِلَادِ أَنْتَ؟ لَمْ أَرَكَ مِنْ قَبْلُ فِي حَلْقَةِ دَرْسِي.",segs:[{ar:"مِنْ أَيِّ الْبِلَادِ أَنْتَ؟",uz:"qaysi yurtdansiz?"},{ar:"لَمْ أَرَكَ مِنْ قَبْلُ",uz:"sizni ilgari ko‘rmaganman"},{ar:"فِي حَلْقَةِ دَرْسِي",uz:"dars davramda"}],full_uz:"Qaysi yurtdansiz? Sizni ilgari dars davramda ko‘rmaganman.",note:"حَلْقَةُ الدَّرْسِ — ustoz atrofida yig‘ilib dars tinglanadigan davra. لَمْ أَرَ da oxirgi illat harfi tushgan."},
{num:361,time:"00:32:02,400 --> 00:32:04,720",arabic:"أَحْمَدُ بْنُ حَنْبَلٍ مِنْ بَغْدَادَ.",segs:[{ar:"أَحْمَدُ بْنُ حَنْبَلٍ",uz:"Ahmad ibn Hanbalman"},{ar:"مِنْ بَغْدَادَ",uz:"Bag‘doddan"}],full_uz:"Bag‘dodlik Ahmad ibn Hanbalman.",note:null},
{num:362,time:"00:32:04,720 --> 00:32:06,720",arabic:"مِنْ بَغْدَادَ؟",segs:null,full_uz:"Bag‘doddanmi?",note:null},
{num:363,time:"00:32:07,359 --> 00:32:11,720",arabic:"آهٍ عَلَى بَغْدَادَ حَاضِرَةِ خِلَافَةِ الْإِسْلَامِ وَالْمُسْلِمِينَ!",segs:[{ar:"آهٍ عَلَى بَغْدَادَ",uz:"oh, Bag‘dod"},{ar:"حَاضِرَةِ خِلَافَةِ الْإِسْلَامِ وَالْمُسْلِمِينَ",uz:"Islom va musulmonlar xalifaligining poytaxti"}],full_uz:"Oh, Islom va musulmonlar xalifaligining poytaxti Bag‘dod!",note:"حَاضِرَةٌ bu yerda «poytaxt, markaziy shahar». آهٍ sog‘inch va hayajonni ifodalaydi."},
{num:364,time:"00:32:11,720 --> 00:32:15,720",arabic:"مَا أَجْمَلَ أَيَّامَهَا عِلْمًا وَفِقْهًا...",segs:[{ar:"مَا أَجْمَلَ أَيَّامَهَا",uz:"u yerdagi kunlar naqadar go‘zal"},{ar:"عِلْمًا وَفِقْهًا",uz:"ilm va fiqh jihatidan"}],full_uz:"U yerdagi kunlar ilm va fiqh jihatidan naqadar go‘zal edi...",note:"مَا أَجْمَلَ... — taajjub qolipi: «naqadar go‘zal!». عِلْمًا va فِقْهًا qaysi jihatdan ekanini bildiradi."},
{num:365,time:"00:32:15,720 --> 00:32:18,160",arabic:"وَأَدَبًا وَمَنْظَرًا حَسَنًا.",segs:[{ar:"وَأَدَبًا",uz:"odob jihatidan ham"},{ar:"وَمَنْظَرًا حَسَنًا",uz:"va go‘zal manzarasi bilan"}],full_uz:"Odob va go‘zal manzarasi bilan ham.",note:null},
{num:366,time:"00:32:18,160 --> 00:32:22,220",arabic:"حَمَاهَا اللَّهُ وَحَمَى أَهْلَهَا مِنْ كُلِّ سُوءٍ.",segs:[{ar:"حَمَاهَا اللَّهُ",uz:"Alloh uni asrasin"},{ar:"وَحَمَى أَهْلَهَا",uz:"va ahlini ham asrasin"},{ar:"مِنْ كُلِّ سُوءٍ",uz:"har qanday yomonlikdan"}],full_uz:"Alloh uni va ahlini har qanday yomonlikdan asrasin.",note:null},
{num:367,time:"00:32:22,220 --> 00:32:24,799",arabic:"أَوَزُرْتَ بَغْدَادَ يَا شَيْخَنَا؟",segs:[{ar:"أَوَزُرْتَ بَغْدَادَ",uz:"Bag‘dodga borganmisiz"},{ar:"يَا شَيْخَنَا؟",uz:"ey shayximiz?"}],full_uz:"Bag‘dodga borganmisiz, shayximiz?",note:"زَارَ — «ziyorat qildi, borib ko‘rdi». زُرْتَ — «siz borib ko‘rdingiz»."},
{num:368,time:"00:32:24,799 --> 00:32:27,319",arabic:"أَجَلْ، وَمَكَثْتُ فِيهَا رَدْحًا مِنَ الزَّمَنِ.",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"وَمَكَثْتُ فِيهَا",uz:"u yerda turdim"},{ar:"رَدْحًا مِنَ الزَّمَنِ",uz:"ancha vaqt"}],full_uz:"Ha, u yerda ancha vaqt turdim.",note:"رَدْحٌ مِنَ الزَّمَنِ — «ancha muddat, uzoq vaqt»."},
{num:369,time:"00:32:27,319 --> 00:32:31,500",arabic:"أَنَا أَبُو عَبْدِ اللَّهِ مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ.",segs:[{ar:"أَنَا أَبُو عَبْدِ اللَّهِ",uz:"men Abu Abdullohman"},{ar:"مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ",uz:"Muhammad ibn Idris Shofi’iy"}],full_uz:"Men Abu Abdulloh Muhammad ibn Idris Shofi’iyman.",note:null},
{num:370,time:"00:32:31,500 --> 00:32:32,740",arabic:"حَفِظَكَ اللَّهُ.",segs:null,full_uz:"Alloh sizni asrasin.",note:null},
{num:371,time:"00:32:32,740 --> 00:32:36,319",arabic:"قَدْ سَمِعْتُ الْيَوْمَ فِي دَرْسِكَ كَلَامًا لَمْ أَسْمَعْهُ مِنْ قَبْلُ.",segs:[{ar:"قَدْ سَمِعْتُ الْيَوْمَ",uz:"bugun eshitdim"},{ar:"فِي دَرْسِكَ",uz:"darsingizda"},{ar:"كَلَامًا لَمْ أَسْمَعْهُ مِنْ قَبْلُ",uz:"ilgari eshitmagan gaplarni"}],full_uz:"Bugun darsingizda ilgari eshitmagan gaplarni eshitdim.",note:null},
{num:372,time:"00:32:36,319 --> 00:32:40,019",arabic:"حَفِظَكَ اللَّهُ لَنَا وَنَفَعَنَا بِعِلْمِكَ يَا شَيْخَنَا.",segs:[{ar:"حَفِظَكَ اللَّهُ لَنَا",uz:"Alloh sizni biz uchun asrasin"},{ar:"وَنَفَعَنَا بِعِلْمِكَ",uz:"va ilmingizdan bizni bahramand qilsin"},{ar:"يَا شَيْخَنَا",uz:"ey shayximiz"}],full_uz:"Alloh sizni biz uchun asrasin va ilmingizdan bizni bahramand qilsin, shayximiz.",note:"نَفَعَهُ بِشَيْءٍ — «bir narsa bilan unga foyda yetkazdi»."},
{num:373,time:"00:32:41,759 --> 00:32:43,759",arabic:"أَتَأْذَنُ لِي أَنْ أَطْرَحَ عَلَيْكَ سُؤَالًا؟",segs:[{ar:"أَتَأْذَنُ لِي",uz:"menga ruxsat berasizmi"},{ar:"أَنْ أَطْرَحَ عَلَيْكَ سُؤَالًا؟",uz:"sizga bir savol berishga?"}],full_uz:"Sizga bir savol berishimga ruxsat berasizmi?",note:"طَرَحَ سُؤَالًا — «savol berdi, savolni o‘rtaga tashladi»."},
{num:374,time:"00:32:46,140 --> 00:32:51,640",arabic:"كَيْفَ نُوَفِّقُ بَيْنَ حَدِيثِ أَبِي هُرَيْرَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ...",segs:[{ar:"كَيْفَ نُوَفِّقُ بَيْنَ",uz:"qanday muvofiqlashtiramiz"},{ar:"حَدِيثِ أَبِي هُرَيْرَةَ",uz:"Abu Hurayraning hadisini"},{ar:"أَنَّ النَّبِيَّ",uz:"Payg‘ambar ... qilganlari haqidagi"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Abu Hurayraning Payg‘ambar haqida rivoyat qilgan hadislarini qanday muvofiqlashtiramiz? Alloh unga salovot va salom yo‘llasin...",note:"وَفَّقَ بَيْنَ أَمْرَيْنِ — «ikki narsani bir-biriga muvofiqlashtirdi»."},
{num:375,time:"00:32:51,640 --> 00:32:53,460",arabic:"نَهَى عَنْ صَوْمِ يَوْمِ عَرَفَةَ.",segs:[{ar:"نَهَى",uz:"qaytardilar"},{ar:"عَنْ صَوْمِ يَوْمِ عَرَفَةَ",uz:"Arafa kuni ro‘za tutishdan"}],full_uz:"Arafa kuni ro‘za tutishdan qaytarganlari haqidagi.",note:"نَهَى عَنْ — «...dan qaytardi, taqiqladi»."},
{num:376,time:"00:32:53,460 --> 00:32:57,519",arabic:"وَبَيْنَ حَدِيثِ أَبِي قَتَادَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ...",segs:[{ar:"وَبَيْنَ حَدِيثِ أَبِي قَتَادَةَ",uz:"va Abu Qatodaning hadisini"},{ar:"أَنَّ النَّبِيَّ",uz:"Payg‘ambar ... qilganlari haqidagi"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"Va Abu Qatodaning Payg‘ambar haqida rivoyat qilgan hadislarini? Alloh unga salovot va salom yo‘llasin...",note:"وَبَيْنَ oldingi بَيْنَ bilan bog‘lanib, taqqoslanayotgan ikkinchi narsani keltiradi."},
{num:377,time:"00:32:57,519 --> 00:33:02,039",arabic:"أَخْبَرَ أَنَّ صَوْمَ يَوْمِ عَرَفَةَ يُكَفِّرُ سَنَةً قَبْلَهُ وَسَنَةً بَعْدَهُ.",segs:[{ar:"أَخْبَرَ",uz:"xabar berdilar"},{ar:"أَنَّ صَوْمَ يَوْمِ عَرَفَةَ",uz:"Arafa kuni ro‘za tutish"},{ar:"يُكَفِّرُ سَنَةً قَبْلَهُ",uz:"undan oldingi bir yilga kafforat bo‘lishini"},{ar:"وَسَنَةً بَعْدَهُ",uz:"va undan keyingi bir yilga"}],full_uz:"Arafa kuni ro‘za tutish undan oldingi va keyingi bir yillik gunohlarga kafforat bo‘lishini xabar berganlari haqidagi.",note:"كَفَّرَ — «kafforat bo‘ldi, gunohni yuvdi». سَنَةً da shu yilning gunohlari nazarda tutilgan."},
{num:378,time:"00:33:02,039 --> 00:33:08,000",arabic:"سُؤَالُكَ هَذَا لَا يَصْدُرُ إِلَّا عَنْ وَلِهٍ مُحِبٍّ لِلْحَدِيثِ الشَّرِيفِ.",segs:[{ar:"سُؤَالُكَ هَذَا",uz:"bu savolingiz"},{ar:"لَا يَصْدُرُ إِلَّا عَنْ",uz:"faqat ...dan chiqadi"},{ar:"وَلِهٍ مُحِبٍّ",uz:"ishqi baland, sevuvchi kishidan"},{ar:"لِلْحَدِيثِ الشَّرِيفِ",uz:"hadisi sharifni"}],full_uz:"Bu savolingiz faqat hadisi sharifni qattiq sevuvchi kishidan chiqadi.",note:"صَدَرَ عَنْ — «...dan chiqdi, kelib chiqdi». وَلِهٌ — kuchli mehr yoki ishqqa berilgan kishi."},
{num:379,time:"00:33:08,000 --> 00:33:11,140",arabic:"تَعَالَ يَا أَحْمَدُ وَاجْلِسْ.",segs:[{ar:"تَعَالَ يَا أَحْمَدُ",uz:"keling, Ahmad"},{ar:"وَاجْلِسْ",uz:"va o‘tiring"}],full_uz:"Keling, Ahmad, o‘tiring.",note:null},
{num:380,time:"00:33:11,140 --> 00:33:20,140",arabic:"التَّعَارُضُ الَّذِي يَظْهَرُ بَيْنَ الْحَدِيثَيْنِ...",segs:[{ar:"التَّعَارُضُ الَّذِي يَظْهَرُ",uz:"ko‘rinayotgan ziddiyatni"},{ar:"بَيْنَ الْحَدِيثَيْنِ",uz:"ikki hadis orasida"}],full_uz:"Ikki hadis orasida ko‘rinayotgan ziddiyatni...",note:"الْحَدِيثَيْنِ — ikkilikning jar shakli: «ikki hadis»."},
{num:381,time:"00:33:20,140 --> 00:33:24,120",arabic:"يُزِيلُهُ حَدِيثُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا.",segs:[{ar:"يُزِيلُهُ حَدِيثُ عَائِشَةَ",uz:"Oishaning hadisi yo‘qotadi"},{ar:"رَضِيَ اللَّهُ عَنْهَا",uz:"Alloh undan rozi bo‘lsin"}],full_uz:"Oishaning hadisi yo‘qotadi. Alloh undan rozi bo‘lsin.",note:"أَزَالَ — يُزِيلُ — «yo‘qotmoq, bartaraf qilmoq»."},
{num:382,time:"00:33:24,120 --> 00:33:28,560",arabic:"قَالَتْ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ...",segs:[{ar:"قَالَتْ",uz:"u aytdi"},{ar:"نَهَى رَسُولُ اللَّهِ",uz:"Alloh Rasuli qaytardilar"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh unga salovot va salom yo‘llasin"}],full_uz:"U aytdi: «Alloh Rasuli qaytardilar...» Alloh unga salovot va salom yo‘llasin.",note:null},
{num:383,time:"00:33:28,560 --> 00:33:32,460",arabic:"عَنْ صَوْمِ يَوْمِ عَرَفَةَ بِعَرَفَاتٍ.",segs:[{ar:"عَنْ صَوْمِ يَوْمِ عَرَفَةَ",uz:"Arafa kuni ro‘za tutishdan"},{ar:"بِعَرَفَاتٍ",uz:"Arafotda"}],full_uz:"Arafa kuni Arafotda ro‘za tutishdan.",note:"بِعَرَفَاتٍ joyni bildiradi: «Arafotda»."},
{num:384,time:"00:33:32,460 --> 00:33:36,020",arabic:"يَتَبَيَّنُ مِنْ هَذَا أَنَّ صَوْمَ يَوْمِ عَرَفَةَ...",segs:[{ar:"يَتَبَيَّنُ مِنْ هَذَا",uz:"bundan ayon bo‘ladiki"},{ar:"أَنَّ صَوْمَ يَوْمِ عَرَفَةَ",uz:"Arafa kuni ro‘za tutish"}],full_uz:"Bundan ayon bo‘ladiki, Arafa kuni ro‘za tutish...",note:null},
{num:385,time:"00:33:36,020 --> 00:33:38,320",arabic:"لِغَيْرِ الْحَاجِّ.",segs:null,full_uz:"Haj qilmayotgan kishi uchundir.",note:"غَيْرُ الْحَاجِّ — «hoji bo‘lmagan, o‘sha paytda haj qilmayotgan kishi»."},
{num:386,time:"00:33:38,319 --> 00:33:48,000",arabic:"أَمَّا الْحَاجُّ فَعَلَيْهِ تَرْكُ الصِّيَامِ حَتَّى يَتَفَرَّغَ لِلدُّعَاءِ وَيَتَقَوَّى عَلَى الْعِبَادَةِ.",segs:[{ar:"أَمَّا الْحَاجُّ",uz:"haj qilayotgan kishiga kelsak"},{ar:"فَعَلَيْهِ تَرْكُ الصِّيَامِ",uz:"u ro‘zani tark qilishi kerak"},{ar:"حَتَّى يَتَفَرَّغَ لِلدُّعَاءِ",uz:"duoga o‘zini bag‘ishlashi uchun"},{ar:"وَيَتَقَوَّى عَلَى الْعِبَادَةِ",uz:"va ibodatga kuch to‘plashi uchun"}],full_uz:"Haj qilayotgan kishi esa duoga o‘zini bag‘ishlash va ibodatga kuch to‘plash uchun ro‘zani tark qilishi kerak.",note:"تَفَرَّغَ لِـ — «o‘zini bir ishga bag‘ishladi, boshqa ishlardan bo‘shadi». تَقَوَّى عَلَى — «...uchun kuch to‘pladi»."},
{num:387,time:"00:33:48,000 --> 00:33:50,439",arabic:"بَارَكَ اللَّهُ فِيكَ يَا شَيْخَنَا.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"يَا شَيْخَنَا",uz:"ey shayximiz"}],full_uz:"Alloh sizga baraka bersin, shayximiz.",note:null},
{num:388,time:"00:33:58,939 --> 00:34:00,740",arabic:"وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"وَعَلَيْكُمُ السَّلَامُ",uz:"sizga ham tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizga ham tinchlik va Allohning rahmati bo‘lsin.",note:null},
{num:389,time:"00:34:00,740 --> 00:34:02,419",arabic:"أَهْلًا بِبَائِعِ الشَّمْعِ، تَفَضَّلْ.",segs:[{ar:"أَهْلًا بِبَائِعِ الشَّمْعِ",uz:"xush kelibsiz, sham sotuvchi"},{ar:"تَفَضَّلْ",uz:"marhamat"}],full_uz:"Xush kelibsiz, sham sotuvchi, marhamat.",note:null},
{num:390,time:"00:34:02,419 --> 00:34:06,000",arabic:"بَارَكَ اللَّهُ فِيكَ، عِنْدِي سُؤَالٌ وَلَدَيْكَ جَوَابٌ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"عِنْدِي سُؤَالٌ",uz:"menda bir savol bor"},{ar:"وَلَدَيْكَ جَوَابٌ",uz:"sizda esa uning javobi bor"}],full_uz:"Alloh sizga baraka bersin. Menda bir savol bor, sizda esa uning javobi bor.",note:"عِنْدِي va لَدَيْكَ egalik yoki mavjudlikni bildiradi: «menda bor», «sizda bor»."},
{num:391,time:"00:34:06,000 --> 00:34:08,880",arabic:"أَلَيْسَ مِنَ الْأَفْضَلِ أَنْ تَدْخُلَ ثُمَّ نَتَحَدَّثَ؟",segs:[{ar:"أَلَيْسَ مِنَ الْأَفْضَلِ",uz:"yaxshiroq emasmi"},{ar:"أَنْ تَدْخُلَ",uz:"ichkariga kirsangiz"},{ar:"ثُمَّ نَتَحَدَّثَ؟",uz:"so‘ng gaplashsak?"}],full_uz:"Ichkariga kirib, keyin gaplashsak yaxshiroq emasmi?",note:null},
{num:392,time:"00:34:08,880 --> 00:34:10,079",arabic:"تَفَضَّلْ لِلدَّاخِلِ.",segs:null,full_uz:"Ichkariga marhamat.",note:null},
{num:393,time:"00:34:10,079 --> 00:34:11,679",arabic:"إِنِّي فِي عَجَلَةٍ مِنْ أَمْرِي.",segs:null,full_uz:"Men shoshilyapman.",note:"فِي عَجَلَةٍ مِنْ أَمْرِي — «shoshilyapman, vaqtim tig‘iz»."},
{num:394,time:"00:34:11,679 --> 00:34:16,260",arabic:"هُوَ سُؤَالٌ بِشَأْنِ الْجَارِيَةِ الَّتِي بِعْتُمُوهَا.",segs:[{ar:"هُوَ سُؤَالٌ",uz:"bu bir savol"},{ar:"بِشَأْنِ الْجَارِيَةِ",uz:"joriya haqida"},{ar:"الَّتِي بِعْتُمُوهَا",uz:"sizlar sotgan"}],full_uz:"Savolim sizlar sotgan joriya haqida.",note:"بِشَأْنِ — «...haqida, ...borasida». بِعْتُمُوهَا — «sizlar uni sotdingizlar»."},
{num:395,time:"00:34:16,260 --> 00:34:20,000",arabic:"وَكَيْفَ عَرَفْتَ أَنَّهُ كَانَ لَدَيْنَا جَارِيَةٌ وَبِعْنَاهَا؟",segs:[{ar:"وَكَيْفَ عَرَفْتَ",uz:"qanday bildingiz"},{ar:"أَنَّهُ كَانَ لَدَيْنَا جَارِيَةٌ",uz:"bizda bir joriya bo‘lganini"},{ar:"وَبِعْنَاهَا؟",uz:"va uni sotganimizni?"}],full_uz:"Bizda bir joriya bo‘lganini va uni sotganimizni qanday bildingiz?",note:null},
{num:396,time:"00:34:20,679 --> 00:34:21,800",arabic:"مِنْ أَحَدِ تُجَّارِ السُّوقِ.",segs:null,full_uz:"Bozordagi savdogarlardan biridan.",note:null},
{num:397,time:"00:34:21,800 --> 00:34:24,820",arabic:"لِمَاذَا تَسْأَلُ عَنْهَا؟ مَا شَأْنُكَ بِهَا؟",segs:[{ar:"لِمَاذَا تَسْأَلُ عَنْهَا؟",uz:"nega u haqida so‘rayapsiz?"},{ar:"مَا شَأْنُكَ بِهَا؟",uz:"unga nima aloqangiz bor?"}],full_uz:"Nega u haqida so‘rayapsiz? Unga nima aloqangiz bor?",note:null},
{num:398,time:"00:34:24,820 --> 00:34:26,159",arabic:"لَقَدْ سَمِعْتُ أَنَّ اسْمَهَا فَوْزٌ.",segs:[{ar:"لَقَدْ سَمِعْتُ",uz:"eshitdim"},{ar:"أَنَّ اسْمَهَا فَوْزٌ",uz:"uning ismi Favz ekanini"}],full_uz:"Uning ismi Favz ekanini eshitdim.",note:null},
{num:399,time:"00:34:26,159 --> 00:34:28,219",arabic:"وَلِي قَرِيبَةٌ تَحْمِلُ نَفْسَ الِاسْمِ.",segs:[{ar:"وَلِي قَرِيبَةٌ",uz:"bir qarindosh qizim bor"},{ar:"تَحْمِلُ نَفْسَ الِاسْمِ",uz:"xuddi shu ismli"}],full_uz:"Mening xuddi shu ismli bir qarindosh qizim bor.",note:"تَحْمِلُ نَفْسَ الِاسْمِ — so‘zma-so‘z «ayni ismni ko‘taradi», ya’ni shu ism bilan ataladi."},
{num:400,time:"00:34:28,219 --> 00:34:30,340",arabic:"وَقَدْ ضَاعَتْ مِنَّا فِي زَحْمَةِ أَسْوَاقِ بَغْدَادَ.",segs:[{ar:"وَقَدْ ضَاعَتْ مِنَّا",uz:"u bizdan yo‘qolib qoldi"},{ar:"فِي زَحْمَةِ أَسْوَاقِ بَغْدَادَ",uz:"Bag‘dod bozorlarining tiqilinchida"}],full_uz:"U Bag‘dod bozorlarining tiqilinchida bizdan yo‘qolib qoldi.",note:"زَحْمَةٌ — «tiqilinch, odamlar gavjumligi»."},
{num:401,time:"00:34:30,340 --> 00:34:33,320",arabic:"فَأَرَدْتُ أَنْ أَتَأَكَّدَ إِنْ كَانَتْ ذَاتَ الْفَتَاةِ.",segs:[{ar:"فَأَرَدْتُ أَنْ أَتَأَكَّدَ",uz:"shuning uchun aniqlashtirmoqchi bo‘ldim"},{ar:"إِنْ كَانَتْ ذَاتَ الْفَتَاةِ",uz:"aynan o‘sha qiz ekanini"}],full_uz:"Shuning uchun aynan o‘sha qiz ekanini aniqlashtirmoqchi bo‘ldim.",note:"ذَاتُ الْفَتَاةِ bu yerda «aynan o‘sha qiz»."},
{num:402,time:"00:34:33,320 --> 00:34:34,639",arabic:"تَقُولُ كَلَامًا غَرِيبًا.",segs:null,full_uz:"G‘alati gaplarni aytyapsiz.",note:null},
{num:403,time:"00:34:34,639 --> 00:34:38,779",arabic:"فَالْجَارِيَةُ الَّتِي كَانَتْ عِنْدَنَا اسْمُهَا رَغَدٌ، وَلَا نَعْرِفُ جَارِيَةً غَيْرَهَا.",segs:[{ar:"فَالْجَارِيَةُ الَّتِي كَانَتْ عِنْدَنَا",uz:"bizdagi joriyaning"},{ar:"اسْمُهَا رَغَدٌ",uz:"ismi Rag‘ad edi"},{ar:"وَلَا نَعْرِفُ جَارِيَةً غَيْرَهَا",uz:"undan boshqa joriyani bilmaymiz"}],full_uz:"Bizdagi joriyaning ismi Rag‘ad edi. Undan boshqa joriyani bilmaymiz.",note:null},
{num:404,time:"00:34:38,779 --> 00:34:41,519",arabic:"اِئْذَنْ لِي، فَلَدَيَّ عَمَلٌ فِي الدَّاخِلِ.",segs:[{ar:"اِئْذَنْ لِي",uz:"menga ruxsat bering"},{ar:"فَلَدَيَّ عَمَلٌ فِي الدَّاخِلِ",uz:"ichkarida ishim bor"}],full_uz:"Menga ruxsat bering, ichkarida ishim bor.",note:"اِئْذَنْ لِي — xayrlashish yoki suhbatdan chiqish uchun muloyim ruxsat so‘rash."},
{num:405,time:"00:35:04,639 --> 00:35:11,719",arabic:"إِنْ بَقِيَتْ هَذِهِ الْفَتَاةُ جَارِيَةً...",segs:[{ar:"إِنْ بَقِيَتْ هَذِهِ الْفَتَاةُ",uz:"agar bu qiz qolaversa"},{ar:"جَارِيَةً",uz:"joriya bo‘lib"}],full_uz:"Agar bu qiz joriya bo‘lib qolaversa...",note:null},
{num:406,time:"00:35:11,719 --> 00:35:15,119",arabic:"سَتَمُوتُ كَمَدًا وَحُزْنًا.",segs:[{ar:"سَتَمُوتُ",uz:"o‘lib qoladi"},{ar:"كَمَدًا وَحُزْنًا",uz:"ichki alam va qayg‘udan"}],full_uz:"Ichki alam va qayg‘udan o‘lib qoladi.",note:"كَمَدٌ — ichga yutilgan kuchli qayg‘u. كَمَدًا وَحُزْنًا o‘limning sababini bildiradi."},
{num:407,time:"00:35:15,119 --> 00:35:19,859",arabic:"فَمَا أَشَدَّ أَنْ يَفْقِدَ الْمَرْءُ حُرِّيَّتَهُ!",segs:[{ar:"فَمَا أَشَدَّ",uz:"naqadar og‘ir"},{ar:"أَنْ يَفْقِدَ الْمَرْءُ حُرِّيَّتَهُ",uz:"kishining ozodligini yo‘qotishi"}],full_uz:"Kishining ozodligini yo‘qotishi naqadar og‘ir!",note:"مَا أَشَدَّ... — taajjub qolipi: «naqadar og‘ir, naqadar kuchli!»."},
{num:408,time:"00:35:19,859 --> 00:35:22,980",arabic:"بَعْدَ أَنْ وُلِدْنَا أَحْرَارًا.",segs:[{ar:"بَعْدَ أَنْ وُلِدْنَا",uz:"tug‘ilganimizdan keyin"},{ar:"أَحْرَارًا",uz:"ozod bo‘lib"}],full_uz:"Axir biz ozod tug‘ilganmiz.",note:"وُلِدْنَا — majhul nisbat: «biz tug‘ildik». أَحْرَارًا — tug‘ilish paytidagi holat."},
{num:409,time:"00:35:22,980 --> 00:35:27,119",arabic:"لَنْ يَطُولَ حَالُكِ عَلَى مَا أَنْتِ عَلَيْهِ يَا فَوْزُ.",segs:[{ar:"لَنْ يَطُولَ حَالُكِ",uz:"holatingiz uzoq davom etmaydi"},{ar:"عَلَى مَا أَنْتِ عَلَيْهِ",uz:"hozirgi ahvolingizda"},{ar:"يَا فَوْزُ",uz:"ey Favz"}],full_uz:"Hozirgi ahvolingiz uzoq davom etmaydi, Favz.",note:"طَالَ — يَطُولُ — «uzoq davom etmoq, uzaymoq»."},
{num:410,time:"00:35:27,119 --> 00:35:30,699",arabic:"وَعْدٌ عَلَى بُثَيْنَةَ أَنْ تُنَفِّذَهُ.",segs:[{ar:"وَعْدٌ",uz:"bu bir va’da"},{ar:"عَلَى بُثَيْنَةَ أَنْ تُنَفِّذَهُ",uz:"Busayna uni bajarishi shart"}],full_uz:"Bu Busayna bajarishi shart bo‘lgan va’da.",note:"نَفَّذَ وَعْدًا — «va’dani bajardi». So‘zlovchi o‘zini ism bilan tilga olmoqda."},
{num:411,time:"00:35:34,639 --> 00:35:37,879",arabic:"لِمَ أَجَبْتُهُ بِهَذِهِ الطَّرِيقَةِ؟",segs:[{ar:"لِمَ أَجَبْتُهُ",uz:"nega unga javob berdim"},{ar:"بِهَذِهِ الطَّرِيقَةِ؟",uz:"bu tarzda?"}],full_uz:"Nega unga bu tarzda javob berdim?",note:"أَجَبْتُهُ — «men unga javob berdim»; أَجَبْتَهُ esa «siz unga javob berdingiz»."},
{num:412,time:"00:35:37,879 --> 00:35:43,239",arabic:"فَقَدْ أَثَرْتُ بِسُوءِ جَوَابِي شُكُوكَ بَائِعِ الشَّمْعِ هَذَا.",segs:[{ar:"فَقَدْ أَثَرْتُ",uz:"uyg‘otib qo‘ydim"},{ar:"بِسُوءِ جَوَابِي",uz:"yomon javobim bilan"},{ar:"شُكُوكَ بَائِعِ الشَّمْعِ هَذَا",uz:"bu sham sotuvchining shubhalarini"}],full_uz:"Yomon javobim bilan bu sham sotuvchining shubhalarini uyg‘otib qo‘ydim.",note:"أَثَارَ الشُّكُوكَ — «shubha uyg‘otdi». أَثَرْتُ — birinchi shaxs o‘tgan zamon shakli."},
{num:413,time:"00:35:43,239 --> 00:35:49,079",arabic:"مَاذَا لَوْ فَضَحَ أَمْرَنَا؟",segs:[{ar:"مَاذَا لَوْ",uz:"nima bo‘ladi, agar"},{ar:"فَضَحَ أَمْرَنَا؟",uz:"sirimizni fosh qilsa?"}],full_uz:"Sirimizni fosh qilsa nima bo‘ladi?",note:"فَضَحَ أَمْرَهُ — «uning yashirin ishini fosh qildi»."},
{num:414,time:"00:35:49,079 --> 00:35:53,960",arabic:"لِمَ كُلُّ هَذَا الْقَلَقِ يَا حَنْظَلَةُ؟",segs:[{ar:"لِمَ كُلُّ هَذَا الْقَلَقِ",uz:"nega buncha xavotir"},{ar:"يَا حَنْظَلَةُ؟",uz:"ey Hanzala?"}],full_uz:"Nega buncha xavotir, Hanzala?",note:null},
{num:415,time:"00:35:53,960 --> 00:35:58,199",arabic:"الْقِصَّةُ بِاخْتِصَارٍ: كَانَ لَدَيْنَا جَارِيَةٌ وَبِعْنَاهَا.",segs:[{ar:"الْقِصَّةُ بِاخْتِصَارٍ",uz:"gapning qisqasi"},{ar:"كَانَ لَدَيْنَا جَارِيَةٌ",uz:"bizda bir joriya bor edi"},{ar:"وَبِعْنَاهَا",uz:"va uni sotdik"}],full_uz:"Gapning qisqasi: bizda bir joriya bor edi va uni sotdik.",note:"بِاخْتِصَارٍ — «qisqacha»."},
{num:416,time:"00:35:58,199 --> 00:36:01,159",arabic:"مَنْ هِيَ؟ مِنْ أَيْنَ أَتَتْ؟ هَذَا أَمْرٌ لَا يَعْنِينَا.",segs:[{ar:"مَنْ هِيَ؟",uz:"u kim?"},{ar:"مِنْ أَيْنَ أَتَتْ؟",uz:"qayerdan kelgan?"},{ar:"هَذَا أَمْرٌ لَا يَعْنِينَا",uz:"bu bizga aloqasi yo‘q ish"}],full_uz:"U kim, qayerdan kelgan — bu bizga aloqador emas.",note:"لَا يَعْنِينَا — «bizga daxli yo‘q, bizni qiziqtirmaydi»."},
{num:417,time:"00:36:01,159 --> 00:36:08,639",arabic:"وَلَكِنْ مَا ذَنْبُ فَوْزٍ فِي كُلِّ هَذَا؟",segs:[{ar:"وَلَكِنْ مَا ذَنْبُ فَوْزٍ",uz:"lekin Favzning aybi nima"},{ar:"فِي كُلِّ هَذَا؟",uz:"bularning barchasida?"}],full_uz:"Lekin bularning barchasida Favzning aybi nima?",note:null},
{num:418,time:"00:36:08,639 --> 00:36:13,359",arabic:"قَدْ يَكُونُ الرَّجُلُ حَقًّا مِنْ أَهْلِهَا الَّذِينَ أَضَاعُوهَا.",segs:[{ar:"قَدْ يَكُونُ الرَّجُلُ حَقًّا",uz:"bu kishi haqiqatan bo‘lishi mumkin"},{ar:"مِنْ أَهْلِهَا",uz:"uning yaqinlaridan"},{ar:"الَّذِينَ أَضَاعُوهَا",uz:"uni yo‘qotib qo‘ygan"}],full_uz:"Bu kishi haqiqatan uni yo‘qotib qo‘ygan yaqinlaridan bo‘lishi mumkin.",note:"ضَاعَ — «yo‘qoldi»; أَضَاعَ — «yo‘qotdi»."},
{num:419,time:"00:36:13,359 --> 00:36:19,799",arabic:"مَا لِي أَنَا وَلِلزَّوَاجِ؟",segs:[{ar:"مَا لِي أَنَا",uz:"menga nima kerak"},{ar:"وَلِلزَّوَاجِ؟",uz:"uylanish?"}],full_uz:"Menga uylanishning nima keragi bor?",note:"مَا لِي وَلِـ...؟ — «mening ...bilan nima ishim bor?»."},
{num:420,time:"00:36:19,799 --> 00:36:22,440",arabic:"زَوْجَةٌ وَاحِدَةٌ تَكْفِي.",segs:null,full_uz:"Bitta xotin yetadi.",note:null},
{num:421,time:"00:36:22,440 --> 00:36:27,019",arabic:"ثُمَّ إِنَّ أُمَّ عُمَيْرٍ لَنْ تَرْضَى بِضَرَّةٍ عَلَيْهَا.",segs:[{ar:"ثُمَّ إِنَّ أُمَّ عُمَيْرٍ",uz:"qolaversa, Ummu Umayr"},{ar:"لَنْ تَرْضَى بِضَرَّةٍ عَلَيْهَا",uz:"ustiga kundosh kelishiga rozi bo‘lmaydi"}],full_uz:"Qolaversa, Ummu Umayr ustiga kundosh kelishiga rozi bo‘lmaydi.",note:"ضَرَّةٌ — «kundosh», bir erkakka turmushga chiqqan ayollarning bir-biriga nisbatan nomi."},
{num:422,time:"00:36:27,019 --> 00:36:30,099",arabic:"إِنَّهَا دُونَ ضَرَّةٍ غَيْرُ رَاضِيَةٍ عَنِّي.",segs:[{ar:"إِنَّهَا دُونَ ضَرَّةٍ",uz:"u kundoshi yo‘q holda ham"},{ar:"غَيْرُ رَاضِيَةٍ عَنِّي",uz:"mendan rozi emas"}],full_uz:"U kundoshi yo‘q holda ham mendan rozi emas.",note:"رَضِيَ عَنْ شَخْصٍ — «bir kishidan rozi bo‘ldi»; رَضِيَ بِشَيْءٍ — «bir narsaga rozi bo‘ldi»."},
{num:423,time:"00:36:30,099 --> 00:36:34,099",arabic:"فَكَيْفَ بِأُخْرَى؟ وَأَضِيعُ أَنَا بَيْنَهُمَا.",segs:[{ar:"فَكَيْفَ بِأُخْرَى؟",uz:"yana biri bo‘lsa, qanday bo‘ladi?"},{ar:"وَأَضِيعُ أَنَا بَيْنَهُمَا",uz:"men esa ikkovining orasida sarson bo‘laman"}],full_uz:"Yana biri bo‘lsa, qanday bo‘ladi? Men ikkovining orasida sarson bo‘laman.",note:"بَيْنَهُمَا — «ular ikkovining orasida»."},
{num:424,time:"00:36:35,099 --> 00:36:36,099",arabic:"لَكِنْ أُمِّي...",segs:null,full_uz:"Lekin onam...",note:null},
{num:425,time:"00:36:37,099 --> 00:36:40,099",arabic:"أُمِّي إِنَّهَا فِي مَعْرَكَةٍ مَعَ أُمِّ عُمَيْرٍ.",segs:[{ar:"أُمِّي إِنَّهَا فِي مَعْرَكَةٍ",uz:"onam urush holatida"},{ar:"مَعَ أُمِّ عُمَيْرٍ",uz:"Ummu Umayr bilan"}],full_uz:"Onam Ummu Umayr bilan urush holatida.",note:"مَعْرَكَةٌ bu yerda haqiqiy jang emas, davomli kelishmovchilikni bildiradi."},
{num:426,time:"00:36:40,099 --> 00:36:42,099",arabic:"لَا نَاقَةَ لِي فِيهَا وَلَا جَمَلَ.",segs:[{ar:"لَا نَاقَةَ لِي فِيهَا",uz:"unda mening na urg‘ochi tuyam bor"},{ar:"وَلَا جَمَلَ",uz:"na erkak tuyam"}],full_uz:"Bu ishda mening hech qanday daxlim yo‘q.",note:"لَا نَاقَةَ لِي فِيهَا وَلَا جَمَلَ — «bu ishga daxlim ham, manfaatim ham yo‘q» degan maqol."},
{num:427,time:"00:36:42,099 --> 00:36:44,099",arabic:"وَأَنَا لَسْتُ نِدًّا لِأُمِّ عُمَيْرٍ.",segs:[{ar:"وَأَنَا لَسْتُ نِدًّا",uz:"men teng raqib emasman"},{ar:"لِأُمِّ عُمَيْرٍ",uz:"Ummu Umayrga"}],full_uz:"Men Ummu Umayrga teng raqib emasman.",note:"نِدٌّ — «teng keladigan raqib»."},
{num:428,time:"00:36:45,099 --> 00:36:48,099",arabic:"لَا، لَنْ أُغْضِبَ أُمَّ عُمَيْرٍ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"لَنْ أُغْضِبَ أُمَّ عُمَيْرٍ",uz:"Ummu Umayrni g‘azablantirmayman"}],full_uz:"Yo‘q, Ummu Umayrni g‘azablantirmayman.",note:"أَغْضَبَ — «g‘azablantirdi»; غَضِبَ — «g‘azablandi»."},
{num:429,time:"00:36:48,099 --> 00:36:51,099",arabic:"وَلْتَذْهَبِ الشَّقْرَاوَاتُ إِلَى الشَّيْطَانِ.",segs:[{ar:"وَلْتَذْهَبِ الشَّقْرَاوَاتُ",uz:"sariq sochli ayollar ketaversin"},{ar:"إِلَى الشَّيْطَانِ",uz:"shaytonning oldiga"}],full_uz:"Sariq sochli ayollar shaytonning oldiga ketaversin.",note:"لْ buyruq lomi uchinchi shaxsga buyruq yoki istak bildiradi. الشَّقْرَاوَاتُ — شَقْرَاءُ ning ko‘pligi."},
{num:430,time:"00:36:52,099 --> 00:36:54,099",arabic:"يَا بُهْلُولُ! مَاذَا تُرِيدُ؟",segs:[{ar:"يَا بُهْلُولُ",uz:"ey Buhlul"},{ar:"مَاذَا تُرِيدُ؟",uz:"nima istaysiz?"}],full_uz:"Ey Buhlul! Nima istaysiz?",note:null},
{num:431,time:"00:36:54,099 --> 00:37:03,099",arabic:"عِنْدَ تَجْوَالِكَ بَيْنَ الْقُبُورِ، هَلْ رَأَيْتَ الشَّيْطَانَ؟",segs:[{ar:"عِنْدَ تَجْوَالِكَ بَيْنَ الْقُبُورِ",uz:"qabrlar orasida aylanib yurganingizda"},{ar:"هَلْ رَأَيْتَ الشَّيْطَانَ؟",uz:"shaytonni ko‘rdingizmi?"}],full_uz:"Qabrlar orasida aylanib yurganingizda shaytonni ko‘rdingizmi?",note:"تَجْوَالٌ — «aylanib yurish, kezish»."},
{num:432,time:"00:37:03,099 --> 00:37:06,440",arabic:"أَجَلْ، رَأَيْتُهُ كَمَا أَرَاكَ الْآنَ.",segs:[{ar:"أَجَلْ، رَأَيْتُهُ",uz:"ha, uni ko‘rdim"},{ar:"كَمَا أَرَاكَ الْآنَ",uz:"hozir sizni ko‘rib turganimdek"}],full_uz:"Ha, uni hozir sizni ko‘rib turganimdek ko‘rdim.",note:null},
{num:433,time:"00:37:06,440 --> 00:37:08,420",arabic:"صِفْهُ لِي.",segs:null,full_uz:"Uni menga tasvirlab bering.",note:"وَصَفَ — يَصِفُ — صِفْ: buyruqda boshlang‘ich و tushadi."},
{num:434,time:"00:37:08,420 --> 00:37:13,139",arabic:"هَلْ لَدَيْكَ مِرْآةٌ فِي الْبَيْتِ؟",segs:[{ar:"هَلْ لَدَيْكَ مِرْآةٌ",uz:"oynangiz bormi"},{ar:"فِي الْبَيْتِ؟",uz:"uyda?"}],full_uz:"Uyda oynangiz bormi?",note:"مِرْآةٌ — «ko‘zgu, oyna»."},
{num:435,time:"00:37:13,139 --> 00:37:14,420",arabic:"وَكَبِيرَةٌ أَيْضًا.",segs:null,full_uz:"Kattasi ham bor.",note:null},
{num:436,time:"00:37:14,420 --> 00:37:19,099",arabic:"عَظِيمٌ، اُنْظُرْ فِي الْمِرْآةِ تَرَ الشَّيْطَانَ.",segs:[{ar:"عَظِيمٌ",uz:"juda yaxshi"},{ar:"اُنْظُرْ فِي الْمِرْآةِ",uz:"oynaga qarang"},{ar:"تَرَ الشَّيْطَانَ",uz:"shaytonni ko‘rasiz"}],full_uz:"Juda yaxshi, oynaga qarang, shaytonni ko‘rasiz.",note:"تَرَ buyruqning natijasi sifatida majzum; تَرَى dagi oxirgi illat harfi tushgan."},
{num:437,time:"00:37:26,120 --> 00:37:28,920",arabic:"مَاذَا يَقْصِدُ؟",segs:null,full_uz:"Nimani nazarda tutyapti?",note:null},
{num:438,time:"00:37:28,920 --> 00:37:32,660",arabic:"حَسَنًا، سَأُجَرِّبُ وَأَرَى إِنْ كَانَ كَلَامُهُ صَحِيحًا.",segs:[{ar:"حَسَنًا",uz:"xo‘p"},{ar:"سَأُجَرِّبُ وَأَرَى",uz:"sinab ko‘raman va bilaman"},{ar:"إِنْ كَانَ كَلَامُهُ صَحِيحًا",uz:"gapining to‘g‘ri ekanini"}],full_uz:"Xo‘p, sinab ko‘rib, gapining to‘g‘ri yoki noto‘g‘riligini bilaman.",note:"جَرَّبَ — «sinab ko‘rdi»."},
{num:439,time:"00:37:41,800 --> 00:37:46,100",arabic:"لَا تَنْسَيْ مَا أَوْصَيْتُكِ بِهِ بِشَأْنِ الْأَمِينِ وَالْمَأْمُونِ يَا زُبَيْدَةُ.",segs:[{ar:"لَا تَنْسَيْ",uz:"unutmang"},{ar:"مَا أَوْصَيْتُكِ بِهِ",uz:"sizga tayinlaganlarimni"},{ar:"بِشَأْنِ الْأَمِينِ وَالْمَأْمُونِ",uz:"Amin va Ma’mun haqida"},{ar:"يَا زُبَيْدَةُ",uz:"ey Zubayda"}],full_uz:"Amin va Ma’mun haqida sizga tayinlaganlarimni unutmang, Zubayda.",note:"لَا تَنْسَيْ — ayol kishiga taqiq. تَنْسَيْنَ shaklidagi ن jazm sababli tushadi."},
{num:440,time:"00:37:46,100 --> 00:37:50,019",arabic:"وَهَلْ أَنَا مَنْ تَنْسَى وَصَايَا مَوْلَاهَا؟",segs:[{ar:"وَهَلْ أَنَا مَنْ تَنْسَى",uz:"men unutadiganlardanmanmi"},{ar:"وَصَايَا مَوْلَاهَا؟",uz:"o‘z hukmdorining nasihatlarini?"}],full_uz:"Men o‘z hukmdorining nasihatlarini unutadiganlardanmanmi?",note:"وَصَايَا — وَصِيَّةٌ ning ko‘pligi: «nasihatlar, tayinlovlar»."},
{num:441,time:"00:37:50,019 --> 00:37:54,280",arabic:"اِطْمَئِنَّ، بِعَوْنِ اللَّهِ سَتَعُودُ إِلَيْنَا سَالِمًا غَانِمًا.",segs:[{ar:"اِطْمَئِنَّ",uz:"xotirjam bo‘ling"},{ar:"بِعَوْنِ اللَّهِ",uz:"Allohning yordami bilan"},{ar:"سَتَعُودُ إِلَيْنَا",uz:"bizning oldimizga qaytasiz"},{ar:"سَالِمًا غَانِمًا",uz:"omon va g‘animat bilan"}],full_uz:"Xotirjam bo‘ling, Allohning yordami bilan oldimizga omon va g‘animat bilan qaytasiz.",note:"سَالِمًا غَانِمًا — «omon-eson va yutuq bilan». Ikkala so‘z qaytishdagi holatni bildiradi."},
{num:442,time:"00:37:54,280 --> 00:37:59,659",arabic:"إِنَّمَا هِيَ وَصِيَّةُ مُوَدِّعٍ يَا زُبَيْدَةُ.",segs:[{ar:"إِنَّمَا هِيَ وَصِيَّةُ مُوَدِّعٍ",uz:"bu xayrlashayotgan kishining nasihati, xolos"},{ar:"يَا زُبَيْدَةُ",uz:"ey Zubayda"}],full_uz:"Bu xayrlashayotgan kishining nasihati, xolos, Zubayda.",note:"مُوَدِّعٌ — وَدَّعَ («xayrlashdi») fe’lining ismi foili."},
{num:443,time:"00:37:59,659 --> 00:38:04,000",arabic:"وَإِنِّي لَأَرْجُو اللَّهَ أَنْ يَمُنَّ عَلَيَّ بِالشَّهَادَةِ.",segs:[{ar:"وَإِنِّي لَأَرْجُو اللَّهَ",uz:"men Allohdan chin dildan umid qilaman"},{ar:"أَنْ يَمُنَّ عَلَيَّ",uz:"menga in’om etishini"},{ar:"بِالشَّهَادَةِ",uz:"shahidlikni"}],full_uz:"Men Alloh menga shahidlikni in’om etishini chin dildan umid qilaman.",note:"لَأَرْجُو dagi لَـ ta’kid bildiradi. مَنَّ عَلَيْهِ بِـ — «unga ...ni in’om qildi»."},
{num:444,time:"00:38:04,000 --> 00:38:06,800",arabic:"فَيَخْتِمَ لَنَا بِخَيْرٍ.",segs:null,full_uz:"Va oqibatimizni yaxshilik bilan yakunlasin.",note:"خَتَمَ لَهُ بِخَيْرٍ — «uning umrini yaxshi oqibat bilan yakunladi»."},
{num:445,time:"00:38:06,800 --> 00:38:11,739",arabic:"اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ.",segs:[{ar:"اللَّهُمَّ",uz:"Allohim"},{ar:"أَنْتَ الصَّاحِبُ فِي السَّفَرِ",uz:"safarda hamroh Sensan"}],full_uz:"Allohim, safarda hamroh Sensan.",note:null},
{num:446,time:"00:38:11,739 --> 00:38:14,500",arabic:"وَالْخَلِيفَةُ فِي الْأَهْلِ.",segs:null,full_uz:"Oilada o‘rnimizga qolib asrovchi ham Sensan.",note:"الْخَلِيفَةُ bu duoda siyosiy unvon emas, safardagi kishining ortida qolgan oilasiga qarovchi va asrovchi ma’nosida."},
{num:447,time:"00:38:42,019 --> 00:38:51,019",arabic:"اللَّهُ أَكْبَرُ.",segs:null,full_uz:"Alloh eng buyukdir.",note:null},
{num:448,time:"00:38:55,019 --> 00:38:57,019",arabic:"يَا جُنُودَ اللَّهِ!",segs:null,full_uz:"Ey Allohning askarlari!",note:null},
{num:449,time:"00:38:57,019 --> 00:39:00,019",arabic:"يَا حُمَاةَ الْأَرْضِ وَالْعَقِيدَةِ!",segs:[{ar:"يَا حُمَاةَ الْأَرْضِ",uz:"ey yurt himoyachilari"},{ar:"وَالْعَقِيدَةِ",uz:"va e’tiqodning"}],full_uz:"Ey yurt va e’tiqod himoyachilari!",note:"حُمَاةٌ — حَامٍ («himoyachi»)ning ko‘pligi."},
{num:450,time:"00:39:01,019 --> 00:39:04,019",arabic:"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"sizlarga tinchlik bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"va Allohning rahmati hamda barakalari"}],full_uz:"Sizlarga tinchlik, Allohning rahmati va barakalari bo‘lsin.",note:null},
{num:451,time:"00:39:07,019 --> 00:39:12,739",arabic:"إِنَّنَا الْيَوْمَ نَمْضِي لِنَذُودَ عَنْ حِمَى الْإِسْلَامِ وَالْمُسْلِمِينَ.",segs:[{ar:"إِنَّنَا الْيَوْمَ نَمْضِي",uz:"biz bugun yo‘lga chiqmoqdamiz"},{ar:"لِنَذُودَ",uz:"himoya qilish uchun"},{ar:"عَنْ حِمَى الْإِسْلَامِ وَالْمُسْلِمِينَ",uz:"Islom va musulmonlar hududini"}],full_uz:"Biz bugun Islom va musulmonlar hududini himoya qilish uchun yo‘lga chiqmoqdamiz.",note:"ذَادَ عَنْ — «himoya qildi, dushmanni qaytardi». حِمًى — «himoya qilinadigan hudud»."},
{num:452,time:"00:39:12,739 --> 00:39:20,500",arabic:"نَمْضِي إِلَى عَدُوِّ اللَّهِ نِقْفُورَ الَّذِي نَكَثَ بِعَهْدِهِ مَعَكُمْ.",segs:[{ar:"نَمْضِي إِلَى عَدُوِّ اللَّهِ نِقْفُورَ",uz:"Allohning dushmani Niqfur tomon bormoqdamiz"},{ar:"الَّذِي نَكَثَ بِعَهْدِهِ مَعَكُمْ",uz:"sizlar bilan qilgan ahdini buzgan"}],full_uz:"Sizlar bilan qilgan ahdini buzgan Allohning dushmani Niqfur tomon bormoqdamiz.",note:"نَكَثَ بِعَهْدِهِ — «ahdini buzdi»."},
{num:453,time:"00:39:20,500 --> 00:39:25,800",arabic:"فَكُونُوا كَمَا أَرَادَ اللَّهُ لَكُمْ أَنْ تَكُونُوا.",segs:[{ar:"فَكُونُوا",uz:"shunday bo‘linglar"},{ar:"كَمَا أَرَادَ اللَّهُ لَكُمْ",uz:"Alloh sizlar uchun istaganidek"},{ar:"أَنْ تَكُونُوا",uz:"bo‘lishingizni"}],full_uz:"Alloh sizlarni qanday bo‘lishingizni istagan bo‘lsa, shunday bo‘linglar.",note:"كُونُوا — كَانَ fe’lining ko‘plikdagi buyruq shakli."},
{num:454,time:"00:39:25,800 --> 00:39:30,880",arabic:"صُبُرًا فِي الْحَرْبِ، صُدُقًا عِنْدَ اللِّقَاءِ.",segs:[{ar:"صُبُرًا فِي الْحَرْبِ",uz:"urushda sabrli"},{ar:"صُدُقًا عِنْدَ اللِّقَاءِ",uz:"to‘qnashuvda sodiq"}],full_uz:"Urushda sabrli, to‘qnashuvda sodiq bo‘linglar.",note:"صُبُرٌ va صُدُقٌ kishilar ko‘pligini sifatlaydi. عِنْدَ اللِّقَاءِ bu yerda dushman bilan to‘qnash kelish payti."},
{num:455,time:"00:39:30,880 --> 00:39:34,740",arabic:"فَالْجَنَّةُ عِنْدَ مَوْضِعِ سُيُوفِكُمْ.",segs:[{ar:"فَالْجَنَّةُ",uz:"jannat"},{ar:"عِنْدَ مَوْضِعِ سُيُوفِكُمْ",uz:"qilichlaringiz tushadigan joydadir"}],full_uz:"Jannat qilichlaringiz tushadigan joydadir.",note:"مَوْضِعٌ — «joy, o‘rin»; سُيُوفٌ — سَيْفٌ («qilich»)ning ko‘pligi."},
{num:456,time:"00:39:34,740 --> 00:39:39,380",arabic:"فَأَعْمِلُوهَا فِي عَدُوِّ اللَّهِ وَعَدُوِّكُمْ.",segs:[{ar:"فَأَعْمِلُوهَا",uz:"bas, ularni ishga solinglar"},{ar:"فِي عَدُوِّ اللَّهِ وَعَدُوِّكُمْ",uz:"Allohning va o‘zingizning dushmaningizga qarshi"}],full_uz:"Bas, ularni Allohning va o‘zingizning dushmaningizga qarshi ishga solinglar.",note:"أَعْمَلَ — «ishga soldi, qo‘lladi». هَا oldingi banddagi qilichlarga qaytadi."},
{num:457,time:"00:39:39,380 --> 00:39:43,820",arabic:"يَا خَيْلَ اللَّهِ ارْكَبِي!",segs:[{ar:"يَا خَيْلَ اللَّهِ",uz:"ey Allohning otliq lashkari"},{ar:"ارْكَبِي",uz:"otlan!"}],full_uz:"Ey Allohning otliq lashkari, otlan!",note:"خَيْلٌ — otlar yoki otliq lashkarni bildiruvchi jamlovchi so‘z. ارْكَبِي shu so‘zga mos birlik muannas buyruq shaklida kelgan."}
];

if (typeof module !== "undefined" && module.exports) {
    module.exports = lessons;
}
